    class BudgetParams
    {
        public double P, CavoTx, AccTx, GAnt, PreLoss, PreGain, PostLoss, TvGain, Mds, Nf, GroundOn, GroundH = 10, TvCavo = 0.5, TvNf = 1.5, Tant = 250;
        public int NAnt;
        // schema dell'impianto (v27): cavi scelti dal database, lunghezze, relè, transverter, modo
        public double CavoAnt = -1, LenAnt = 3, Rele = 0.3, CavoPa = -1, LenPa = 30, CavoDis = -1, LenDis = 30, TvOn = 0, TvGainSet = 25, Modo = 0, SnReq = -25, TvMod = -1;
        public double LossAnt, LossPa, LossDis;   // perdite dei cavi calcolate alla frequenza della banda
        // antenna a disco (Budget EME dischi): diametro (m), efficienza (%), f/D, montatura (0 Az-El, 1 polare); con Disco = 1
        // il guadagno è quello del disco (PE1RKI: G = 10·log[η·(π·D/λ)²]) e il numero di antenne vale 1
        public double Disco = 0, DiscoD = 3.0, DiscoEff = 60, DiscoFD = 0.40, DiscoMont = 0;
        // tipo di disco: 0 primo fuoco, 1 offset (D = apertura proiettata, cioè l'asse minore: W2IMU, Crawford Hill TR #18;
        // senza l'oscuramento dell'illuminatore, ≥ 0,5 dB in più a parità di efficienza d'illuminazione)
        public double DiscoTipo = 0;
        // stima della temperatura d'antenna del disco (v1.9.4): illuminazione al bordo (dB, comprese le perdite di spazio),
        // rete della superficie: diametro del filo e passo (mm), filo 0 = superficie piena
        public double DiscoBordo = 10, DiscoFilo = 0, DiscoPasso = 8;
        // catena completa: stadi del preamplificatore (1 o 2), uscita TX del transverter (W), pilotaggio richiesto dal PA (W),
        // cavo tra transverter e PA
        public double PreStadi = 1, TvPtx = 10, PaPin = 10, CavoTv = -1, LenTv = 2, LossTv;
        // connettori stimati (consiglio pratico di NJ9R: circa 1 dB ogni 8 – 10 connettori, 0,11 dB ciascuno):
        // in trasmissione quelli tra PA e antenna, in ricezione quelli tra antenna e preamplificatore, contati a parte
        public const double DbConnettore = 0.11;
        public double ConnTx = 0, ConnRx = 0, LossConn, LossConnRx;

        public static double Freq = 144;   // frequenza della banda corrente, per le perdite dei cavi

        public static readonly string[] Keys = { "p", "cavotx", "acctx", "gant", "nant", "preloss", "pregain", "postloss", "tvgain", "mds", "nf", "groundon", "groundh", "tvcavo", "tvnf", "tant",
            "cavoant", "lenant", "rele", "cavopa", "lenpa", "cavodis", "lendis", "tvon", "tvgainset", "modo", "snreq", "tvmod", "conntx", "connrx",
            "disco", "discod", "discoeff", "discofd", "discomont", "discotipo", "prestadi", "tvptx", "papin", "cavotv", "lentv",
            "discobordo", "discofilo", "discopasso" };

        // Guadagno del disco (PE1RKI, "Dish calcs."): G = 10·log[η·(π·D/λ)²] in dBi; dBd = dBi − 2,15
        public static double GuadagnoDisco(double dM, double effPct, double fMHz)
        {
            double lam = 299.792458 / Math.Max(1, fMHz);
            return 10.0 * Math.Log10(Math.Max(1e-6, effPct / 100.0) * Math.Pow(Math.PI * Math.Max(0.05, dM) / lam, 2));
        }
        // apertura a −3 dB del disco: regola pratica 70·λ/D (gradi)
        public static double AperturaDisco(double dM, double fMHz) { return 70.0 * (299.792458 / Math.Max(1, fMHz)) / Math.Max(0.05, dM); }
        // Frazione della potenza dell'illuminatore che passa oltre il bordo del disco (ricaduta, "spillover").
        // Illuminatore ideale cos^q(θ) (W1GHZ, Microwave Antenna Book, cap. 4 e 6): semiangolo del bordo
        // θ0 = 2·atan[1/(4·f/D)], perdita di spazio al bordo 20·log[1/cos²(θ0/2)] dB, il resto dell'illuminazione al
        // bordo (bordoDb) è il calo dell'illuminatore, da cui q; la potenza oltre θ0 nel semispazio vale cos^(q+1)(θ0).
        public static double Ricaduta(double fd, double bordoDb)
        {
            double t0 = 2.0 * Math.Atan(1.0 / (4.0 * Math.Max(0.1, fd)));
            double spazio = 20.0 * Math.Log10(1.0 / Math.Pow(Math.Cos(t0 / 2.0), 2));
            double ill = Math.Max(0.5, bordoDb - spazio);
            double ct = Math.Cos(Math.Min(t0, 89.0 * Math.PI / 180.0));
            double q = (ill / 10.0) / -Math.Log10(ct);
            return Math.Pow(ct, q + 1.0);
        }
        // Potenza che passa attraverso una rete a maglie quadrate (Mumford 1961, griglia di fili paralleli, la stessa
        // formula di EMECalc di VK3UM): X = (s/λ)·ln[s/(π·d)], |T|² = 4X²/(1 + 4X²); 0 con filo 0 (superficie piena)
        public static double TrasmissioneRete(double filoMm, double passoMm, double fMHz)
        {
            if (filoMm <= 0 || passoMm <= filoMm) return 0;
            double lam = 299792.458 / Math.Max(1, fMHz);   // mm
            double x = passoMm / lam * Math.Log(passoMm / (Math.PI * filoMm));
            return 4 * x * x / (1 + 4 * x * x);
        }
        // Stima della temperatura d'antenna del disco: cielo freddo di riferimento nel fascio, ricaduta oltre il bordo
        // e rete che vedono il terreno a 290 K (come EMECalc di VK3UM, G3LTF)
        public void TantDisco(double fMHz, double tsky, out double tCielo, out double tRic, out double tRete, out double spill, out double tr)
        {
            spill = Ricaduta(DiscoFD, DiscoBordo);
            tr = TrasmissioneRete(DiscoFilo, DiscoPasso, fMHz);
            tRic = spill * 290.0;
            tRete = tr * (1 - spill) * 290.0;
            tCielo = tsky * (1 - spill) * (1 - tr);
        }
        // apertura a −3 dB di yagi e gruppi di yagi dal guadagno totale: regola di Kraus G = 41253 / θ² corretta del fattore 0,93
        // trovato da W4RNL con le simulazioni NEC delle yagi lunghe (lo stesso valore di YA-MS)
        public const double CorrFascioYagi = 0.93;
        public static double FascioYagi(double gDbi) { return CorrFascioYagi * Math.Sqrt(41253.0 / Math.Pow(10.0, gDbi / 10.0)); }
        // larghezza del fascio unica per tutto il programma: disco → 70·λ/D (IZ0JNY), yagi → 0,93·√(41253/G)
        public double Fascio(double fMHz)
        {
            if (Disco > 0.5) return AperturaDisco(DiscoD, fMHz);
            return FascioYagi(GAnt + 10.0 * Math.Log10(Math.Max(1, NAnt)));
        }

        // valori iniziali di una stazione a disco (432, 902, 1296 MHz): disco da 3 m al 60 %, preampli a due stadi al fuoco,
        // transverter da 10 W che pilota un PA da 500 W
        public static BudgetParams DefaultDisco(int band)
        {
            BudgetParams b = Default(band);
            b.Disco = 1; b.DiscoD = 3.0; b.DiscoEff = 60; b.DiscoFD = 0.40; b.DiscoMont = 0;
            b.NAnt = 1; b.P = 500; b.Nf = 0.35; b.PreGain = 30; b.PreStadi = 2;
            b.Tant = band == 432 ? 60 : (band == 902 ? 45 : 40);
            b.Rele = 0.2; b.LenAnt = 1;
            b.CavoPa = CaviDb.Indice("Ecoflex 15"); b.LenPa = 3;
            b.CavoDis = CaviDb.Indice("Ecoflex 15"); b.LenDis = 25;
            b.TvOn = 1; b.TvGainSet = 20; b.TvNf = 1.0; b.TvMod = -1; b.TvPtx = 10; b.PaPin = 10;
            b.CavoTv = CaviDb.Indice("RG-213/U"); b.LenTv = 2;
            double fs = Freq;
            Freq = band;
            b.Calcola();
            Freq = fs;
            return b;
        }

        // Transverter della tabella del manuale (§ 3.7.2) con figura di rumore e guadagno dichiarati dai costruttori;
        // l'ultima voce della tendina è "personalizzato" (TvMod = -1)
        public static readonly string[] TvNome = { "Kuhne (DB6NT) MKU 144 G2", "Kuhne (DB6NT) TR 144 H +40", "Q5 Signal L144-28M", "HA1YA ME2T-PRO-II / ME2HT-PRO-II", "UR3LMZ 144/28 MHz (UX4LA)", "Elecraft XV144", "S53WW Javornik 144/14", "S53RM Murka 144/14", "Kuhne (DB6NT) TR 144 PRO", "Kuhne (DB6NT) TR 144 H", "Kuhne (DB6NT) 144TR7300" };
        public static readonly double[] TvNfMod = { 0.9, 1.2, 1.0, 1.0, 1.0, 1.0, 0.9, 5.0, 1.4, 0.8, 0.7 };
        public static readonly double[] TvGMod = { 25, 25, 20, 25, 20, 25, 25, 21, 25, 25, 17 };

        // Modi digitali e S/N richiesto in 2500 Hz (Guida di WSJT-X, § 7.1; FT4 = FT8 + 3,5 dB;
        // Q65: "Quick-Start Guide to Q65", K1JT e altri, 3 aprile 2021, soglia 50 % senza AP).
        // I nuovi modi vanno aggiunti in fondo: l'indice del modo è salvato nelle impostazioni.
        // Q65-60B e Q65-60C: senza spread stessa sensibilità del 60A (stessa durata del simbolo, manuale TEORIA § 1.12).
        public static readonly string[] ModiNome = { "JT65", "JT9", "JT4", "FT8", "FT4", "Q65-60A", "WSPR", "Q65-30A", "Q65-120A", "Q65-15A", "Q65-300A", "Q65-60B", "Q65-60C" };
        public static readonly double[] ModiSn = { -25, -27, -23, -20, -16.5, -27.6, -31, -24.8, -30.8, -22.2, -33.8, -27.6, -27.6 };
        public static readonly bool[] ModiDaVerificare = { false, false, false, false, false, false, false, false, false, false, false, false, false };
        // Nella tendina solo i modi con periodo di 60 secondi (voce → indice del modo): JT65, Q65-60A, Q65-60B, Q65-60C.
        // Gli altri restano nell'elenco solo per leggere le impostazioni vecchie: un modo non più in tendina diventa JT65.
        public static readonly int[] ModiOrdine = { 0, 5, 11, 12 };
        public static int ModoDaVoce(int voce) { return voce >= 0 && voce < ModiOrdine.Length ? ModiOrdine[voce] : -1; }
        public static int VoceDaModo(int modo) { return Array.IndexOf(ModiOrdine, modo); }

        // Temperatura d'antenna indicativa per banda (da sostituire con il valore Ta delle tabelle VE7BQH)
        public static double TantPredefinita(int band)
        {
            switch (band)
            {
                case 50: return 3500; case 70: return 1500; case 144: return 250; case 222: return 120; case 432: return 50; case 902: return 45; case 1296: return 40;
                default: return 150;
            }
        }

        public static BudgetParams Default(int band)
        {
            BudgetParams b = new BudgetParams();
            b.PreLoss = 0.3; b.PreGain = 20; b.PostLoss = 3; b.TvGain = 0; b.Mds = -130;
            b.AccTx = 0.5;
            b.Tant = TantPredefinita(band);
            b.CavoAnt = CaviDb.Indice("Hyperflex 13"); b.CavoPa = CaviDb.Indice("Ecoflex 10 Plus"); b.CavoDis = b.CavoPa;
            b.LenAnt = 3; b.LenPa = 30; b.LenDis = 30; b.Rele = 0.3;
            if (band == 50) { b.P = 1000; b.CavoTx = 1.0; b.GAnt = 12.0; b.NAnt = 1; b.Nf = 1.0; }
            else if (band == 70) { b.P = 400; b.CavoTx = 1.0; b.GAnt = 14.0; b.NAnt = 2; b.Nf = 0.8; }
            else if (band == 222) { b.P = 1000; b.CavoTx = 1.5; b.GAnt = 18.5; b.NAnt = 4; b.Nf = 0.4; }
            else if (band == 432) { b.P = 500; b.CavoTx = 2.0; b.GAnt = 21.0; b.NAnt = 4; b.Nf = 0.4; b.CavoAnt = CaviDb.Indice("LDF4-50A (Heliax 1/2\")"); b.CavoPa = b.CavoAnt; b.CavoDis = b.CavoAnt; }
            else if (band == 902) { b.P = 500; b.CavoTx = 2.0; b.GAnt = 20.0; b.NAnt = 4; b.Nf = 0.35; b.CavoAnt = CaviDb.Indice("LDF4-50A (Heliax 1/2\")"); b.CavoPa = b.CavoAnt; b.CavoDis = b.CavoAnt; b.LenAnt = 2; }
            else if (band == 1296) { b.P = 500; b.CavoTx = 2.0; b.GAnt = 21.0; b.NAnt = 4; b.Nf = 0.3; b.CavoAnt = CaviDb.Indice("LDF4-50A (Heliax 1/2\")"); b.CavoPa = b.CavoAnt; b.CavoDis = b.CavoAnt; b.LenAnt = 2; }
            else { b.P = 1000; b.CavoTx = 1.5; b.GAnt = 17.0; b.NAnt = 4; b.Nf = 0.5; }
            double fs = Freq;
            Freq = band;
            b.Calcola();
            Freq = fs;
            return b;
        }

        static double PerditaCavo(double idx, double len)
        {
            int i = (int)Math.Round(idx);
            if (i < 0 || i >= CaviDb.Elenco.Count) return 0;
            return CaviDb.Elenco[i].Perdita(Freq, len);
        }

        // Perdite effettive dalle scelte dello schema: TX = cavo PA-relè + relè + cavo antenna; RX = cavo antenna + relè prima del preampli
        public void Calcola()
        {
            LossAnt = PerditaCavo(CavoAnt, LenAnt);
            LossPa = PerditaCavo(CavoPa, LenPa);
            LossDis = PerditaCavo(CavoDis, LenDis);
            LossTv = PerditaCavo(CavoTv, LenTv);
            if (Disco > 0.5) { GAnt = GuadagnoDisco(DiscoD, DiscoEff, Freq); NAnt = 1; }
            LossConn = Math.Max(0, ConnTx) * DbConnettore;
            LossConnRx = Math.Max(0, ConnRx) * DbConnettore;
            CavoTx = LossPa;
            AccTx = Rele + LossAnt + LossConn;
            PreLoss = LossAnt + Rele + LossConnRx;
            PostLoss = LossDis;
            TvGain = TvOn > 0.5 ? TvGainSet : 0;
        }

        public double SnRichiesto { get { return SnReq; } }
        public string NomeModo
        {
            get
            {
                int m = (int)Math.Round(Modo);
                return m >= 0 && m < ModiNome.Length ? ModiNome[m] : Lang.T("personalizzato");
            }
        }

