            b.DiscoBordo = (double)u.DiscoBordo.Value; b.DiscoFilo = (double)u.DiscoFilo.Value; b.DiscoPasso = (double)u.DiscoPasso.Value;
            b.DiscoMont = Math.Max(0, u.DiscoMont.SelectedIndex);
            b.DiscoTipo = u.DiscoTipo != null ? Math.Max(0, u.DiscoTipo.SelectedIndex) : 0;
