        float fontFactor = 1f;
        int S(int px) { return (int)Math.Round(px * scale * fontFactor); }
        float S(float px) { return px * scale * fontFactor; }

        // ---------- Linguetta 2: budget EME ----------

        TabControl tabs;
        ComboBox cmbBand, cmbBw, cmbTau, cmbRos;
