            bar.Controls.Add(L(Lang.T("Istante (UTC)"))); bar.Controls.Add(dtpB); bar.Controls.Add(bNow); bar.Controls.Add(bRow);
            bar.Controls.Add(chkPol);
            chkEco = new Spunta();
