            cmbTau.Width = S(78);
            cmbTau.SelectedIndexChanged += (s, e) => { RecalcBudget(); if (!caricamento) SaveSettings(); };
            tip.SetToolTip(cmbTau, Lang.T("Tempo d'integrazione τ") + "\u0001" + Lang.T("Tempo su cui si media il rumore misurato (s): con la banda passante dà il ΔT minimo misurabile nella prova della stazione con il fattore Y, ΔT = Tsys/√(B·τ) (Antenna Engineering Handbook, 4ª ed., eq. 41-21)."));
            bar.Controls.Add(L(Lang.T("Integrazione τ"))); bar.Controls.Add(cmbTau);
            // ROS dell'illuminatore o dell'antenna (AEH 4ª ed., eq. 41-19): riduce lo Y previsto del fattore (1 − ρ)
            cmbRos = new Tendina();
            cmbRos.DropDownStyle = ComboBoxStyle.DropDownList;
            foreach (double rv in RosValori) cmbRos.Items.Add(rv.ToString("0.0", Lang.Cultura) + ":1");
            cmbRos.SelectedIndex = 0;
            cmbRos.Width = S(78);
            cmbRos.SelectedIndexChanged += (s, e) => { RecalcBudget(); if (!caricamento) SaveSettings(); };
            tip.SetToolTip(cmbRos, Lang.T("ROS dell'antenna") + "\u0001" + Lang.T("Rapporto di onde stazionarie dell'antenna o dell'illuminatore visto dal preamplificatore, per la prova della stazione con il fattore Y. Il disadattamento riflette una parte ρ = ((ROS − 1)/(ROS + 1))² del rumore della sorgente, che non arriva al ricevitore: lo Y previsto scende (Antenna Engineering Handbook, 4ª ed., eq. 41-19). La parte ρ·TR del rumore che esce dal ricevitore e torna riflessa non si conosce e resta un errore sistematico."));
            bar.Controls.Add(L(Lang.T("ROS"))); bar.Controls.Add(cmbRos);
            // CALCOLI APPROFONDITI: la stessa casella della schermata principale, riquadro viola in alto a destra
            chkComplessiB = new Pillola(Lang.T("CALCOLI APPROFONDITI"), StilePillola.Casella, Color.FromArgb(91, 63, 168), new Font(Lang.FontUi, 9.5F * fontFactor, FontStyle.Bold));
            chkComplessiB.Nota = "⇄ " + Lang.T("Posizione live e +- 24h");
            chkComplessiB.Aggiorna();
            chkComplessiB.Anchor = AnchorStyles.Right | AnchorStyles.Top;
            chkComplessiB.Margin = new Padding(S(6), S(4), S(10), S(4));
            tip.SetToolTip(chkComplessiB, Lang.T("CALCOLI APPROFONDITI") + "\u0001" + Lang.T("Casella sincronizzata: è la stessa casella CALCOLI APPROFONDITI che trovi nel riquadro verde dell'S/N stimato, nella linguetta Posizione live e +- 24h; se la cambi qui cambia anche là, e viceversa. Spenta, il Budget EME passa alla modalità semplificata e le linguette Rumore solare, Export in Excel dei calcoli e Controllo dei calcoli diventano grigie."));
            chkComplessiB.CheckedChanged += (s, e) => { if (chkComplessi.Checked != chkComplessiB.Checked) chkComplessi.Checked = chkComplessiB.Checked; };
            root.Controls.Add(bar, 0, 0);
            root.Controls.Add(chkComplessiB, 1, 0);
            root.SetColumnSpan(chkComplessiB, 2);

            // colonna sinistra: stazioni, indicatori, tabella
            TableLayoutPanel sx = new TableLayoutPanel();
            sx.Dock = DockStyle.Fill;
            sx.ColumnCount = 1;
            sx.RowCount = 3;
            TableLayoutPanel st = new TableLayoutPanel();
            st.Dock = DockStyle.Fill;
            st.ColumnCount = 2;
            st.RowCount = 1;
            st.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50f));
            st.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 50f));
            st.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            st.Margin = new Padding(0);
            st.Controls.Add(BuildBudgetStation(Lang.T("La mia stazione"), Color.FromArgb(31, 111, 209), out bMe), 0, 0);
            st.Controls.Add(BuildBudgetStation(Lang.T("Stazione DX"), Color.FromArgb(217, 119, 6), out bDx), 1, 0);
            sx.RowStyles.Add(new RowStyle(SizeType.Absolute, Math.Max(S(196), StazAltezza(bMe))));
            budgetSx = sx;
            sx.RowStyles.Add(new RowStyle(SizeType.Absolute, S(170)));
            sx.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            sx.Margin = new Padding(0);
            sx.Controls.Add(st, 0, 0);
            pnlKpi = new PannelloDisegno();
            pnlKpi.Dock = DockStyle.Fill;
            pnlKpi.Paint += DisegnaKpi;
            sx.Controls.Add(pnlKpi, 0, 1);

            lvB = new DBListView();
            lvB.Dock = DockStyle.Fill;
            lvB.View = View.Details;
            lvB.FullRowSelect = true;
            lvB.GridLines = true;
            lvB.HeaderStyle = ColumnHeaderStyle.Nonclickable;
            lvB.Columns.Add(Lang.T("Grandezza"), S(300));
            lvB.Columns.Add(Lang.T("Io trasmetto → il DX riceve"), S(230));
            lvB.Columns.Add(Lang.T("Il DX trasmette → io ricevo"), S(230));
            // la tabella è disegnata dal programma (bozzetto 7): lvB raccoglie solo le righe
            pnlTabHost = new Panel();
            pnlTabHost.Dock = DockStyle.Fill;
            pnlTabHost.AutoScroll = true;
            pnlTabB = new PannelloDisegno();
            pnlTabB.Location = new Point(0, 0);
            pnlTabB.Paint += DisegnaTabB;
            pnlTabHost.Controls.Add(pnlTabB);
            pnlTabHost.Resize += (s, e) => DimensionaTabB();
            sx.Controls.Add(pnlTabHost, 0, 2);
            root.Controls.Add(sx, 0, 1);

            // colonna destra: schema dell'impianto di trasmissione e ricezione
            pnlImpHost = new Panel();
            pnlImpHost.Dock = DockStyle.Fill;
            pnlImpHost.AutoScroll = true;
            pnlImpHost.Resize += (s, e) => PosizionaSchema();
            pnlImp = new PannelloDisegno();
            pnlImp.Location = new Point(0, 0);
            pnlImp.Size = new Size(S(530), S(1010));   // poi adattato al riquadro da PosizionaSchema
            pnlImp.Paint += DisegnaImpianto;
            pnlImp.MouseClick += (s, e) =>
            {
                foreach (KeyValuePair<RectangleF, int> kv in impZone)
                    if (kv.Key.Contains(e.Location)) { impSel = kv.Value; MostraSchema(); pnlImp.Invalidate(); break; }
            };
            pnlImp.MouseMove += (s, e) =>
            {
                bool su = false;
                foreach (KeyValuePair<RectangleF, int> kv in impZone) if (kv.Key.Contains(e.Location)) su = true;
                pnlImp.Cursor = su ? Cursors.Hand : Cursors.Default;
            };
            foreach (BudgetUi u in new BudgetUi[] { bMe, bDx })
                foreach (Control c in u.Schema) pnlImp.Controls.Add(c);
            pnlImpHost.Controls.Add(pnlImp);
            root.Controls.Add(pnlImpHost, 2, 1);

            // separatore tra la colonna sinistra e lo schema: si trascina con il mouse, le due parti si ridisegnano da sole
            Panel sep = new Panel();
            sep.Dock = DockStyle.Fill;
            sep.Margin = new Padding(0);
            sep.Cursor = Cursors.VSplit;
            tip.SetToolTip(sep, Lang.T("Trascina per allargare o stringere lo schema dell'impianto; doppio clic per tornare alla larghezza iniziale."));
            bool trascina = false; int x0 = 0, w0 = 0;
            Action<int> applica = w =>
            {
                int max = Math.Max(S(300), root.ClientSize.Width - S(420));
                w = Math.Max(S(300), Math.Min(max, w));
                root.ColumnStyles[2].Width = w;
            };
            sep.MouseDown += (s, e) => { if (e.Button == MouseButtons.Left) { trascina = true; x0 = Cursor.Position.X; w0 = (int)root.ColumnStyles[2].Width; sep.Capture = true; sep.Invalidate(); } };
            sep.MouseMove += (s, e) =>
            {
                if (!trascina) return;
                applica(w0 - (Cursor.Position.X - x0));
                budgetSchemaLarg = (int)Math.Round(root.ColumnStyles[2].Width * 100.0 / S(100));   // la scelta dell'utente, in unità logiche
            };
            sep.MouseUp += (s, e) => { if (trascina) { trascina = false; sep.Capture = false; sep.Invalidate(); if (!caricamento) SaveSettings(); } };
            sep.DoubleClick += (s, e) => { budgetSchemaLarg = 560; applica(S(560)); if (!caricamento) SaveSettings(); };
            sep.Paint += (s, e) =>
            {
                Graphics g = e.Graphics;
                g.SmoothingMode = SmoothingMode.AntiAlias;
                float cx = sep.Width / 2f;
                using (Pen pl = new Pen(trascina ? Color.FromArgb(124, 58, 237) : (Tema.Scuro ? Tema.Linea : Color.FromArgb(200, 206, 216)), trascina ? S(3) : S(2)))
                    g.DrawLine(pl, cx, S(4), cx, sep.Height - S(4));
                // maniglia al centro: tre puntini
                using (Brush b = new SolidBrush(Tema.Scuro ? Color.FromArgb(160, 170, 185) : Color.FromArgb(110, 120, 135)))
                    for (int k = -1; k <= 1; k++) g.FillEllipse(b, cx - S(2.5f), sep.Height / 2f + k * S(9) - S(2.5f), S(5), S(5));
            };
            sep.Resize += (s, e) => sep.Invalidate();
            root.Controls.Add(sep, 1, 1);
            root.Resize += (s, e) => { if (root.ClientSize.Width > 0) applica(S(budgetSchemaLarg)); };

            lblBNote = new Label();   // la nota ora è nel fumetto della tabella
            tip.SetToolTip(pnlTabB, Lang.T("Perdita di tratta: equazione radar con riflettività lunare 0,065 (Evans & Hagfors 1966) e distanze topocentriche delle due stazioni nell'istante scelto. Guadagno totale = G + 10·log10(N) (accoppiamento ideale). Il margine sul MDS confronta il segnale all'ingresso della radio con il suo MDS: non tiene conto del rumore di cielo e del preamplificatore (vedi Dgrd nella prima linguetta)."));

            tp.Controls.Add(root);
            PosizionaSchema();
            MostraSchema();
            CaricaBanda(curBand);
        }

        // ---- schema dell'impianto: riquadri calcolati dai testi (si adattano a caratteri dal 90 al 150 %)
        RectangleF RAnt, RCavoAnt, RRele, RReleBox, RTx, RLna, RPre, RDis, RTv, RCavetti, RRadio;
        string impTv = "";
        bool impTvScarso;
        float impRh, impXl;
        TableLayoutPanel budgetRoot;
        int budgetSchemaLarg = 560;   // larghezza dello schema dell'impianto nel Budget EME (unità logiche, separatore trascinabile)
        // riquadri dello schema (0 cavo antenna, 1 relè, 2 TX, 3 preampli, 4 discesa): true = etichetta sopra la casella,
        // quando etichetta e casella non stanno sulla stessa riga (lingue con testi lunghi o finestra stretta)
        readonly bool[] impPila = new bool[5];
        int Linee(int box, int n) { return impPila[box] ? 2 * n : n; }
        int impRadioRighe = 1;
        bool impRadioUna = true;

        bool ModoPersonalizzato(BudgetUi u) { return u != null && u.Modo.SelectedIndex == u.Modo.Items.Count - 1; }

        void PosizionaSchema()
        {
            if (pnlImp == null || pnlImpHost == null || bMe == null || bDx == null) return;
            BudgetUi u = impSel == 0 ? bMe : bDx;
            // si lascia sempre il posto della barra di scorrimento verticale: così non compare mai quella orizzontale
            int W = Math.Max(S(400), pnlImpHost.ClientSize.Width - 2 - (pnlImpHost.VerticalScroll.Visible ? 0 : SystemInformation.VerticalScrollBarWidth));
            float avail = pnlImpHost.ClientSize.Height - 2;
            using (Graphics g = pnlImp.CreateGraphics())
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fl = FontPx(Lang.FontUi, S(13), false))
            using (Font fr = FontPx(Lang.FontUi, S(12), true))
            {
                float pad = S(10);
                float rh = Math.Max(S(27), Math.Max(u.P.Height, u.CavoAnt.Height) + S(4));
                impRh = rh;
                int fn = S(84), fc = S(156), fm = S(170);
                Func<string, float> Lw = t => g.MeasureString(t, fl).Width;
                Func<string, float> Tw = t => g.MeasureString(t, ft).Width;
                // larghezza dei riquadri di destra: etichetta + casella, titolo
                float wR = Math.Max(Lw(Lang.T("Tipo")) + fc, Lw(Lang.T("Lunghezza")) + fn);
                foreach (string t in new string[] { Lang.T("Perdita di inserzione"), Lang.T("Connettori in TX"), Lang.T("Connettori in RX"), Lang.T("Guadagno"), Lang.T("Figura di rumore"), Lang.T("Cavetti fino alla radio"), Lang.T("Stadi") })
                    wR = Math.Max(wR, Lw(t) + fn);
                wR += 2 * pad + S(14);
                foreach (string t in new string[] { Lang.T("CAVO ANTENNA – RELÈ") + "  " + Lang.T("TX e RX"), Lang.T("RELÈ COASSIALE TX / RX"), Lang.T("PREAMPLIFICATORE"), Lang.T("CAVO DI DISCESA") })
                    wR = Math.Max(wR, Tw(t) + 2 * pad);
                wR = Math.Min(Math.Max(wR, W * 0.38f), W * 0.62f);
                float wTx = Math.Max(Math.Max(Lw(Lang.T("Potenza in uscita")), Lw(Lang.T("Pilotaggio richiesto"))) + fn, Math.Max(Lw(Lang.T("Cavo PA – relè")) + fc, Lw(Lang.T("Lunghezza")) + fn)) + 2 * pad + S(14);
                wTx = Math.Max(wTx, Tw(Lang.T("TRASMETTITORE · PA")) + 2 * pad);
                float spazio = W - S(16) - wR - S(80);   // tra il riquadro TX e quelli di destra passa la linea con il relè
                if (wTx > spazio) wTx = Math.Max(S(150), spazio);
                float xMin = S(8) + wTx + S(20), xMax = W - S(8) - wR - S(40);
                impXl = xMax >= xMin ? (xMin + xMax) / 2f : xMax;
                float xR = W - S(8) - wR;
                Func<string, float, float> Fh = (t, w) => string.IsNullOrEmpty(t) ? 0f : g.MeasureString(t, fr, (int)Math.Max(10, w - 2 * pad)).Height + S(4);
                // per ogni riquadro: etichetta e casella sulla stessa riga solo se ci stanno
                Func<string[], int[], float> Serve = (et, cw) =>
                {
                    float m = 0;
                    for (int k = 0; k < et.Length; k++) m = Math.Max(m, Lw(et[k]) + S(12) + cw[k]);
                    return m + 2 * pad;
                };
                impPila[0] = Serve(new string[] { Lang.T("Tipo"), Lang.T("Lunghezza") }, new int[] { fc, fn }) > wR;
                impPila[1] = Serve(new string[] { Lang.T("Perdita di inserzione"), Lang.T("Connettori in TX"), Lang.T("Connettori in RX") }, new int[] { fn, fn, fn }) > wR;
                impPila[2] = Serve(new string[] { Lang.T("Potenza in uscita"), Lang.T("Pilotaggio richiesto"), Lang.T("Cavo PA – relè"), Lang.T("Lunghezza") }, new int[] { fn, fn, fc, fn }) > wTx;
                impPila[3] = Serve(new string[] { Lang.T("Stadi"), Lang.T("Guadagno"), Lang.T("Figura di rumore") }, new int[] { fc, fn, fn }) > wR;
                impPila[4] = Serve(new string[] { Lang.T("Tipo"), Lang.T("Lunghezza") }, new int[] { fc, fn }) > wR;
                float hCa = S(26) + Linee(0, 2) * rh + Fh(impCavoAnt, wR) + S(6);
                float hRe = S(26) + Linee(1, 3) * rh + Fh(impConn, wR) + S(6);
                float hTx = S(26) + Linee(2, 4) * rh + Fh(impTx, wTx) + S(6);
                float hPre = S(26) + Linee(3, 3) * rh + Fh(impPre, wR) + S(6);
                float hDis = S(26) + Linee(4, 2) * rh + Fh(impDis, wR) + S(6);
                float hTv = S(32) + 4 * rh + Fh(impTv, W - S(16)) + S(6);
                float hCav = rh + S(14);
                impRadioUna = 2 * pad + Lw(Lang.T("MDS della radio")) + fn + S(24) + Lw(Lang.T("Modo · S/N richiesto")) + fm + S(10) <= W - S(16);
                impRadioRighe = (impRadioUna ? 1 : 2) + (ModoPersonalizzato(u) ? 1 : 0);
                float hRad = S(26) + impRadioRighe * rh + Fh(impRadio, W - S(16)) + S(6);
                float hAnt = S(84);
                float extra = 0;
                for (int giro = 0; giro < 2; giro++)
                {
                    RAnt = new RectangleF(S(8), S(44), W - S(16), hAnt);
                    RCavoAnt = new RectangleF(xR, RAnt.Bottom + S(10) + extra, wR, hCa);
                    RReleBox = new RectangleF(xR, RCavoAnt.Bottom + S(14) + extra, wR, hRe);
                    RRele = new RectangleF(impXl - S(30), RReleBox.Top, S(60), S(60));
                    float relFondo = Math.Max(RRele.Bottom, RReleBox.Bottom);
                    RTx = new RectangleF(S(8), relFondo + S(44) + extra, wTx, hTx);
                    RPre = new RectangleF(xR, Math.Max(RTx.Top + S(64), relFondo + S(60)), wR, hPre);
                    RLna = new RectangleF(impXl - S(22), RPre.Top + (hPre - S(40)) / 2f, S(44), S(40));
                    RDis = new RectangleF(xR, Math.Max(RPre.Bottom, RTx.Bottom) + S(50) + extra, wR, hDis);
                    RTv = new RectangleF(S(8), RDis.Bottom + S(22) + extra, W - S(16), hTv);
                    RCavetti = new RectangleF(xR, RTv.Bottom + S(22) + extra, wR, hCav);
                    RRadio = new RectangleF(S(8), RCavetti.Bottom + S(22) + extra, W - S(16), hRad);
                    float tot = RRadio.Bottom + S(10);
                    if (giro == 0 && avail > tot) extra = (avail - tot) / 7f;   // lo schema riempie tutto il riquadro
                    else break;
                }
                int H = (int)Math.Max(RRadio.Bottom + S(10), avail);
                if (pnlImp.Size != new Size(W, H)) pnlImp.Size = new Size(W, H);

                foreach (BudgetUi v in new BudgetUi[] { bMe, bDx })
                {
                    Campo(v.Tant, RAnt.Right - fn, RAnt.Top + S(18), fn, rh);
                    Riga2(v.CavoAnt, RCavoAnt, 0, fc, 0); Riga2(v.LenAnt, RCavoAnt, 1, fn, 0);
                    Riga2(v.Rele, RReleBox, 0, fn, 1); Riga2(v.ConnTx, RReleBox, 1, fn, 1); Riga2(v.ConnRx, RReleBox, 2, fn, 1);
                    Riga2(v.P, RTx, 0, fn, 2); Riga2(v.PaPin, RTx, 1, fn, 2); Riga2(v.CavoPa, RTx, 2, fc, 2); Riga2(v.LenPa, RTx, 3, fn, 2);
                    Riga2(v.PreStadi, RPre, 0, fc, 3); Riga2(v.PreGain, RPre, 1, fn, 3); Riga2(v.Nf, RPre, 2, fn, 3);
                    Riga2(v.CavoDis, RDis, 0, fc, 4); Riga2(v.LenDis, RDis, 1, fn, 4);
                    v.TvOn.Location = new Point((int)(RTv.Left + pad), (int)(RTv.Top + S(6)));
                    float xm = RTv.Left + pad + Lw(Lang.T("Modello")) + S(12);
                    Campo(v.TvMod, xm, RTv.Top + S(30), (int)Math.Min(S(330), RTv.Right - pad - xm), rh);
                    Campo(v.TvGain, RTv.Left + pad + Lw(Lang.T("Guadagno")) + S(12), RTv.Top + S(30) + rh, fn, rh);
                    Campo(v.TvNf, RTv.Right - pad - fn, RTv.Top + S(30) + rh, fn, rh);
                    // trasmissione: uscita del transverter e cavo verso il PA
                    Campo(v.TvPtx, RTv.Left + pad + Lw(Lang.T("Uscita TX")) + S(12), RTv.Top + S(30) + 2 * rh, fn, rh);
                    Campo(v.LenTv, RTv.Right - pad - fn, RTv.Top + S(30) + 2 * rh, fn, rh);
                    Campo(v.CavoTv, RTv.Right - pad - fc, RTv.Top + S(30) + 3 * rh, fc, rh);
                    Campo(v.TvCavo, RCavetti.Right - pad - fn, RCavetti.Top + (RCavetti.Height - rh) / 2f, fn, rh);
                    float yr = RRadio.Top + S(26);
                    Campo(v.Mds, RRadio.Left + pad + Lw(Lang.T("MDS della radio")) + S(12), yr, fn, rh);
                    Campo(v.Modo, RRadio.Right - pad - fm, impRadioUna ? yr : yr + rh, fm, rh);
                    Campo(v.SnReq, RRadio.Right - pad - fn, yr + (impRadioUna ? 1 : 2) * rh, fn, rh);
                }
            }
            pnlImp.Invalidate();
        }

        // controllo nella riga k di un riquadro, allineato a destra
        void Riga2(Control c, RectangleF r, int k, int w, int box)
        {
            int wl = (int)Math.Min(w, r.Width - S(20));
            int riga = impPila[box] ? 2 * k + 1 : k;
            Campo(c, r.Right - S(10) - wl, r.Top + S(26) + riga * impRh, wl, impRh);
        }

        void Campo(Control c, float x, float y, int w, float rh)
        {
            if (c.Width != w) c.Width = w;
            Point p = new Point((int)x, (int)(y + (rh - c.Height) / 2f));
            if (c.Location != p) c.Location = p;
        }

        void MostraSchema()
        {
            if (bMe == null || bDx == null) return;
            foreach (BudgetUi u in new BudgetUi[] { bMe, bDx })
            {
                bool vis = (u == bMe) == (impSel == 0);
                foreach (Control c in u.Schema) c.Visible = vis;
                u.SnReq.Visible = vis && ModoPersonalizzato(u);   // la soglia si scrive a mano solo nel modo personalizzato
            }
            PosizionaSchema();
        }

        void Riquadro(Graphics g, RectangleF r, Color c, string titolo, Font ft)
        {
            using (GraphicsPath p = Arrotondato(r, S(9)))
            {
                using (Brush b = new SolidBrush(Tema.Carta)) g.FillPath(b, p);
                using (Pen pn = new Pen(c, S(2))) g.DrawPath(pn, p);
            }
            if (titolo != null) Testo(g, titolo, ft, c, new RectangleF(r.Left + S(10), r.Top + S(4), r.Width - S(16), S(22)), StringAlignment.Near, StringAlignment.Center);
        }

        // etichetta della riga k: a sinistra della casella (larga wc) o, se il riquadro è stretto, sulla riga sopra
        void Etichetta(Graphics g, string t, RectangleF r, int k, Font f, int box, int wc)
        {
            bool pila = impPila[box];
            float w = pila ? r.Width - S(20) : Math.Max(S(20), r.Width - S(20) - wc - S(6));
            Testo(g, t, f, Tema.Fore, new RectangleF(r.Left + S(10), r.Top + S(26) + (pila ? 2 * k : k) * impRh, w, impRh), StringAlignment.Near, StringAlignment.Center);
        }

        // testo colorato in fondo al riquadro, sotto le righe dei campi
        void Piede(Graphics g, string t, Font f, Color c, RectangleF r, int righe)
        {
            if (string.IsNullOrEmpty(t)) return;
            float y = r.Top + S(26) + righe * impRh + S(1);
            using (Brush b = new SolidBrush(c)) g.DrawString(t, f, b, new RectangleF(r.Left + S(10), y, r.Width - S(20), Math.Max(1, r.Bottom - y - S(2))));
        }

        void DisegnaImpianto(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            impZone.Clear();
            Color cAnt = Color.FromArgb(31, 111, 209), cTx = Color.FromArgb(217, 119, 6), cRx = Color.FromArgb(91, 63, 168), cRad = Color.FromArgb(23, 128, 61), cLinea = Color.FromArgb(55, 65, 81);
            if (Tema.Scuro) cLinea = Color.FromArgb(190, 198, 210);
            float W = pnlImp.Width;
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fl = FontPx(Lang.FontUi, S(13), false))
            using (Font fr = FontPx(Lang.FontUi, S(12), true))
            using (Font fs = FontPx(Lang.FontUi, S(14), true))
            using (Font fp = FontPx(Lang.FontUi, S(11), false))
            {
                // titolo e scelta della stazione
                string[] nomi = { Lang.T("La mia stazione"), Lang.T("Stazione DX") };
                float w1 = g.MeasureString(nomi[1], ft).Width + S(18), w0 = g.MeasureString(nomi[0], ft).Width + S(18);
                Testo(g, Lang.T("IMPIANTO DI TRASMISSIONE E RICEZIONE"), fs, Tema.Scuro ? Tema.Fore : Color.FromArgb(25, 65, 127),
                    new RectangleF(S(10), S(8), Math.Max(1, W - w0 - w1 - S(36)), S(28)), StringAlignment.Near, StringAlignment.Center);
                for (int i = 1; i >= 0; i--)
                {
                    RectangleF r = i == 1 ? new RectangleF(W - S(10) - w1, S(10), w1, S(26)) : new RectangleF(W - S(16) - w1 - w0, S(10), w0, S(26));
                    using (GraphicsPath p = Arrotondato(r, S(13)))
                    {
                        using (Brush b = new SolidBrush(i == impSel ? cAnt : Tema.Carta)) g.FillPath(b, p);
                        using (Pen pn = new Pen(i == impSel ? cAnt : Tema.Linea)) g.DrawPath(pn, p);
                    }
                    Testo(g, nomi[i], ft, i == impSel ? Color.White : Tema.Fore, r, StringAlignment.Center, StringAlignment.Center);
                    impZone.Add(new KeyValuePair<RectangleF, int>(r, i));
                }
                float xl = impXl, rh = impRh;
                // antenna: schiera di yagi, Tant a destra con il cielo dietro la Luna
                Testo(g, impAnt, ft, cAnt, new RectangleF(RAnt.Left + S(2), RAnt.Top - S(4), RAnt.Width * 0.62f, S(22)), StringAlignment.Near, StringAlignment.Near);
                float ya = RAnt.Top + S(44), xa = RAnt.Left + S(10);
                bool offSch = budgetDisco && bMe != null && bMe.Disco && (impSel == 0 ? bMe : bDx).DiscoTipo.SelectedIndex == 1;
                if (offSch)
                {
                    // disco offset visto di lato: spicchio alto di una parabola più grande, illuminatore sotto, fuori dall'apertura
                    float hd = S(64), xb = xa + S(40), xr = xb + S(22);
                    using (GraphicsPath pd = new GraphicsPath())
                    {
                        pd.AddBezier(xr, ya - hd / 2, xb - S(2), ya - hd / 6, xb - S(4), ya + hd / 6, xb + S(4), ya + hd / 2);
                        using (Pen pa = new Pen(cAnt, S(4))) g.DrawPath(pa, pd);
                    }
                    float xfo = xr + S(24), yfo = ya + hd / 2 + S(6);   // illuminatore sotto il bordo inferiore, rivolto verso il disco
                    using (Pen ps = new Pen(Color.FromArgb(100, 116, 139), S(2)))
                    {
                        g.DrawLine(ps, xb + S(4), ya + hd / 2, xfo, yfo);
                        g.DrawLine(ps, xr, ya - hd / 2, xfo, yfo);
                    }
                    using (Pen pm = new Pen(Color.FromArgb(51, 65, 85), S(4))) g.DrawLine(pm, xb - S(30), ya, xb - S(2), ya);
                    using (Brush bfe = new SolidBrush(cTx)) g.FillRectangle(bfe, xfo - S(7), yfo - S(7), S(14), S(14));
                }
                else if (budgetDisco && bMe != null && bMe.Disco)
                {
                    // disco a primo fuoco visto di lato: concavità verso destra, illuminatore nel fuoco davanti al disco
                    float hd = S(64), xb = xa + S(40), xr = xb + S(18);   // xb vertice, xr bordo del disco
                    float xfu = xb + hd * 0.40f;                           // fuoco a f/D × D dal vertice (f/D 0,40)
                    using (GraphicsPath pd = new GraphicsPath())
                    {
                        pd.AddBezier(xr, ya - hd / 2, xb - S(6), ya - hd / 4, xb - S(6), ya + hd / 4, xr, ya + hd / 2);
                        using (Brush bd = new SolidBrush(Tema.Scuro ? Color.FromArgb(60, 70, 90) : Color.FromArgb(226, 232, 240))) g.FillPath(bd, pd);
                        using (Pen pa = new Pen(cAnt, S(4))) g.DrawPath(pa, pd);
                    }
                    using (Pen ps = new Pen(Color.FromArgb(100, 116, 139), S(2)))
                    {
                        g.DrawLine(ps, xr, ya - hd / 2, xfu, ya);
                        g.DrawLine(ps, xr, ya + hd / 2, xfu, ya);
                    }
                    using (Pen pm = new Pen(Color.FromArgb(51, 65, 85), S(4))) g.DrawLine(pm, xb - S(30), ya, xb - S(4), ya);   // supporto dietro il vertice
                    using (Brush bfe = new SolidBrush(cTx)) g.FillRectangle(bfe, xfu - S(2), ya - S(7), S(14), S(14));
                }
                else
                using (Pen pa = new Pen(cAnt, S(3)))
                {
                    g.DrawLine(pa, xa, ya, xa + S(200), ya);
                    for (int k = 0; k < 7; k++) { float xx = xa + S(10) + k * S(30); g.DrawLine(pa, xx, ya - S(18), xx, ya + S(18)); }
                }
                Testo(g, "Tant", fl, Tema.Fore, new RectangleF(RAnt.Right - S(84) - S(60), RAnt.Top + S(18), S(56), rh), StringAlignment.Far, StringAlignment.Center);
                Testo(g, impTsky, fp, Tema.Muted, new RectangleF(RAnt.Left + RAnt.Width * 0.45f, RAnt.Top + S(20) + rh, RAnt.Width * 0.55f, S(20)), StringAlignment.Far, StringAlignment.Near);
                float xf = offSch ? xa + S(40) + S(22) + S(24) : (budgetDisco && bMe != null && bMe.Disco ? xa + S(40) + S(64) * 0.40f + S(5) : xa + S(30));   // punto di alimentazione: schiera o illuminatore del disco
                float yfe = offSch ? ya + S(64) / 2 + S(6) : ya;
                using (Pen pl = new Pen(cLinea, S(4)))
                {
                    g.DrawLine(pl, xf, yfe, xf, RAnt.Bottom);
                    g.DrawLine(pl, xf, RAnt.Bottom, xl, RAnt.Bottom);
                    g.DrawLine(pl, xl, RAnt.Bottom, xl, RRele.Top);
                    g.DrawLine(pl, xl + S(16), RRele.Bottom, xl + S(16), RLna.Top);           // RX verso il preampli
                    g.DrawLine(pl, xl, RTv.Bottom, xl, RRadio.Top);
                }
                using (Brush bf = new SolidBrush(cTx)) g.FillRectangle(bf, xf - S(5), yfe - S(5), S(10), S(10));
                using (Pen ptx = new Pen(cTx, S(4)))
                {
                    float xt = RTx.Left + RTx.Width * 0.5f, yt = RRele.Bottom + S(18);
                    g.DrawLine(ptx, xl - S(16), RRele.Bottom, xl - S(16), yt);
                    g.DrawLine(ptx, xl - S(16), yt, xt, yt);
                    g.DrawLine(ptx, xt, yt, xt, RTx.Top);
                }
                // relè
                using (GraphicsPath p = Arrotondato(RRele, S(6)))
                {
                    using (Brush b = new SolidBrush(Tema.Carta)) g.FillPath(b, p);
                    using (Pen pn = new Pen(cLinea, S(2))) g.DrawPath(pn, p);
                }
                using (Pen pc = new Pen(cRad, S(3)))
                {
                    g.DrawLine(pc, xl, RRele.Top + S(12), xl + S(14), RRele.Bottom - S(14));
                    using (Brush b = new SolidBrush(cLinea)) { g.FillEllipse(b, xl - S(4), RRele.Top + S(8), S(8), S(8)); g.FillEllipse(b, xl - S(20), RRele.Bottom - S(18), S(8), S(8)); g.FillEllipse(b, xl + S(12), RRele.Bottom - S(18), S(8), S(8)); }
                }
                Testo(g, "TX", fp, cTx, new RectangleF(xl - S(50), RRele.Bottom + S(2), S(28), S(16)), StringAlignment.Far, StringAlignment.Near);
                Testo(g, "RX", fp, cRx, new RectangleF(xl + S(24), RRele.Bottom + S(2), S(28), S(16)), StringAlignment.Near, StringAlignment.Near);
                // cavo di discesa ondulato, dal preampli al transverter
                using (Pen pw = new Pen(cLinea, S(4)))
                {
                    float y0 = RLna.Bottom, y1 = RTv.Top;
                    g.DrawLine(pw, xl + S(16), y0, xl + S(16), y0 + S(10));
                    g.DrawBezier(pw, xl + S(16), y0 + S(10), xl - S(40), y0 + (y1 - y0) * 0.35f, xl + S(40), y0 + (y1 - y0) * 0.65f, xl, y1);
                }
                // preampli (triangolo)
                PointF[] tri = { new PointF(xl + S(16) - RLna.Width / 2f, RLna.Top), new PointF(xl + S(16) + RLna.Width / 2f, RLna.Top), new PointF(xl + S(16), RLna.Bottom) };
                using (Brush b = new SolidBrush(Tema.Scuro ? Tema.Carta : Color.FromArgb(230, 238, 255))) g.FillPolygon(b, tri);
                using (Pen pn = new Pen(cAnt, S(2))) g.DrawPolygon(pn, tri);
                Testo(g, "LNA", FontDx(fp), cAnt, new RectangleF(tri[0].X, RLna.Top + S(3), RLna.Width, S(16)), StringAlignment.Center, StringAlignment.Near);

                // riquadri
                Riquadro(g, RCavoAnt, cLinea, Lang.T("CAVO ANTENNA – RELÈ"), ft);
                float wca = g.MeasureString(Lang.T("CAVO ANTENNA – RELÈ"), ft).Width;
                if (g.MeasureString(Lang.T("TX e RX"), fp).Width <= RCavoAnt.Width - wca - S(20))   // solo se c'è posto accanto al titolo
                    Testo(g, Lang.T("TX e RX"), fp, Tema.Muted, new RectangleF(RCavoAnt.Left + S(10) + wca, RCavoAnt.Top + S(5), Math.Max(1, RCavoAnt.Width - wca - S(20)), S(22)), StringAlignment.Near, StringAlignment.Center);
                Etichetta(g, Lang.T("Tipo"), RCavoAnt, 0, fl, 0, S(156)); Etichetta(g, Lang.T("Lunghezza"), RCavoAnt, 1, fl, 0, S(84));
                Piede(g, impCavoAnt, fr, cAnt, RCavoAnt, Linee(0, 2));
                Riquadro(g, RReleBox, cLinea, Lang.T("RELÈ COASSIALE TX / RX"), ft);
                Etichetta(g, Lang.T("Perdita di inserzione"), RReleBox, 0, fl, 1, S(84)); Etichetta(g, Lang.T("Connettori in TX"), RReleBox, 1, fl, 1, S(84)); Etichetta(g, Lang.T("Connettori in RX"), RReleBox, 2, fl, 1, S(84));
                Piede(g, impConn, fr, cLinea, RReleBox, Linee(1, 3));
                Riquadro(g, RTx, cTx, Lang.T("TRASMETTITORE · PA"), ft);
                Etichetta(g, Lang.T("Potenza in uscita"), RTx, 0, fl, 2, S(84)); Etichetta(g, Lang.T("Pilotaggio richiesto"), RTx, 1, fl, 2, S(84));
                Etichetta(g, Lang.T("Cavo PA – relè"), RTx, 2, fl, 2, S(156)); Etichetta(g, Lang.T("Lunghezza"), RTx, 3, fl, 2, S(84));
                Piede(g, impTx, fr, cTx, RTx, Linee(2, 4));
                Riquadro(g, RPre, cAnt, Lang.T("PREAMPLIFICATORE"), ft);
                Etichetta(g, Lang.T("Stadi"), RPre, 0, fl, 3, S(156)); Etichetta(g, Lang.T("Guadagno"), RPre, 1, fl, 3, S(84)); Etichetta(g, Lang.T("Figura di rumore"), RPre, 2, fl, 3, S(84));
                Piede(g, impPre, fr, cAnt, RPre, Linee(3, 3));
                Riquadro(g, RDis, cLinea, Lang.T("CAVO DI DISCESA"), ft);
                Etichetta(g, Lang.T("Tipo"), RDis, 0, fl, 4, S(156)); Etichetta(g, Lang.T("Lunghezza"), RDis, 1, fl, 4, S(84));
                Piede(g, impDis, fr, cAnt, RDis, Linee(4, 2));
                BudgetUi u = impSel == 0 ? bMe : bDx;
                bool tv = u != null && u.TvOn.Checked;
                Color cTv = tv ? cRx : Color.FromArgb(Tema.Scuro ? 110 : 150, cRx);
                Riquadro(g, RTv, cTv, null, ft);
                if (u != null)
                {
                    float xn = u.TvOn.Right + S(6);
                    Testo(g, string.Format(ci, Lang.T("(la radio non lavora direttamente su {0} MHz)"), curBand), fp, Tema.Muted,
                        new RectangleF(xn, RTv.Top + S(6), Math.Max(1, RTv.Right - xn - S(10)), u.TvOn.Height), StringAlignment.Near, StringAlignment.Center);
                    Color ctv = tv ? Tema.Fore : Tema.Muted;
                    Testo(g, Lang.T("Modello"), fl, ctv, new RectangleF(RTv.Left + S(10), RTv.Top + S(30), S(200), rh), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, Lang.T("Guadagno"), fl, ctv, new RectangleF(RTv.Left + S(10), RTv.Top + S(30) + rh, S(200), rh), StringAlignment.Near, StringAlignment.Center);
                    float wnf = g.MeasureString(Lang.T("Figura di rumore"), fl).Width + S(4);
                    Testo(g, Lang.T("Figura di rumore"), fl, ctv, new RectangleF(u.TvNf.Left - S(10) - wnf, RTv.Top + S(30) + rh, wnf, rh), StringAlignment.Far, StringAlignment.Center);
                    Testo(g, Lang.T("Uscita TX"), fl, ctv, new RectangleF(RTv.Left + S(10), RTv.Top + S(30) + 2 * rh, S(200), rh), StringAlignment.Near, StringAlignment.Center);
                    float wlt = g.MeasureString(Lang.T("Lunghezza"), fl).Width + S(4);
                    Testo(g, Lang.T("Lunghezza"), fl, ctv, new RectangleF(u.LenTv.Left - S(10) - wlt, RTv.Top + S(30) + 2 * rh, wlt, rh), StringAlignment.Far, StringAlignment.Center);
                    float wct = g.MeasureString(Lang.T("Cavo al PA"), fl).Width + S(4);
                    Testo(g, Lang.T("Cavo al PA"), fl, ctv, new RectangleF(u.CavoTv.Left - S(10) - wct, RTv.Top + S(30) + 3 * rh, wct, rh), StringAlignment.Far, StringAlignment.Center);
                    if (!string.IsNullOrEmpty(impTv))
                        g.DrawString(impTv, fr, new SolidBrush(impTvScarso ? Color.FromArgb(220, 38, 38) : cRx), new RectangleF(RTv.Left + S(10), RTv.Top + S(30) + 4 * rh, RTv.Width - S(20), Math.Max(1, RTv.Bottom - (RTv.Top + S(30) + 4 * rh))));
                }
                Riquadro(g, RCavetti, cLinea, null, ft);
                Testo(g, Lang.T("Cavetti fino alla radio"), fl, Tema.Fore, new RectangleF(RCavetti.Left + S(10), RCavetti.Top, RCavetti.Width - S(110), RCavetti.Height), StringAlignment.Near, StringAlignment.Center);
                Riquadro(g, RRadio, cRad, Lang.T("RADIO"), ft);
                float yr = RRadio.Top + S(26);
                Testo(g, Lang.T("MDS della radio"), fl, Tema.Fore, new RectangleF(RRadio.Left + S(10), yr, RRadio.Width * 0.45f, rh), StringAlignment.Near, StringAlignment.Center);
                if (u != null)
                {
                    float wm = g.MeasureString(Lang.T("Modo · S/N richiesto"), fl).Width + S(4);
                    if (impRadioUna) Testo(g, Lang.T("Modo · S/N richiesto"), fl, Tema.Fore, new RectangleF(u.Modo.Left - S(10) - wm, yr, wm, rh), StringAlignment.Far, StringAlignment.Center);
                    else Testo(g, Lang.T("Modo · S/N richiesto"), fl, Tema.Fore, new RectangleF(RRadio.Left + S(10), yr + rh, wm, rh), StringAlignment.Near, StringAlignment.Center);
                    if (ModoPersonalizzato(u))
                        Testo(g, Lang.T("S/N richiesto in 2500 Hz"), fl, Tema.Fore, new RectangleF(RRadio.Left + S(10), yr + (impRadioUna ? 1 : 2) * rh, RRadio.Width * 0.6f, rh), StringAlignment.Near, StringAlignment.Center);
                }
                Piede(g, impRadio, fr, cRad, RRadio, impRadioRighe);
            }
        }

        // Indicatori principali sopra la tabella: il numero grande, l'unità piccola
        void DisegnaKpi(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            Rectangle cr = pnlKpi.ClientRectangle;
            // prima riga: collegamento, EIRP mia, EIRP del DX; seconda: perdita di tratta e S/N nei due sensi (con il Sole, se calcolato)
            string[] tit = budgetEco && tabs != null && (tabs.SelectedTab == tpBudget || tabs.SelectedTab == tpBudgetD)
                ? new string[] { Lang.T("ECO POSSIBILE"), Lang.T("EIRP mia").ToUpper(Lang.Cultura), Lang.T("RITARDO DELL'ECO"),
                    Lang.T("PERDITA DI TRATTA EME"), Lang.T("S/N del mio eco").ToUpper(Lang.Cultura), Lang.T("MARGINE SULLA SOGLIA") }
                : new string[] { Lang.T("COLLEGAMENTO POSSIBILE"), Lang.T("EIRP mia").ToUpper(Lang.Cultura), Lang.T("EIRP del DX").ToUpper(Lang.Cultura),
                Lang.T("PERDITA DI TRATTA EME"), Lang.T("S/N io → DX").ToUpper(Lang.Cultura), Lang.T("S/N DX → io").ToUpper(Lang.Cultura) };
            float gap = S(10), w = (cr.Width - 4 * gap) / 3f, h = (cr.Height - 3 * gap) / 2f;
            using (Font fh = FontPx(Lang.FontUi, S(11), false))
            using (Font fv = FontPx(FamigliaNumeri, S(26), true))
            using (Font fu = FontPx(Lang.FontUi, S(14), false))
            using (Font fs = FontPx(Lang.FontUi, S(12), false))
            using (StringFormat tg = (StringFormat)StringFormat.GenericTypographic.Clone())
            {
                tg.FormatFlags |= StringFormatFlags.MeasureTrailingSpaces | StringFormatFlags.NoWrap;
                for (int i = 0; i < 6; i++)
                {
                    RectangleF r = new RectangleF(gap + (i % 3) * (w + gap), gap + (i / 3) * (h + gap), w, h);
                    Color c = kpiC[i].IsEmpty ? Tema.Accent : kpiC[i];
                    Scheda(g, r, c);
                    Testo(g, tit[i], fh, Tema.Muted, new RectangleF(r.Left + S(16), r.Top + S(6), r.Width - S(20), S(18)), StringAlignment.Near, StringAlignment.Near);
                    string v = kpiV[i] ?? "", gr = v, pic = "";
                    int sp = v.IndexOf(' ');
                    if (sp > 0) { gr = v.Substring(0, sp); pic = v.Substring(sp + 1); }
                    float yv = r.Top + S(22);
                    float wg = g.MeasureString(gr, fv, PointF.Empty, tg).Width;
                    using (Brush bv = new SolidBrush(c)) g.DrawString(gr, fv, bv, r.Left + S(16), yv, tg);
                    if (pic.Length > 0)
                    {
                        // unità allineata alla base del numero
                        float base1 = fv.FontFamily.GetCellAscent(fv.Style) * fv.Size / fv.FontFamily.GetEmHeight(fv.Style);
                        float base2 = fu.FontFamily.GetCellAscent(fu.Style) * fu.Size / fu.FontFamily.GetEmHeight(fu.Style);
                        using (Brush bu = new SolidBrush(Tema.Fore))
                            g.DrawString(pic, fu, bu, new RectangleF(r.Left + S(16) + wg + S(8), yv + base1 - base2, Math.Max(1, r.Width - wg - S(30)), fu.Height + S(2)), tg);
                    }
                    Testo(g, kpiS[i] ?? "", fs, Tema.Muted, new RectangleF(r.Left + S(16), r.Bottom - S(22), r.Width - S(20), S(20)), StringAlignment.Near, StringAlignment.Near);
                }
            }
        }

        // Tabella del Budget EME disegnata: intestazione maiuscola, fasce TRASMISSIONE / PERCORSO / RICEZIONE, valori colorati
        float TabBRiga { get { return S(25); } }

        void DimensionaTabB()
        {
            if (pnlTabB == null || pnlTabHost == null || lvB == null) return;
            int n = lvB.Items.Count;
            int h = (int)(S(16) + S(30) + n * TabBRiga + S(16));
            int w = pnlTabHost.ClientSize.Width;
            if (h > pnlTabHost.ClientSize.Height) w -= SystemInformation.VerticalScrollBarWidth;
            Size sz = new Size(Math.Max(S(300), w), Math.Max(h, pnlTabHost.ClientSize.Height));
            if (pnlTabB.Size != sz) pnlTabB.Size = sz;
            pnlTabB.Invalidate();
        }

        void DisegnaTabB(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            g.Clear(Tema.Back);
            if (lvB == null) return;
            Rectangle cr = pnlTabB.ClientRectangle;
            float hTot = S(16) + S(30) + lvB.Items.Count * TabBRiga + S(10);
            RectangleF card = new RectangleF(S(4), S(4), cr.Width - S(12), Math.Min(cr.Height - S(8), hTot));
            Scheda(g, card, Color.Empty);
            Color blu = Color.FromArgb(25, 65, 127);
            using (GraphicsPath p = Arrotondato(card, S(12)))
            {
                Region old = g.Clip;
                g.SetClip(p, CombineMode.Intersect);
                using (Brush bc = new SolidBrush(blu)) g.FillRectangle(bc, card.Left, card.Top, card.Width, S(4));
                g.Clip = old;
            }
            float x = card.Left + S(16), w = card.Width - S(32);
            float[] cx = budgetEco ? new float[] { x, x + w * 0.52f, x + w, x + w } : new float[] { x, x + w * 0.46f, x + w * 0.73f, x + w };
            int nCol = budgetEco ? 2 : 3;   // con il calcolo dell'eco la colonna del DX scompare
            Color riga = Tema.Scuro ? Color.FromArgb(60, 68, 80) : Color.FromArgb(232, 236, 242);
            Color fascia = Tema.Scuro ? Tema.Section : Color.FromArgb(232, 238, 248);
            using (Font fh = FontPx(Lang.FontUi, S(11), true))
            using (Font fr = FontPx(Lang.FontUi, S(13), false))
            using (Font fb = FontPx(Lang.FontUi, S(13), true))
            using (Font fz = FontPx(Lang.FontUi, S(11), true))
            using (Pen pl = new Pen(riga))
            {
                float y = card.Top + S(14);
                for (int k = 0; k < nCol; k++)
                    Testo(g, (budgetEco && k == 1 ? Lang.T("Io trasmetto e ricevo il mio eco") : lvB.Columns[k].Text).ToUpper(Lang.Cultura), fh, Tema.Muted, new RectangleF(cx[k], y, cx[k + 1] - cx[k] - S(6), S(26)), StringAlignment.Near, StringAlignment.Center);
                y += S(28);
                using (Pen ph = new Pen(Tema.Scuro ? Tema.Linea : Color.FromArgb(200, 208, 220), S(1.5f))) g.DrawLine(ph, x - S(4), y, x + w + S(4), y);
                float rh = TabBRiga;
                foreach (ListViewItem it in lvB.Items)
                {
                    bool sez = (it.Tag as string) == "sez";
                    if (sez)
                    {
                        using (Brush bf = new SolidBrush(fascia)) g.FillRectangle(bf, x - S(6), y + S(2), w + S(12), rh - S(3));
                        string t = it.Text.Trim().Replace("   (", " · ").Replace("  (", " · ");
                        if (t.EndsWith(")") && t.IndexOf(" · ", StringComparison.Ordinal) > 0) t = t.Substring(0, t.Length - 1);
                        Testo(g, t.ToUpper(Lang.Cultura), fz, Tema.Scuro ? Tema.Fore : blu, new RectangleF(x, y + S(2), w, rh - S(3)), StringAlignment.Near, StringAlignment.Center);
                    }
                    else
                    {
                        Font f = it.Font != null && it.Font.Bold ? fb : fr;
                        Testo(g, it.Text, f, Tema.Fore, new RectangleF(cx[0], y, cx[1] - cx[0] - S(8), rh), StringAlignment.Near, StringAlignment.Center);
                        for (int k = 1; k < nCol && k < it.SubItems.Count; k++)
                        {
                            Color cv = it.SubItems[k].ForeColor;
                            if (cv == Tema.FieldFore || cv.IsEmpty) cv = Tema.Fore;
                            Testo(g, it.SubItems[k].Text, f, cv, new RectangleF(cx[k], y, cx[k + 1] - cx[k] - S(6), rh), StringAlignment.Near, StringAlignment.Center);
                        }
                        g.DrawLine(pl, x - S(4), y + rh, x + w + S(4), y + rh);
                    }
                    y += rh;
                }
            }
        }

        static double Sn2500(double sn, double bw) { return sn + 10.0 * Math.Log10(bw / 2500.0); }

        // Riga della scheda del disco con la temperatura d'antenna stimata (cielo + ricaduta + rete) e quella dello schema
        static string TantDiscoTxt(BudgetParams q, CultureInfo c)
        {
            double tc, tr, tn, sp, tt;
            q.TantDisco(BudgetParams.Freq, TskyRif(BudgetParams.Freq), out tc, out tr, out tn, out sp, out tt);
            return string.Format(c, Lang.T("Tant stimata {0:F0} K = cielo {1:F0} + ricaduta {2:F0} + rete {3:F0} K (nello schema {4:F0} K)"), tc + tr + tn, tc, tr, tn, q.Tant);
        }

        // Testi dello schema e degli indicatori, ricalcolati con il budget
        void AggiornaSchemaEKpi(BudgetParams pm, BudgetParams pd, Riga r, Tratta a, Tratta b, double path, double pol, double bw, bool valido)
        {
            BudgetParams p = impSel == 0 ? pm : pd;
            double f = curBand;
            CultureInfo c = ci;
            string nomeAnt = p.CavoAnt >= 0 && p.CavoAnt < CaviDb.Elenco.Count ? CaviDb.Elenco[(int)p.CavoAnt].Nome : "";
            string nomeDis = p.CavoDis >= 0 && p.CavoDis < CaviDb.Elenco.Count ? CaviDb.Elenco[(int)p.CavoDis].Nome : "";
            double gt = p.GAnt + 10.0 * Math.Log10(p.NAnt);
            impAnt = p.Disco > 0.5
                ? Lang.T("ANTENNA") + " · " + string.Format(c, Lang.T("disco {0:F2} m"), p.DiscoD) + " · " + p.GAnt.ToString("F1", c) + " dBi"
                : Lang.T("ANTENNA") + " · " + p.NAnt + " × " + p.GAnt.ToString("F1", c) + " dBi = " + gt.ToString("F1", c) + " dBi";
            // pilotaggio del PA dal transverter
            impTv = ""; impTvScarso = false;
            if (p.TvOn > 0.5)
            {
                double alPa = p.TvPtx * Math.Pow(10.0, -p.LossTv / 10.0);
                impTvScarso = alPa < p.PaPin * 0.98;
                impTv = string.Format(c, Lang.T("TX: {0} → cavo {1:F2} dB → al PA {2}"), FmtW(p.TvPtx, c), p.LossTv, FmtW(alPa, c))
                    + " · " + (impTvScarso ? string.Format(c, Lang.T("pilotaggio insufficiente (servono {0})"), FmtW(p.PaPin, c)) : Lang.T("pilotaggio sufficiente"));
            }
            impCavoAnt = (nomeAnt.Length > 0 ? (p.LossAnt / Math.Max(0.001, p.LenAnt) * 100).ToString("F1", c) + " dB/100 m · " : "") + string.Format(c, "{0} MHz → {1:F2} dB", f, p.LossAnt);
            double txTot = p.CavoTx + p.AccTx;
            if (p.LossConn > 0 || p.LossConnRx > 0)
            {
                impTx = string.Format(c, Lang.T("cavo {0:F2} + relè {1:F2} + antenna {2:F2} + connettori {3:F2} = {4:F2} dB → {5} all'antenna"), p.LossPa, p.Rele, p.LossAnt, p.LossConn, txTot, FmtW(p.P * Math.Pow(10.0, -txTot / 10.0), c));
                impPre = string.Format(c, Lang.T("prima del preampli: {0:F2} + {1:F2} + connettori {2:F2} = {3:F2} dB"), p.LossAnt, p.Rele, p.LossConnRx, p.PreLoss);
                impConn = string.Format(c, Lang.T("TX {0} × {1:F2} dB = {2:F2} dB · RX {3} × {1:F2} dB = {4:F2} dB prima del preampli"), (int)Math.Round(p.ConnTx), BudgetParams.DbConnettore, p.LossConn, (int)Math.Round(p.ConnRx), p.LossConnRx);
            }
            else
            {
                impTx = string.Format(c, Lang.T("cavo {0:F2} + relè {1:F2} + antenna {2:F2} = {3:F2} dB → {4} all'antenna"), p.LossPa, p.Rele, p.LossAnt, txTot, FmtW(p.P * Math.Pow(10.0, -txTot / 10.0), c));
                impPre = string.Format(c, Lang.T("prima del preampli: {0:F2} + {1:F2} = {2:F2} dB"), p.LossAnt, p.Rele, p.PreLoss);
                impConn = "";
            }
            impDis = (nomeDis.Length > 0 ? (p.LossDis / Math.Max(0.001, p.LenDis) * 100).ToString("F1", c) + " dB/100 m · " : "") + string.Format(c, "{0} MHz → {1:F2} dB", f, p.LossDis);
            double nr, nft = NfFriis(p, bw, out nr);
            double te = 290.0 * (Math.Pow(10.0, nft / 10.0) - 1.0);
            impTsky = "";
            if (valido)
            {
                Tratta t = impSel == 0 ? b : a;   // tratta in cui questa stazione riceve
                double sn25 = Sn2500(t.SNb, bw);
                impTsky = string.Format(c, Lang.T("Tsky dietro la Luna {0:F0} K"), t.Tsky);
                impRadio = string.Format(c, Lang.T("Catena di ricezione (Friis): NF {0:F2} dB · Te {1:F0} K · NF radio dal MDS {2:F1} dB"), nft, te, nr) + "\n"
                    + string.Format(c, Lang.T("S/N {0} dB in {1:0} Hz · {2} dB in 2500 Hz (soglia tipica {3}: {4} dB)"), Segno(t.SNb, c), bw, Segno(sn25, c), p.NomeModo, p.SnReq.ToString("0.#", c));
            }
            else impRadio = string.Format(c, Lang.T("Catena di ricezione (Friis): NF {0:F2} dB · Te {1:F0} K · NF radio dal MDS {2:F1} dB"), nft, te, nr);
            foreach (KeyValuePair<BudgetUi, BudgetParams> kv in new KeyValuePair<BudgetUi, BudgetParams>[] {
                new KeyValuePair<BudgetUi, BudgetParams>(bMe, pm), new KeyValuePair<BudgetUi, BudgetParams>(bDx, pd) })
            {
                BudgetParams q = kv.Value;
                double tx = q.CavoTx + q.AccTx;
                kv.Key.Info1.Text = string.Format(c, Lang.T("Potenza {0} · perdite TX {1:F1} dB (dallo schema)"), FmtW(q.P, c), tx);
                if (q.Disco > 0.5)
                {
                    double lam = 299.792458 / Math.Max(1, BudgetParams.Freq), x = Math.PI * q.DiscoD / lam;
                    kv.Key.Info2.Text = Lang.T("Guadagno = 10·log[η·(π·D/λ)²] (PE1RKI)") + (q.DiscoTipo > 0.5 ? " · " + Lang.T("offset: D = apertura proiettata (W2IMU)") : "") + "\n"
                        + string.Format(c, "λ = {0:F2} cm · (π·D/λ)² = {1:F0}", lam * 100, x * x) + "\n"
                        + TantDiscoTxt(q, c) + "\n"
                        + string.Format(c, Lang.T("{0:F1} dBi ({1:F1} dBd) · apertura a −3 dB ≈ 70·λ/D = {2:F1}°"), q.GAnt, q.GAnt - 2.15, BudgetParams.AperturaDisco(q.DiscoD, BudgetParams.Freq));
                }
                else
                kv.Key.Info2.Text = string.Format(c, Lang.T("Guadagno totale {0} × {1:F1} dBi = {2:F1} dBi · trasmissione e ricezione: schema a destra →"), q.NAnt, q.GAnt, q.GAnt + 10.0 * Math.Log10(q.NAnt));
            }
            // indicatori
            if (!valido)
            {
                for (int i = 0; i < 6; i++) { kpiV[i] = "–"; kpiS[i] = ""; kpiC[i] = Tema.Muted; }
                kpiS[0] = Lang.T("servono i locator delle due stazioni");
            }
            else
            {
                kpiV[0] = r.Ok ? Lang.T("SÌ") : Lang.T("NO");
                kpiS[0] = r.Ok ? Lang.T("Luna puntabile da entrambe") : Lang.T("la Luna non è puntabile da entrambe");
                kpiC[0] = r.Ok ? Tema.OkFg : Tema.BadFg;
                double e1 = Math.Pow(10.0, a.EirpDbW / 10.0), e2 = Math.Pow(10.0, b.EirpDbW / 10.0);
                kpiV[1] = FmtW(e1, c) + " · " + a.EirpDbW.ToString("F1", c) + " dBW";
                kpiS[1] = string.Format(c, Lang.T("{0} all'antenna (perdite TX {1:F1} dB) · {2:F1} dBi"), FmtW(a.PantW, c), a.LossTx, a.Gtx);
                kpiC[1] = Color.FromArgb(31, 111, 209);
                kpiV[2] = FmtW(e2, c) + " · " + b.EirpDbW.ToString("F1", c) + " dBW";
                kpiS[2] = string.Format(c, Lang.T("{0} all'antenna (perdite TX {1:F1} dB) · {2:F1} dBi"), FmtW(b.PantW, c), b.LossTx, b.Gtx);
                kpiC[2] = Color.FromArgb(217, 119, 6);
                kpiV[3] = path.ToString("F1", c) + " dB";
                kpiS[3] = PolCircolare ? (chkPol.Checked ? string.Format(c, Lang.T("+ {0:F1} dB polarizzazione circolare (KA1GT)"), pol) : Lang.T("non inclusa (polarizzazione circolare)"))
                    : chkPol.Checked ? string.Format(c, Lang.T("+ {0:F1} dB polarizzazione (Dpol {1:F0}°)"), pol, r.Dpol) : string.Format(c, Lang.T("polarizzazione non inclusa (Dpol {0:F0}°)"), r.Dpol);
                kpiC[3] = Color.FromArgb(107, 114, 128);
                KpiSn(a, b, bw, false);
                kpiC[4] = Color.FromArgb(15, 139, 141);
                kpiC[5] = Color.FromArgb(91, 63, 168);
            }
            // titolo delle schede delle stazioni: locator e posizione della Luna
            bMe.Sotto = (me != null && me.Ok ? me.Loc.Text.Trim() : "") + (valido && r != null ? string.Format(c, " · " + Lang.T("Luna") + " Az {0:F1}° El {1:F1}°", r.P.Az, r.P.El) : "");
            bDx.Sotto = (dx != null && dx.Ok && chkDx.Checked ? dx.Loc.Text.Trim() : "") + (valido && r != null && r.StatoDx != null ? string.Format(c, " · " + Lang.T("Luna") + " Az {0:F1}° El {1:F1}°", r.Q.Az, r.Q.El) : "");
            foreach (BudgetUi bu in new BudgetUi[] { bMe, bDx }) if (bu.Card != null) bu.Card.Invalidate();
            if (pnlKpi != null) pnlKpi.Invalidate();
            PosizionaSchema();   // i testi in fondo ai riquadri possono cambiare il numero di righe
        }

        static string Segno(double v, CultureInfo c) { return (v >= 0 ? "+" : "−") + Math.Abs(v).ToString("F1", c); }

        // S/N nei due sensi nella banda passante scelta (con il Sole quando è calcolato), con il valore riportato a 2500 Hz
        void KpiSn(Tratta a, Tratta b, double bw, bool sole)
        {
            CultureInfo c = ci;
            Tratta[] t = { a, b };
            for (int i = 0; i < 2; i++)
            {
                kpiV[4 + i] = Segno(t[i].SNb, c) + " dB";
                kpiS[4 + i] = string.Format(c, sole ? Lang.T("in {0:0} Hz con il Sole · {1} dB in 2500 Hz") : Lang.T("in {0:0} Hz · {1} dB in 2500 Hz"), bw, Segno(Sn2500(t[i].SNb, bw), c));
            }
            if (pnlKpi != null) pnlKpi.Invalidate();
        }


        // ---- Budget EME yagi / Budget EME dischi: la stessa interfaccia passa da una linguetta all'altra.
        // bpMe/bpDx tengono l'impianto attivo di ogni banda (quello dell'ultima linguetta usata per la banda),
        // bpMeAlt/bpDxAlt l'altro tipo di antenna, così i valori delle yagi e dei dischi restano separati.
        static readonly int[] BandeDischi = { 432, 902, 1296 };
        // in 23 cm con i dischi si usa la polarizzazione circolare: niente perdita spaziale, ma una perdita tipica
        // degli illuminatori reali (isolamento tra le porte di circa 10 dB → 0,4 dB, misure di Bob Atkins KA1GT)
        const double PerditaCircolare = 0.4;
        bool PolCircolare { get { return budgetDisco && curBand >= 1296 && bMe != null && bMe.Disco; } }
        double PolScelta(Riga r) { return !chkPol.Checked ? 0.0 : (PolCircolare ? PerditaCircolare : r.PolLoss); }
        TabPage tpBudgetD;
        bool budgetDisco;
        TableLayoutPanel budgetSx;
        Dictionary<int, BudgetParams> bpMeAlt = new Dictionary<int, BudgetParams>();
        Dictionary<int, BudgetParams> bpDxAlt = new Dictionary<int, BudgetParams>();

        void AllineaTipo(int f)
        {
            bool vuole = budgetDisco && Array.IndexOf(BandeDischi, f) >= 0;
            Dictionary<int, BudgetParams>[] att = { bpMe, bpDx }, alt = { bpMeAlt, bpDxAlt };
            for (int i = 0; i < 2; i++)
            {
                BudgetParams cur;
                if (!att[i].TryGetValue(f, out cur)) continue;
                if ((cur.Disco > 0.5) == vuole) continue;
                BudgetParams a;
                if (!alt[i].TryGetValue(f, out a) || (a.Disco > 0.5) != vuole) a = vuole ? BudgetParams.DefaultDisco(f) : BudgetParams.Default(f);
                alt[i][f] = cur;
                att[i][f] = a;
            }
        }

        void ImpostaModoBudget(bool disco)
        {
            if (budgetRoot == null || tpBudgetD == null) return;
            TabPage dest = disco ? tpBudgetD : tpBudget;
            if (budgetRoot.Parent != dest)
            {
                if (budgetRoot.Parent != null) budgetRoot.Parent.Controls.Remove(budgetRoot);
                dest.Controls.Add(budgetRoot);
            }
            if (budgetDisco == disco && bMe.Disco == (disco && Array.IndexOf(BandeDischi, curBand) >= 0)) return;
            SalvaBanda(curBand);
            budgetDisco = disco;
            if (disco && Array.IndexOf(BandeDischi, curBand) < 0)
            {
                // i dischi si calcolano a 432, 902 e 1296 MHz: si passa alla prima di queste bande tra quelle scelte
                foreach (int f in BandeDischi)
                    if (bandeAttive.Contains(f)) { cmbBand.SelectedIndex = bandeAttive.IndexOf(f); break; }
            }
            CaricaBanda(curBand);
            if (!caricamento) SaveSettings();
        }

        void ApplicaModoUi()
        {
            bool d = budgetDisco && Array.IndexOf(BandeDischi, curBand) >= 0;
            foreach (BudgetUi u in new BudgetUi[] { bMe, bDx })
            {
                if (u == null) continue;
                u.Disco = d;
                if (u.Card != null) { DisponiStazione(u); u.Card.Invalidate(); }
            }
            if (budgetSx != null && bMe != null) budgetSx.RowStyles[0].Height = Math.Max(S(196), StazAltezza(bMe));
        }

        void SalvaBanda(int f)
        {
            BudgetParams.Freq = f;
            bpMe[f] = BudgetParams.FromUi(bMe);
            bpDx[f] = BudgetParams.FromUi(bDx);
        }

        void CaricaBanda(int f)
        {
            BudgetParams.Freq = f;
            AllineaTipo(f);
            loadingB = true;
            try
            {
                bpMe[f].ToUi(bMe);
                bpDx[f].ToUi(bDx);
            }
            finally { loadingB = false; }
            curBand = f;
            ApplicaModoUi();
            SyncTab3();
            MostraSchema();
            RecalcBudget();
        }

        void CambiaBanda()
        {
            if (bandeAttive.Count == 0) return;
            int nf = bandeAttive[Math.Max(0, Math.Min(bandeAttive.Count - 1, cmbBand.SelectedIndex))];
            if (nf == curBand) return;
            if (tabs != null && tabs.SelectedTab == tpBudgetD && Array.IndexOf(BandeDischi, nf) < 0 && Array.IndexOf(BandeDischi, curBand) >= 0)
            {
                // nella linguetta dei dischi solo 432, 902 e 1296 MHz
                cmbBand.SelectedIndex = bandeAttive.IndexOf(curBand);
                return;
            }
            SalvaBanda(curBand);
            CaricaBanda(nf);
            BandaVersoFreq();
        }

        bool RigaSelezionata(out DateTime t)
        {
            t = DateTime.MinValue;
            if (lv.SelectedIndices.Count == 0 || lv.SelectedIndices[0] >= mostrate.Count)
            {
                Messaggio(this, Lang.T("Seleziona prima una riga nella tabella della linguetta \"Posizione della Luna\"."),
                    "YAEC", MessageBoxButtons.OK, MessageBoxIcon.Information);
                return false;
            }
            DateTime u = mostrate[lv.SelectedIndices[0]].Utc;
            t = new DateTime(u.Year, u.Month, u.Day, u.Hour, u.Minute, 0, DateTimeKind.Unspecified);
            return true;
        }

        void UsaRigaSelezionata()
        {
            DateTime t;
            if (!RigaSelezionata(out t)) return;
            dtpB.Value = t;
            RecalcBudget();
        }

        static string FmtW(double w, CultureInfo c)
        {
            if (w >= 1e9) return (w / 1e9).ToString("F2", c) + " GW";
            if (w >= 1e6) return (w / 1e6).ToString("F2", c) + " MW";
            if (w >= 1e3) return (w / 1e3).ToString("F2", c) + " kW";
            if (w >= 10) return w.ToString("F0", c) + " W";
            return w.ToString("F2", c) + " W";
        }

        string Db(double v) { return v.ToString("F1", ci) + " dB"; }
        string Dbm(double v) { return v.ToString("F1", ci) + " dBm"; }
        string Dbw(double v) { return v.ToString("F1", ci) + " dBW"; }

        class Tratta
        {
            public double PdBW, LossTx, PantW, Gtx, EirpDbW, Grx, Sant, S1, S2, S3, S4, S5, MdsAnt, Margin, Mds;
            public double GgTx, GgRx, Extra, Tant, TskyEcc;
            public double Tsky, Tsun, Tr, Tloss, Tsys, Bw, Nb, SNb, NfTot, NfRadio;
        }

        const double KBOLTZ = 1.380649e-23;

        static double NoiseDbm(double tsys, double bw)
        {
            return 10.0 * Math.Log10(KBOLTZ * tsys * bw) + 30.0;
        }

        // Guadagno dovuto al terreno ("ground gain") per un'antenna a polarizzazione orizzontale
        // senza elevazione, alta h metri sopra un terreno piano e riflettente (coefficiente -1):
        // G = 20·log|2·sin(2π·h·sin(El)/λ)|, massimo +6 dB sui lobi. Con h = 0 si applica +6 dB fisso.
        public static double GroundGain(double hM, double elDeg, double fMHz)
        {
            if (hM <= 0) return 6.02;
            double el = Math.Max(0.05, elDeg);
            double lambda = 299.792458 / fMHz;
            double g = Math.Abs(2.0 * Math.Sin(2.0 * Math.PI * hM * Math.Sin(el * Math.PI / 180.0) / lambda));
            if (g < 0.01) g = 0.01;
            return 20.0 * Math.Log10(g);
        }

        // Elevazione del primo lobo di riflessione (gradi)
        public static double PrimoLobo(double hM, double fMHz)
        {
            if (hM <= 0) return double.NaN;
            double x = (299.792458 / fMHz) / (4.0 * hM);
            return x >= 1 ? 90.0 : Math.Asin(x) * 180.0 / Math.PI;
        }

        // tsky = cielo dietro la Luna visto dal ricevitore, tsun = temperatura aggiunta dal Sole (0 se ignorata),
        // ggTx/ggRx = ground gain delle due antenne, extra = altre perdite di tratta, bw = banda passante (Hz)
        public static double TskyRif(double freq) { return (200.0 - 2.7) * Math.Pow(144.0 / freq, 2.6) + 2.7; }

        static Tratta CalcTratta(BudgetParams tx, BudgetParams rx, double path, double pol, double tsky, double tsun,
            double bw, double ggTx, double ggRx, double extra, double freq)
        {
            Tratta t = new Tratta();
            t.GgTx = ggTx; t.GgRx = ggRx; t.Extra = extra; t.Bw = bw;
            t.PdBW = 10.0 * Math.Log10(tx.P);
            t.LossTx = tx.CavoTx + tx.AccTx;
            t.PantW = tx.P * Math.Pow(10.0, -t.LossTx / 10.0);
            t.Gtx = tx.GAnt + 10.0 * Math.Log10(tx.NAnt) + ggTx;
            t.EirpDbW = t.PdBW - t.LossTx + t.Gtx;
            t.Grx = rx.GAnt + 10.0 * Math.Log10(rx.NAnt) + ggRx;
            t.Sant = t.EirpDbW + 30.0 - path - pol - extra + t.Grx;
            t.S1 = t.Sant - rx.PreLoss;
            t.S2 = t.S1 + rx.PreGain;
            t.S3 = t.S2 - rx.PostLoss;
            t.S4 = t.S3 + rx.TvGain;
            t.S5 = t.S4 - rx.TvCavo;   // dopo i cavetti tra transverter e radio = ingresso della radio
            t.Mds = rx.Mds;
            t.MdsAnt = rx.Mds - (-rx.PreLoss + rx.PreGain - rx.PostLoss + rx.TvGain - rx.TvCavo);
            t.Margin = t.S5 - rx.Mds;
            // Rumore di sistema riferito ai morsetti dell'antenna: Tant (cielo + Sole) + temperatura
            // equivalente del ricevitore completo, con la formula di Friis (HP/Agilent AN 57-1)
            t.Tsky = tsky;
            t.Tsun = tsun;
            t.Tr = 290.0 * (Math.Pow(10.0, rx.Nf / 10.0) - 1.0);
            double nfRadio;
            t.NfTot = NfFriis(rx, bw, out nfRadio);
            t.NfRadio = nfRadio;
            t.Tloss = 290.0 * (Math.Pow(10.0, t.NfTot / 10.0) - 1.0);
            // Tant (tabelle VE7BQH, 30° di elevazione) comprende già un cielo di riferimento; si aggiunge
            // solo l'eccesso del cielo dietro la Luna rispetto a quel riferimento (200 K a 144 MHz, indice 2,6)
            t.Tant = rx.Tant;
            t.TskyEcc = Math.Max(0.0, tsky - TskyRif(freq));
            t.Tsys = t.Tant + t.TskyEcc + tsun + t.Tloss;
            t.Nb = NoiseDbm(t.Tsys, bw);
            t.SNb = t.Sant - t.Nb;
            return t;
        }

        // Quanto S/N e G/T si perdono con 0,1 dB di perdita in più prima del preampli (cavo, relè, connettori):
        // la perdita moltiplica la figura di rumore totale riferita all'antenna (Ftot = L·F dopo), quindi
        // Tsys cresce di 290·Ftot·(10^0,01 − 1). Con il cielo freddo dai 432 MHz in su pesa circa 3 volte più
        // che a 144 MHz (PA3CSG, "You worked everybody on 144 MHz EME so try 432 MHz EME").
        static double Costo01(Tratta t)
        {
            double ft = Math.Pow(10.0, t.NfTot / 10.0);
            return -10.0 * Math.Log10((t.Tsys + 290.0 * ft * (Math.Pow(10.0, 0.01) - 1.0)) / t.Tsys);
        }

        // ---- Prova della stazione con il fattore Y (G3LTF, "Practical Optimization of 432 MHz and up EME systems
        // using VK3UM's EMECalc"): rumore con l'antenna sulla sorgente diviso rumore sul cielo freddo, previsto con la
        // catena di ricezione di questo budget. Tsys sul cielo freddo = Tant (cielo di riferimento compreso) + Te del ricevitore.
        // Sorgente estesa a disco uniforme nel fascio gaussiano: guadagno medio sul disco (1 − 2^(−x²)) / (ln2·x²), x = diametro / HPBW;
        // Luna come disco a 213 K (DF3GJ) con il fill factor 1 − 2^(−x²) (DF3GJ, UA3AVR); Cas A puntiforme.
        public const double TLuna = 213.0;
        // diametro apparente del Sole (v1.9.5): da 0,524° all'afelio a 0,542° al perielio, dalla distanza Terra–Sole
        // (Meeus, Astronomical Algorithms, cap. 25: r = 1,00014 − 0,01671·cos g − 0,00014·cos 2g UA; 0,5332° a 1 UA)
        public static double DiamSole = 0.533;
        public static double DiamSoleIl(DateTime t)
        {
            double d = (t - new DateTime(2000, 1, 1, 12, 0, 0, DateTimeKind.Utc)).TotalDays;
            double g = (357.529 + 0.98560028 * d) * Math.PI / 180.0;
            double r = 1.00014 - 0.01671 * Math.Cos(g) - 0.00014 * Math.Cos(2 * g);
            return 0.5332 / r;
        }
        static double[] FattoriY(Tratta t, BudgetParams rx, double sfu, double freq, double distKm) { return FattoriY(t, rx, sfu, freq, distKm, 0); }
        // rho: frazione di potenza riflessa dal disadattamento dell'antenna (AEH eq. 41-19): il ΔT della sorgente diventa (1 − ρ)·ΔT
        static double[] FattoriY(Tratta t, BudgetParams rx, double sfu, double freq, double distKm, double rho)
        {
            double tf = t.Tant + t.Tloss;
            double gdb = rx.GAnt + 10.0 * Math.Log10(Math.Max(1, rx.NAnt));
            double lam = 299.792458 / freq, ae = Math.Pow(10.0, gdb / 10.0) * lam * lam / (4.0 * Math.PI);
            double hp = rx.Fascio(freq);
            double xs = DiamSole / hp, xm = 2.0 * Math.Asin(1737.4 / Math.Max(300000, distKm)) * 180.0 / Math.PI / hp;
            double ts = double.IsNaN(sfu) || sfu <= 0 ? double.NaN : sfu * 1e-22 * ae / (2.0 * KBOLTZ) * (1 - Math.Pow(2, -xs * xs)) / (Math.Log(2) * xs * xs);
            double tm = TLuna * (1 - Math.Pow(2, -xm * xm));
            double jy = double.NaN;
            foreach (Radiosorgente so in Sorgenti) if (so.Nome == "Cas A") jy = so.Flusso(freq);
            double tc = jy * 1e-26 * ae / (2.0 * KBOLTZ);
            Func<double, double> y = dt => double.IsNaN(dt) ? double.NaN : 10.0 * Math.Log10(1 + (1.0 - rho) * dt / tf);
            return new double[] { gdb - 10.0 * Math.Log10(tf), y(ts), y(tm), y(tc), 10.0 * Math.Log10((290.0 + t.Tloss) / tf), sfu, jy, xm * hp, tf };
        }

        // G/T del disco di 6 m di G3LTF (rapporti lineari, K⁻¹): misurato e teorico
        static readonly double[,] GtG3ltf = { { 432, 5, 8.7 }, { 1296, 79, 79 }, { 2320, 133, 253 }, { 3400, 218, 543 }, { 5760, 218, 693 }, { 10368, 176, 2247 } };

        void RigheFattoreY(Tratta ta, BudgetParams ra, double sfuA, Tratta tb, BudgetParams rb, double sfuB, double freq, double distKm, CultureInfo c)
        {
            double ros = LeggiRos(), rho = RhoDaRos(ros);
            double[] ya = ta != null ? FattoriY(ta, ra, sfuA, freq, distKm, rho) : null;
            double[] yb = FattoriY(tb, rb, sfuB, freq, distKm, rho);
            // sensibilità della misura (radiometro a potenza totale, AEH 4ª ed., eq. 41-21): ΔT = Tsys/√(B·τ);
            // lo Y minimo distinguibile, 10·log(1 + 1/√(B·τ)), non dipende da Tsys
            double bwY = LeggiBw(), tau = LeggiTau(), rad = Math.Sqrt(bwY * tau);
            Func<double[], int, string> f = (v, i) =>
            {
                if (v == null) return "";
                if (double.IsNaN(v[i])) return "–";
                double vol = (Math.Pow(10.0, v[i] / 10.0) - 1.0) * rad;   // ΔT della sorgente in multipli del ΔT minimo
                string giud = vol >= 3 ? Lang.T("misurabile") : (vol >= 1 ? Lang.T("al limite") : Lang.T("non misurabile"));
                string vs = Math.Abs(v[i]) < 1 ? (v[i] >= 0 ? "+" : "−") + Math.Abs(v[i]).ToString("F2", c) : Segno(v[i], c);
                return vs + " dB · " + vol.ToString(vol < 10 ? "0.0" : "0", c) + "× · " + giud;
            };
            SezioneB(Lang.T("PROVA DELLA STAZIONE: FATTORE Y PREVISTO SUL CIELO FREDDO (G3LTF, EMECalc di VK3UM)"));
            RigaB(Lang.T("G/T sul cielo freddo (G − 10·log Tsys)"), yb[0].ToString("F1", c) + " dB/K", ya != null ? ya[0].ToString("F1", c) + " dB/K" : "", Tema.Field, true, Tema.Accent, Tema.Accent);
            {
                double dy = 10.0 * Math.Log10(1 + 1 / rad);
                Func<double[], string> dt = v => v == null ? "" : (v[8] / rad).ToString(v[8] / rad < 10 ? "0.00" : "0.0", c) + " K · " + dy.ToString("0.000", c) + " dB";
                RigaB(string.Format(c, Lang.T("ΔT minimo misurabile (AEH eq. 41-21, B = {0} Hz, τ = {1} s)"), bwY.ToString("0", c), tau.ToString("0.#", c)), dt(yb), dt(ya));
            }
            string sole = double.IsNaN(yb[5]) ? Lang.T("Sole (flusso dalla linguetta Rumore solare)") : string.Format(c, Lang.T("Sole ({0:F0} sfu alla frequenza di lavoro, disco di {1:F2}°)"), yb[5], DiamSole);
            RigaB(sole, f(yb, 1), f(ya, 1));
            RigaB(string.Format(c, Lang.T("Luna ({0:F0} K, disco di {1:F2}°)"), TLuna, yb[7]), f(yb, 2), f(ya, 2));
            RigaB(string.Format(c, Lang.T("Cas A ({0:F0} Jy, flusso indicativo)"), yb[6]), f(yb, 3), f(ya, 3));
            RigaB(Lang.T("Cielo freddo contro terreno o carico da 50 Ω a 290 K"), f(yb, 4), f(ya, 4));
            RigaB(Lang.T("ΔT minimo: limite ideale del radiometro a potenza totale; la deriva del guadagno lo peggiora (regola pratica di PA3CSG: circa 0,1 dB). Misurabile = almeno 3 volte il minimo."), "", "");
            if (ros > 1.0)
                RigaB(string.Format(c, Lang.T("ROS {0}:1 dell'antenna: ρ = {1}, lo Y di Sole, Luna e Cas A scende del fattore (1 − ρ) (AEH eq. 41-19); il rumore del ricevitore riflesso, ρ·TR, non si conosce e resta un errore sistematico"), ros.ToString("0.0", c), rho.ToString("0.000", c)),
                    Segno(10.0 * Math.Log10(1.0 - rho), c) + " dB ΔT", ya != null ? Segno(10.0 * Math.Log10(1.0 - rho), c) + " dB ΔT" : "");
            if (rb.Disco > 0.5)
                for (int i = 0; i < GtG3ltf.GetLength(0); i++)
                    if (Math.Abs(GtG3ltf[i, 0] - freq) < 20)
                    {
                        double m = 10.0 * Math.Log10(GtG3ltf[i, 1]), th = 10.0 * Math.Log10(GtG3ltf[i, 2]);
                        RigaB(string.Format(c, Lang.T("Confronto: disco di 6 m di G3LTF a {0:F0} MHz, G/T misurato contro teorico"), GtG3ltf[i, 0]),
                            string.Format(c, "{0:F1} / {1:F1} dB/K ({2} dB)", m, th, Segno(m - th, c)), ya != null ? string.Format(c, "{0:F1} / {1:F1} dB/K", m, th) : "");
                    }
        }

        // Figura di rumore complessiva della catena di ricezione (dB), formula di Friis
        // bw = banda passante impostata (Hz), usata per ricavare la NF della radio dal suo MDS
        static double NfFriis(BudgetParams rx, double bw, out double nfRadio)
        {
            nfRadio = Math.Max(0.5, rx.Mds + 174.0 - 10.0 * Math.Log10(bw));
            double[] f = {
                Math.Pow(10.0, rx.PreLoss / 10.0), Math.Pow(10.0, rx.Nf / 10.0), Math.Pow(10.0, rx.PostLoss / 10.0),
                rx.TvGain == 0 ? 1.0 : Math.Pow(10.0, rx.TvNf / 10.0), Math.Pow(10.0, rx.TvCavo / 10.0), Math.Pow(10.0, nfRadio / 10.0) };
            double[] g = {
                Math.Pow(10.0, -rx.PreLoss / 10.0), Math.Pow(10.0, rx.PreGain / 10.0), Math.Pow(10.0, -rx.PostLoss / 10.0),
                Math.Pow(10.0, rx.TvGain / 10.0), Math.Pow(10.0, -rx.TvCavo / 10.0), 1.0 };
            double ftot = f[0], gcum = g[0];
            for (int i = 1; i < f.Length; i++)
            {
                ftot += (f[i] - 1.0) / gcum;
                gcum *= g[i];
            }
            return 10.0 * Math.Log10(ftot);
        }

        string GainTxt(BudgetParams b, double gt)
        {
            if (b.NAnt <= 1) return gt.ToString("F1", ci) + " dBi";
            return string.Format(ci, "{0} × {1:F1} dBi = {2:F1} dBi", b.NAnt, b.GAnt, gt);
        }

        string GroundTxt(BudgetParams b, double gg, double el, double f)
        {
            if (b.GroundOn < 0.5) return Lang.T("non attivo (antenna con elevazione)");
            if (b.GroundH <= 0) return string.Format(ci, Lang.T("+{0:F1} dB (valore fisso)"), gg);
            return string.Format(ci, Lang.T("{0}{1:F1} dB  (h {2:0.#} m, El {3:F1}°, 1° lobo a {4:F1}°)"),
                gg >= 0 ? "+" : "", gg, b.GroundH, el, PrimoLobo(b.GroundH, f));
        }

        ListView lvCur;

        void RigaB(string a, string b, string c, Color back, bool bold, Color foreB, Color foreC)
        {
            ListViewItem it = new ListViewItem(a);
            it.UseItemStyleForSubItems = false;
            ListViewItem.ListViewSubItem sb = it.SubItems.Add(b);
            ListViewItem.ListViewSubItem sc = it.SubItems.Add(c);
            Font f = bold ? new Font(lvCur.Font, FontStyle.Bold) : lvCur.Font;
            it.Font = f; sb.Font = f; sc.Font = f;
            it.BackColor = back; sb.BackColor = back; sc.BackColor = back;
            it.ForeColor = Tema.FieldFore;
            sb.ForeColor = foreB; sc.ForeColor = foreC;
            bufB.Add(it);
        }

        void RigaB(string a, string b, string c) { RigaB(a, b, c, Tema.Field, false, Tema.FieldFore, Tema.FieldFore); }
        void SezioneB(string a)
        {
            RigaB(a, "", "", Tema.Section, true, Tema.FieldFore, Tema.FieldFore);
            bufB[bufB.Count - 1].Tag = "sez";
        }

        // Scrive le righe raccolte; con riduci = true per ogni capitolo mostra solo l'intestazione e la riga finale
        void FlushB(bool riduci)
        {
            ListViewItem ultima = null;
            bool inSez = false;
            foreach (ListViewItem it in bufB)
            {
                bool sez = (it.Tag as string) == "sez";
                if (!riduci) { lvCur.Items.Add(it); continue; }
                if (sez)
                {
                    if (ultima != null) lvCur.Items.Add(ultima);
                    ultima = null;
                    lvCur.Items.Add(it);
                    inSez = true;
                }
                else if (inSez) ultima = it;
                else lvCur.Items.Add(it);
            }
            if (riduci && ultima != null) lvCur.Items.Add(ultima);
            bufB.Clear();
        }
        void RigaSN(string a, double x, double y)
        {
            RigaB(a, (x >= 0 ? "+" : "") + Db(x), (y >= 0 ? "+" : "") + Db(y), Tema.SnBg, true,
                x >= 0 ? Tema.OkFg : Tema.BadFg, y >= 0 ? Tema.OkFg : Tema.BadFg);
        }
        static string K(double t) { return t.ToString("F0", CultureInfo.CurrentCulture) + " K"; }

        void RecalcBudget()
        {
            if (lvB == null || loadingB) return;
            FillBudget(lvB, false);
            DimensionaTabB();
            if (lvS != null) FillBudget(lvS, true);
            if (tabs != null && tpExcel != null && tabs.SelectedTab == tpExcel) RiempiExcel();
            RiempiDebug();
        }

        static readonly double[] TauValori = { 0.1, 0.2, 0.5, 1, 2, 5, 10, 20, 30, 60 };
        double LeggiTau() { return cmbTau != null && cmbTau.SelectedIndex >= 0 ? TauValori[cmbTau.SelectedIndex] : 1.0; }
        static readonly double[] RosValori = { 1.0, 1.1, 1.2, 1.3, 1.5, 1.7, 2.0, 2.5, 3.0 };
        double LeggiRos() { return cmbRos != null && cmbRos.SelectedIndex >= 0 ? RosValori[cmbRos.SelectedIndex] : 1.0; }
        static double RhoDaRos(double ros) { double g = (ros - 1.0) / (ros + 1.0); return g * g; }

        double LeggiBw()
        {
            double v;
            if (cmbBw != null && double.TryParse(cmbBw.Text.Trim(), NumberStyles.Float, inv, out v) && v >= 1 && v <= 100000) return v;
            return 2500;
        }

        // calcolo dell'eco della propria stazione (Budget EME yagi e dischi): io trasmetto e ricevo il mio eco
        Spunta chkEco;
        bool budgetEco;

        void FillEco(ListView target, BudgetParams pm, BudgetParams pd)
        {
            target.BeginUpdate();
            try
            {
                target.Items.Clear();
                bufB.Clear();
                if (!me.Ok)
                {
                    AggiornaSchemaEKpi(pm, pd, null, null, null, 0, 0, LeggiBw(), false);
                    RigaB(Lang.T("Imposta un locator valido per la tua stazione nella linguetta \"Posizione della Luna\"."), "", "");
                    return;
                }
                double freq = curBand, bw = LeggiBw();
                DateTime t = DateTime.SpecifyKind(dtpB.Value, DateTimeKind.Utc);
                Riga r = Calcola1(t, false, freq, chkRefr.Checked);
                double d = r.P.DistTopo;
                double path = Moon.PathLoss(freq, d, d);
                double tsky = Moon.Tsky(r.P.Lambda, freq);
                double gg = pm.GroundOn > 0.5 ? GroundGain(pm.GroundH, r.P.El, freq) : 0.0;
                double polE = chkPol.Checked && PolCircolare ? PerditaCircolare : 0.0;
                Tratta e = CalcTratta(pm, pm, path, polE, tsky, 0, bw, gg, gg, 0, freq);
                Tratta e2 = null;
                SolarInfo so = null;
                if (lvS != null)
                {
                    so = CalcSolar(t, r.P, me, pm, freq, true);
                    if (so.Valid) e2 = CalcTratta(pm, pm, path, polE, tsky, so.Tsun, bw, gg, gg, 0, freq);
                }
                double ritardo = 2.0 * d / 299792.458, dop = 2.0 * r.DopMe;
                CultureInfo c = ci;
                // schede e schema come nel bilancio normale, con la stessa stazione nei due sensi
                AggiornaSchemaEKpi(pm, pd, r, e, e, path, 0, bw, true);
                kpiV[0] = r.OkMe ? Lang.T("SÌ") : Lang.T("NO");
                kpiS[0] = r.OkMe ? Lang.T("Luna puntabile dalla mia stazione") : Lang.T("la Luna non è puntabile dalla mia stazione");
                kpiC[0] = r.OkMe ? Tema.OkFg : Tema.BadFg;
                kpiV[2] = ritardo.ToString("F2", c) + " s";
                kpiS[2] = string.Format(c, Lang.T("Doppler dell'eco {0} Hz"), (dop >= 0 ? "+" : "−") + Math.Abs(dop).ToString("N0", c));
                kpiC[2] = Color.FromArgb(217, 119, 6);
                kpiS[3] = Lang.T("eco della mia stazione: niente perdita di polarizzazione spaziale");
                Tratta es = e2 ?? e;
                double sn25 = Sn2500(es.SNb, bw), marg = sn25 - pm.SnReq;
                kpiV[4] = Segno(es.SNb, c) + " dB";
                kpiS[4] = string.Format(c, e2 != null ? Lang.T("in {0:0} Hz con il Sole · {1} dB in 2500 Hz") : Lang.T("in {0:0} Hz · {1} dB in 2500 Hz"), bw, Segno(sn25, c));
                kpiV[5] = Segno(marg, c) + " dB";
                kpiS[5] = string.Format(c, Lang.T("sulla soglia di {0} ({1} dB in 2500 Hz)"), pm.NomeModo, pm.SnReq.ToString("0.#", c));
                kpiC[5] = marg >= 0 ? Tema.OkFg : Tema.BadFg;
                bMe.Sotto = me.Loc.Text.Trim() + string.Format(c, " · " + Lang.T("Luna") + " Az {0:F1}° El {1:F1}°", r.P.Az, r.P.El);
                if (pnlKpi != null) pnlKpi.Invalidate();

                SezioneB(Lang.T("TRASMISSIONE  (") + curBand.ToString(inv) + " MHz)");
                RigaB(Lang.T("Potenza in uscita"), FmtW(pm.P, c) + "   (" + Dbw(e.PdBW) + ")", "");
                bool conConn = pm.LossConn > 0;
                RigaB(conConn ? Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna + connettori)") : Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna)"),
                    string.Format(c, "{0:F2} + {1:F2} + {2:F2}", pm.LossPa, pm.Rele, pm.LossAnt) + (conConn ? string.Format(c, " + {0:F2}", pm.LossConn) : "") + " = " + Db(e.LossTx), "");
                RigaB(Lang.T("Potenza all'antenna"), FmtW(e.PantW, c) + "   (" + Dbw(e.PdBW - e.LossTx) + ")", "");
                RigaB(Lang.T("Guadagno antenna TX (in spazio libero)"), GainTxt(pm, e.Gtx - gg), "");
                if (pm.GroundOn > 0.5)
                {
                    RigaB(Lang.T("BETA - ground gain antenna TX senza elevazione"), GroundTxt(pm, gg, r.P.El, freq), "");
                    RigaB(Lang.T("Guadagno antenna TX totale"), e.Gtx.ToString("F1", c) + " dBi", "");
                }
                RigaB("EIRP", FmtW(Math.Pow(10.0, e.EirpDbW / 10.0), c) + "   (" + Dbw(e.EirpDbW) + ")", "", Tema.Field, true, Tema.Accent, Tema.Accent);

                SezioneB(Lang.T("PERCORSO TERRA - LUNA - TERRA   (") + FmtDT(t) + " UTC)");
                RigaB(Lang.T("Posizione Luna dalla mia stazione"), string.Format(c, "Az {0:F1}°  El {1:F1}°  ({2})", r.P.Az, r.P.El, r.StatoMe), "");
                RigaB(Lang.T("Distanza Luna: andata / ritorno"), d.ToString("N0", c) + " km / " + d.ToString("N0", c) + " km", "");
                RigaB(Lang.T("Ritardo dell'eco"), ritardo.ToString("F3", c) + " s", "");
                RigaB(Lang.T("Doppler dell'eco"), (dop >= 0 ? "+" : "−") + Math.Abs(dop).ToString("N0", c) + " Hz", "");
                RigaB(Lang.T("Perdita di tratta EME"), Db(path), "", Tema.Field, true, Tema.FieldFore, Tema.FieldFore);
                if (PolCircolare && chkPol.Checked)
                    RigaB(Lang.T("Perdita di polarizzazione (circolare)"), string.Format(ci, Lang.T("{0:F1} dB: polarizzazione circolare, perdita tipica degli illuminatori reali (KA1GT)"), PerditaCircolare), "");
                else
                    RigaB(Lang.T("Perdita di polarizzazione spaziale"), Lang.T("0,0 dB: stessa antenna in trasmissione e ricezione"), "");
                string fin = r.OkMe ? Lang.T("SÌ, Luna puntabile dalla mia stazione") : Lang.T("NO: la Luna non è puntabile dalla mia stazione");
                Color cf = r.OkMe ? Tema.OkFg : Tema.BadFg;
                RigaB(Lang.T("Eco possibile in questo istante"), fin, "", Tema.Field, true, cf, cf);

                SezioneB(Lang.T("RICEZIONE"));
                RigaB(Lang.T("Guadagno antenna RX (in spazio libero)"), GainTxt(pm, e.Grx - gg), "");
                if (pm.GroundOn > 0.5)
                {
                    RigaB(Lang.T("BETA - ground gain antenna RX senza elevazione"), GroundTxt(pm, gg, r.P.El, freq), "");
                    RigaB(Lang.T("Guadagno antenna RX totale"), e.Grx.ToString("F1", c) + " dBi", "");
                }
                RigaB(Lang.T("Segnale ai morsetti dell'antenna RX"), Dbm(e.Sant), "");
                RigaB(Lang.T("Dopo le perdite ante preampli"), Dbm(e.S1), "");
                RigaB(Lang.T("Dopo il preampli"), Dbm(e.S2), "");
                RigaB(Lang.T("Dopo le perdite post preampli"), Dbm(e.S3), "");
                RigaB(Lang.T("Dopo il transverter"), Dbm(e.S4), "");
                RigaB(Lang.T("Perdita cavetti transverter-radio"), Db(pm.TvCavo), "");
                RigaB(Lang.T("All'ingresso della radio (dopo i cavetti)"), Dbm(e.S5), "", Tema.Field, true, Tema.FieldFore, Tema.FieldFore);
                RigaB(Lang.T("MDS della radio"), Dbm(e.Mds), "");
                RigaB(Lang.T("MDS riportato ai morsetti dell'antenna"), Dbm(e.MdsAnt), "");
                RigaB(Lang.T("Margine sopra il MDS"), (e.Margin >= 0 ? "+" : "") + Db(e.Margin), "", Tema.MarginBg, true, e.Margin >= 0 ? Tema.OkFg : Tema.BadFg, Tema.Fore);

                string bwTxt = bw.ToString("0", c) + " Hz";
                SezioneB(Lang.T("RUMORE E RAPPORTO S/N STIMATO  (banda passante ") + bwTxt + ")");
                RigaB(Lang.T("Temperatura del cielo dietro la Luna (Tsky)"), K(e.Tsky), "");
                RigaB(Lang.T("Temperatura d'antenna Tant (tabelle VE7BQH, 30° di elevazione)"), K(e.Tant), "");
                RigaB(Lang.T("Eccesso del cielo dietro la Luna rispetto al riferimento"), K(e.TskyEcc), "");
                RigaB(Lang.T("Rumore del preampli (NF ") + pm.Nf.ToString("F2", c) + " dB)", K(e.Tr), "");
                RigaB(Lang.T("NF della radio stimata dal MDS (banda ") + bwTxt + ")", Db(e.NfRadio), "");
                RigaB(Lang.T("Figura di rumore del ricevitore (Friis, HP/Agilent AN 57-1)"), e.NfTot.ToString("F2", c) + " dB  (Te " + K(e.Tloss) + ")", "", Tema.Field, true, Tema.Accent, Tema.Accent);
                RigaB(Lang.T("Temperatura di sistema Tsys (senza il Sole)"), K(e.Tsys), "");
                RigaB(Lang.T("Costo di 0,1 dB di perdita in più prima del preampli (S/N e G/T)"), Costo01(e).ToString("F2", c) + " dB", "");
                RigaB(Lang.T("Rumore in ") + bwTxt, Dbm(e.Nb), "");
                RigaB(Lang.T("S/N stimato in ") + bwTxt + Lang.T(" (senza il Sole)"), Segno(e.SNb, c) + " dB", "", Tema.Field, true, e.SNb >= 0 ? Tema.OkFg : Tema.Fore, Tema.Fore);
                RigaB(string.Format(c, Lang.T("S/N in 2500 Hz (soglia tipica {0} / {1})"), pm.NomeModo, pm.SnReq.ToString("0.#", c) + " dB"), Segno(Sn2500(e.SNb, bw), c) + " dB", "");
                if (e2 != null)
                {
                    RigaB(Lang.T("Tsys con il Sole (dalla linguetta Rumore solare)"), K(e2.Tsys), "");
                    RigaB(Lang.T("S/N in ") + bwTxt + Lang.T(" con il Sole (dalla linguetta Rumore solare)"), Segno(e2.SNb, c) + " dB", "");
                }
                double sfuMe = double.NaN;
                if (lvS != null) { SolarInfo sy = CalcSolar(t, r.P, me, pm, freq, true); if (sy.Valid) sfuMe = sy.Flux; }
                DiamSole = DiamSoleIl(t);
                RigheFattoreY(null, pm, double.NaN, e, pm, sfuMe, freq, d, c);
            }
            finally
            {
                FlushB(!complessi);
                target.EndUpdate();
            }
        }

        void FillBudget(ListView target, bool solar)
        {
            lvCur = target;
            BudgetParams.Freq = curBand;
            BudgetParams pm = BudgetParams.FromUi(bMe), pd = BudgetParams.FromUi(bDx);
            // perdite calcolate dallo schema, mostrate anche nelle caselle (usate dal foglio Export in Excel dei calcoli)
            foreach (KeyValuePair<BudgetUi, BudgetParams> kv in new KeyValuePair<BudgetUi, BudgetParams>[] {
                new KeyValuePair<BudgetUi, BudgetParams>(bMe, pm), new KeyValuePair<BudgetUi, BudgetParams>(bDx, pd) })
            {
                bool lb = loadingB;
                loadingB = true;
                kv.Key.CavoTx.Value = (decimal)Math.Min(60.0, kv.Value.CavoTx); kv.Key.AccTx.Value = (decimal)Math.Min(60.0, kv.Value.AccTx);
                kv.Key.PreLoss.Value = (decimal)Math.Min(60.0, kv.Value.PreLoss); kv.Key.PostLoss.Value = (decimal)Math.Min(60.0, kv.Value.PostLoss);
                loadingB = lb;
            }
            if (target == lvB && budgetEco) { FillEco(target, pm, pd); return; }
            if (target == lvB && (!me.Ok || !chkDx.Checked || !dx.Ok)) AggiornaSchemaEKpi(pm, pd, null, null, null, 0, 0, LeggiBw(), false);

            target.BeginUpdate();
            try
            {
                target.Items.Clear();
                bufB.Clear();
                if (!me.Ok || !chkDx.Checked || !dx.Ok)
                {
                    RigaB(Lang.T("Imposta un locator valido per la tua stazione e attiva la seconda stazione"), "", "");
                    RigaB(Lang.T("nella linguetta \"Posizione della Luna\": servono le posizioni di entrambe."), "", "");
                    return;
                }
                double freq = curBand;
                double bw = LeggiBw();
                double extra = 0;
                DateTime t = DateTime.SpecifyKind(dtpB.Value, DateTimeKind.Utc);
                Riga r = Calcola1(t, true, freq, chkRefr.Checked);
                double path = Moon.PathLoss(freq, r.P.DistTopo, r.Q.DistTopo);
                double pol = PolScelta(r);
                double tskyDx = Moon.Tsky(r.Q.Lambda, freq);   // cielo visto dal DX
                double tskyMe = Moon.Tsky(r.P.Lambda, freq);   // cielo visto da me
                double ggMe = pm.GroundOn > 0.5 ? GroundGain(pm.GroundH, r.P.El, freq) : 0.0;
                double ggDx = pd.GroundOn > 0.5 ? GroundGain(pd.GroundH, r.Q.El, freq) : 0.0;
                Tratta a = CalcTratta(pm, pd, path, pol, tskyDx, 0, bw, ggMe, ggDx, extra, freq);   // io -> DX
                Tratta b = CalcTratta(pd, pm, path, pol, tskyMe, 0, bw, ggDx, ggMe, extra, freq);   // DX -> io
                if (target == lvB) AggiornaSchemaEKpi(pm, pd, r, a, b, path, pol, bw, true);
                // Rumore solare (stesso calcolo della linguetta "Rumore solare")
                SolarInfo sa = null, sb = null;
                Tratta a2 = null, b2 = null;
                if (lvS != null && (complessi || solar))
                {
                    sa = CalcSolar(t, r.Q, dx, pd, freq, false);  // ricevitore = DX
                    sb = CalcSolar(t, r.P, me, pm, freq, true);   // ricevitore = io
                    a2 = CalcTratta(pm, pd, path, pol, tskyDx, sa.Valid ? sa.Tsun : 0, bw, ggMe, ggDx, extra, freq);
                    b2 = CalcTratta(pd, pm, path, pol, tskyMe, sb.Valid ? sb.Tsun : 0, bw, ggDx, ggMe, extra, freq);
                }
                bool ground = pm.GroundOn > 0.5 || pd.GroundOn > 0.5;

                SezioneB(Lang.T("TRASMISSIONE  (") + curBand.ToString(inv) + " MHz)");
                RigaB(Lang.T("Potenza in uscita"), FmtW(pm.P, ci) + "   (" + Dbw(a.PdBW) + ")", FmtW(pd.P, ci) + "   (" + Dbw(b.PdBW) + ")");
                bool conConn = pm.LossConn > 0 || pd.LossConn > 0;
                RigaB(conConn ? Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna + connettori)") : Lang.T("Perdite TX (cavo PA–relè + relè + cavo antenna)"),
                    string.Format(ci, "{0:F2} + {1:F2} + {2:F2}", pm.LossPa, pm.Rele, pm.LossAnt) + (conConn ? string.Format(ci, " + {0:F2}", pm.LossConn) : "") + " = " + Db(a.LossTx),
                    string.Format(ci, "{0:F2} + {1:F2} + {2:F2}", pd.LossPa, pd.Rele, pd.LossAnt) + (conConn ? string.Format(ci, " + {0:F2}", pd.LossConn) : "") + " = " + Db(b.LossTx));
                RigaB(Lang.T("Potenza all'antenna"), FmtW(a.PantW, ci) + "   (" + Dbw(a.PdBW - a.LossTx) + ")",
                    FmtW(b.PantW, ci) + "   (" + Dbw(b.PdBW - b.LossTx) + ")");
                RigaB(Lang.T("Guadagno antenna TX (in spazio libero)"), GainTxt(pm, a.Gtx - ggMe), GainTxt(pd, b.Gtx - ggDx));
                if (ground)
                {
                    RigaB(Lang.T("BETA - ground gain antenna TX senza elevazione"), GroundTxt(pm, ggMe, r.P.El, freq), GroundTxt(pd, ggDx, r.Q.El, freq));
                    RigaB(Lang.T("Guadagno antenna TX totale"), a.Gtx.ToString("F1", ci) + " dBi", b.Gtx.ToString("F1", ci) + " dBi");
                }
                RigaB("EIRP", FmtW(Math.Pow(10.0, a.EirpDbW / 10.0), ci) + "   (" + Dbw(a.EirpDbW) + ")",
                    FmtW(Math.Pow(10.0, b.EirpDbW / 10.0), ci) + "   (" + Dbw(b.EirpDbW) + ")",
                    Tema.Field, true, Tema.Accent, Tema.Accent);

                SezioneB(Lang.T("PERCORSO TERRA - LUNA - TERRA   (") + FmtDT(t) + " UTC)");
                RigaB(Lang.T("Posizione Luna dalla stazione TX"),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.P.Az, r.P.El, r.StatoMe),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.Q.Az, r.Q.El, r.StatoDx));
                RigaB(Lang.T("Posizione Luna dalla stazione RX"),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.Q.Az, r.Q.El, r.StatoDx),
                    string.Format(ci, "Az {0:F1}°  El {1:F1}°  ({2})", r.P.Az, r.P.El, r.StatoMe));
                RigaB(Lang.T("Distanza Luna: TX / RX"),
                    r.P.DistTopo.ToString("N0", ci) + " km / " + r.Q.DistTopo.ToString("N0", ci) + " km",
                    r.Q.DistTopo.ToString("N0", ci) + " km / " + r.P.DistTopo.ToString("N0", ci) + " km");
                RigaB(Lang.T("Perdita di tratta EME"), Db(path), Db(path), Tema.Field, true, Tema.FieldFore, Tema.FieldFore);
                string polTxt = chkPol.Checked
                    ? string.Format(ci, "{0:F1} dB  (Dpol {1:F0}°)", r.PolLoss, r.Dpol)
                    : string.Format(ci, Lang.T("non inclusa  (Dpol {0:F0}° → {1:F1} dB)"), r.Dpol, r.PolLoss);
                if (PolCircolare)
                {
                    polTxt = chkPol.Checked ? string.Format(ci, Lang.T("{0:F1} dB: polarizzazione circolare, perdita tipica degli illuminatori reali (KA1GT)"), PerditaCircolare)
                        : Lang.T("non inclusa (polarizzazione circolare)");
                    RigaB(Lang.T("Perdita di polarizzazione (circolare)"), polTxt, polTxt);
                }
                else RigaB(Lang.T("Perdita di polarizzazione spaziale"), polTxt, polTxt);
                string fin = r.Ok ? Lang.T("SÌ, finestra comune") : Lang.T("NO: la Luna non è puntabile da entrambe");
                Color cf = r.Ok ? Tema.OkFg : Tema.BadFg;
                RigaB(Lang.T("Collegamento possibile in questo istante"), fin, fin, Tema.Field, true, cf, cf);

                SezioneB(Lang.T("RICEZIONE"));
                RigaB(Lang.T("Guadagno antenna RX (in spazio libero)"), GainTxt(pd, a.Grx - ggDx), GainTxt(pm, b.Grx - ggMe));
                if (ground)
                {
                    RigaB(Lang.T("BETA - ground gain antenna RX senza elevazione"), GroundTxt(pd, ggDx, r.Q.El, freq), GroundTxt(pm, ggMe, r.P.El, freq));
                    RigaB(Lang.T("Guadagno antenna RX totale"), a.Grx.ToString("F1", ci) + " dBi", b.Grx.ToString("F1", ci) + " dBi");
                }
                RigaB(Lang.T("Segnale ai morsetti dell'antenna RX"), Dbm(a.Sant), Dbm(b.Sant));
                RigaB(Lang.T("Dopo le perdite ante preampli"), Dbm(a.S1), Dbm(b.S1));
                RigaB(Lang.T("Dopo il preampli"), Dbm(a.S2), Dbm(b.S2));
                RigaB(Lang.T("Dopo le perdite post preampli"), Dbm(a.S3), Dbm(b.S3));
                RigaB(Lang.T("Dopo il transverter"), Dbm(a.S4), Dbm(b.S4));
                RigaB(Lang.T("Perdita cavetti transverter-radio"), Db(pd.TvCavo), Db(pm.TvCavo));
                RigaB(Lang.T("All'ingresso della radio (dopo i cavetti)"), Dbm(a.S5), Dbm(b.S5),
                    Tema.Field, true, Tema.FieldFore, Tema.FieldFore);
                RigaB(Lang.T("MDS della radio"), Dbm(a.Mds), Dbm(b.Mds));
                RigaB(Lang.T("MDS riportato ai morsetti dell'antenna"), Dbm(a.MdsAnt), Dbm(b.MdsAnt));
                RigaB(Lang.T("Margine sopra il MDS"),
                    (a.Margin >= 0 ? "+" : "") + Db(a.Margin), (b.Margin >= 0 ? "+" : "") + Db(b.Margin),
                    Tema.MarginBg, true,
                    a.Margin >= 0 ? Tema.OkFg : Tema.BadFg, b.Margin >= 0 ? Tema.OkFg : Tema.BadFg);

                string bwTxt = bw.ToString("0", ci) + " Hz";
                SezioneB(Lang.T("RUMORE E RAPPORTO S/N STIMATO  (banda passante ") + bwTxt + ")");
                RigaB(Lang.T("Temperatura del cielo dietro la Luna (Tsky)"), K(a.Tsky), K(b.Tsky));
                RigaB(Lang.T("Temperatura d'antenna Tant (tabelle VE7BQH, 30° di elevazione)"), K(a.Tant), K(b.Tant));
                RigaB(Lang.T("Eccesso del cielo dietro la Luna rispetto al riferimento"), K(a.TskyEcc), K(b.TskyEcc));
                RigaB(Lang.T("Rumore del preampli (NF ") + pd.Nf.ToString("F2", ci) + " / " + pm.Nf.ToString("F2", ci) + " dB)",
                    K(a.Tr), K(b.Tr));
                RigaB(Lang.T("NF della radio stimata dal MDS (banda ") + bwTxt + ")", Db(a.NfRadio), Db(b.NfRadio));
                RigaB(Lang.T("Figura di rumore del ricevitore (Friis, HP/Agilent AN 57-1)"),
                    a.NfTot.ToString("F2", ci) + " dB  (Te " + K(a.Tloss) + ")", b.NfTot.ToString("F2", ci) + " dB  (Te " + K(b.Tloss) + ")",
                    Tema.Field, true, Tema.Accent, Tema.Accent);
                RigaB(Lang.T("Temperatura di sistema Tsys (senza il Sole)"), K(a.Tsys), K(b.Tsys));
                RigaB(Lang.T("Costo di 0,1 dB di perdita in più prima del preampli (S/N e G/T)"), Costo01(a).ToString("F2", ci) + " dB", Costo01(b).ToString("F2", ci) + " dB");
                RigaB(Lang.T("Rumore in ") + bwTxt, Dbm(a.Nb), Dbm(b.Nb));
                RigaSN(Lang.T("S/N stimato in ") + bwTxt + Lang.T(" (senza il Sole)"), a.SNb, b.SNb);
                RigaB(string.Format(ci, Lang.T("S/N in 2500 Hz (soglia tipica {0} / {1})"), pd.NomeModo + " " + pd.SnReq.ToString("0.#", ci), pm.NomeModo + " " + pm.SnReq.ToString("0.#", ci) + " dB"),
                    Segno(Sn2500(a.SNb, bw), ci) + " dB", Segno(Sn2500(b.SNb, bw), ci) + " dB");
                if (a2 != null && !solar)
                {
                    RigaB(Lang.T("Tsys con il Sole (dalla linguetta Rumore solare)"), K(a2.Tsys), K(b2.Tsys));
                    RigaSN(Lang.T("S/N in ") + bwTxt + Lang.T(" con il Sole (dalla linguetta Rumore solare)"), a2.SNb, b2.SNb);
                }

                if (!solar)
                {
                    double sfuA = double.NaN, sfuB = double.NaN;
                    if (lvS != null)
                    {
                        SolarInfo ya = sa ?? CalcSolar(t, r.Q, dx, pd, freq, false), yb = sb ?? CalcSolar(t, r.P, me, pm, freq, true);
                        if (ya.Valid) sfuA = ya.Flux;
                        if (yb.Valid) sfuB = yb.Flux;
                    }
                    DiamSole = DiamSoleIl(t);
                    RigheFattoreY(b, pm, sfuB, a, pd, sfuA, freq, r.P.DistTopo, ci);   // prima colonna = tratta a (riceve il DX), come le righe sopra
                }
                if (solar && a2 != null) AddSolarRows(a, b, a2, b2, sa, sb);
                // gli indicatori S/N del Budget usano l'S/N con il Sole, come l'ultima riga della tabella
                if (target == lvB && a2 != null && sa != null && sb != null && (sa.Valid || sb.Valid)) KpiSn(a2, b2, bw, true);
            }
            finally
            {
                FlushB((target == lvB || (lvX != null && target == lvX)) && !complessi);
                target.EndUpdate();
            }
        }

