        List<KeyValuePair<RectangleF, Action>> cieloZone = new List<KeyValuePair<RectangleF, Action>>();
        List<KeyValuePair<RectangleF, string>> cieloFumetti = new List<KeyValuePair<RectangleF, string>>();
        string cieloFumetto = "";
