        // 0 affidabile (8 caratteri o più), 1 indicativo (6), 2 non calcolato (4), 3 terreno non disponibile (fuori da SRTM1), −1 locator non valido
        static int StatoLocDx(string loc, double lat)
        {
            string t = (loc ?? "").Trim();
            if (t.Length < 4) return -1;
            if (lat > 60.0 || lat < -56.0) return 3;
            if (t.Length < 6) return 2;
            if (t.Length < 8) return 1;
            return 0;
        }

        // orizzonte salvato di un locator DX (letto una volta sola dal disco)
        Orizzonte OrizzonteDi(string loc)
        {
            loc = (loc ?? "").Trim().ToUpperInvariant();
            if (loc.Length < 4) return null;
            Orizzonte o;
            if (orizDxCache.TryGetValue(loc, out o)) return o;
            string pp = Orizzonte.PercorsoDx(loc);
            o = File.Exists(pp) ? Orizzonte.Carica(pp) : null;
            orizDxCache[loc] = o;
            return o;
        }

        string DxLoc { get { return dx == null ? "" : dx.Loc.Text.Trim().ToUpperInvariant(); } }
        int StatoDx { get { return dx == null || !dx.Ok ? -1 : StatoLocDx(DxLoc, dx.Lat); } }
        bool OrizzonteDxValido
        {
            get
            {
                int st = StatoDx;
                return st >= 0 && st <= 1 && orizzDx != null && orizzDx.Valido && string.Equals(orizzDx.Loc.Trim(), DxLoc, StringComparison.OrdinalIgnoreCase);
            }
        }
        // il terreno del DX entra nei calcoli: casella attiva, seconda stazione attiva e orizzonte calcolato per il suo locator
        bool TerrenoDxAttivo { get { return usaTerrenoDx && chkDx != null && chkDx.Checked && dx != null && dx.Orizzonte != null; } }

        // stesse caselle e stessa altezza dell'antenna del DX ovunque
        Spunta CasellaTerrenoDx(string testo)
        {
            Spunta c = new Spunta();
            c.Text = testo;
            c.AutoSize = true;
            c.Colore = Color.FromArgb(22, 163, 74);
            c.Checked = usaTerrenoDx;
            c.Margin = new Padding(S(6), S(3), S(6), S(3));
            tip.SetToolTip(c, Lang.T("Ostruzioni del terreno del DX") + "\u0001" + Lang.T("La Luna conta come visibile dal DX solo quando sta sopra il suo terreno, calcolato dai dati SRTM1 attorno al suo locator (linguetta «Il mio orizzonte», vista DX): vale per le finestre comuni, la tabella, la barra delle 24 ore, la Volta celeste e Stazioni da provare. Serve un locator di almeno 6 caratteri; con 6 il risultato è indicativo."));
            c.CheckedChanged += (s, e) => { if (orizSync) return; usaTerrenoDx = c.Checked; TerrenoCambiato(true); };
            chkTerrenoDxAltrove.Add(c);
            return c;
        }
        NumericUpDown NudAntDx()
        {
            NumericUpDown n = Nud(0, 300, antDxSuolo, 0, 60);
            tip.SetToolTip(n, Lang.T("Altezza dell'antenna del DX sul suolo (m): di solito non si conosce, 10 m è un valore tipico. Conta per gli ostacoli vicini; cambiala e ricalcola l'orizzonte del DX."));
            n.ValueChanged += (s, e) =>
            {
                if (orizSync) return;
                antDxSuolo = n.Value;
                orizSync = true;
                try { foreach (NumericUpDown x in nudAntDxAltrove) if (x != n) x.Value = Math.Max(x.Minimum, Math.Min(x.Maximum, antDxSuolo)); }
                finally { orizSync = false; }
                if (!caricamento) SaveSettings();
            };
            nudAntDxAltrove.Add(n);
            return n;
        }

        // «Orizzonte dal terreno» o «Stazioni da provare» → tabella della Posizione della Luna: si sceglie una riga e si torna con il pulsante verde
        void VaiTabella(int verso)
        {
            tabRitorno = verso;
            if (btnPosOstacoli != null)
            {
                if (verso == 2)
                {
                    btnPosOstacoli.Text = "↩ " + Lang.T("Stazioni da provare").ToUpper(Lang.Cultura);
                    tip.SetToolTip(btnPosOstacoli, Lang.T("Torna a Stazioni da provare") + "\u0001" + Lang.T("Porta il giorno della riga selezionata nella linguetta Stazioni da provare."));
                }
                else
                {
                    btnPosOstacoli.Text = "↩ " + Lang.T("OSTACOLI");
                    tip.SetToolTip(btnPosOstacoli, Lang.T("Torna a Orizzonte dal terreno") + "\u0001" + Lang.T("Porta il momento della riga selezionata nella vista degli ostacoli della linguetta Il mio orizzonte."));
                }
                btnPosOstacoli.Visible = true;
                if (btnPosOstacoli.Parent != null) btnPosOstacoli.Parent.PerformLayout();
            }
            if (tabs != null && tpPos != null) tabs.SelectedTab = tpPos;
        }
        void OrizVaiTabella() { VaiTabella(1); }
        void OrizTornaOstacoli()
        {
            DateTime t;
            if (!RigaSelezionata(out t)) return;
            int verso = tabRitorno;
            tabRitorno = 0;
            if (btnPosOstacoli != null) btnPosOstacoli.Visible = false;
            if (verso == 2)
            {
                if (dtpStaz != null) dtpStaz.Value = t.Date;
                if (tabs != null && tpStaz != null) tabs.SelectedTab = tpStaz;
                return;
            }
            orizVista = 0;
            MostraVistaOriz();
            ImpostaOrizT(DateTime.SpecifyKind(t, DateTimeKind.Utc));
            if (tabs != null && tpOriz != null) tabs.SelectedTab = tpOriz;
        }
