        void BuildDgFreqTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 1; root.RowCount = 3;
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Padding = new Padding(S(4));

            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true; bar.AutoSizeMode = AutoSizeMode.GrowAndShrink; bar.Dock = DockStyle.Fill; bar.WrapContents = true;
            nudDgfGiorni = Nud(7, 61, 30, 0, 60);
            tip.SetToolTip(nudDgfGiorni, Lang.T("Numero di giorni da oggi da mostrare nel grafico (da 7 a 61)."));
            nudDgfGiorni.ValueChanged += (s, e) => { if (!caricamento) { SaveSettings(); RecalcDgf(true); } };
            lblDgfDal = BoxDgf("", 90);
            Pillola bCalc = new Pillola("▶ " + Lang.T("CALCOLA"), StilePillola.Pieno, Color.FromArgb(31, 111, 209), new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bCalc.Margin = new Padding(S(10), S(2), S(3), S(2));
            bCalc.Click += (s, e) => RecalcDgf(true);
            bar.Controls.Add(L(Lang.T("Giorni"))); bar.Controls.Add(Tonda(nudDgfGiorni));
            bar.Controls.Add(L(Lang.T("dal"))); bar.Controls.Add(Tonda(lblDgfDal)); bar.Controls.Add(bCalc);
            root.Controls.Add(bar, 0, 0);

            FlowLayoutPanel bar2 = new FlowLayoutPanel();
            bar2.AutoSize = true; bar2.AutoSizeMode = AutoSizeMode.GrowAndShrink; bar2.Dock = DockStyle.Fill; bar2.WrapContents = true;
            Label lt = L(Lang.T("Dgrd calcolato su"));
            lt.Font = new Font(Lang.FontUi, 10F * fontFactor, FontStyle.Bold);
            bar2.Controls.Add(lt);
            FlowLayoutPanel fq = Coppia();
            lblDgfMhz = BoxDgf("144", 50); lblDgfKhz = BoxDgf("000", 45);
            Label lnota = L(Lang.T("= frequenza di lavoro della schermata principale"));
            lnota.ForeColor = Tema.Muted;
            fq.Controls.Add(L(Lang.T("Frequenza"))); fq.Controls.Add(Tonda(lblDgfMhz)); fq.Controls.Add(L("MHz")); fq.Controls.Add(Tonda(lblDgfKhz)); fq.Controls.Add(L("kHz")); fq.Controls.Add(lnota);
            bar2.Controls.Add(fq);
            FlowLayoutPanel grx = Coppia();
            grx.Margin = new Padding(S(14), 0, 0, 0);
            rbDgfRx0 = new Tondino(); rbDgfRx0.Text = Lang.T("80 K fissi, come WSJT-X");
            rbDgfRx1 = new Tondino(); rbDgfRx1.Text = Lang.T("la mia stazione dal Budget EME");
            tip.SetToolTip(rbDgfRx0, Lang.T("Ricevitore da 80 K uguale per tutti, come nella Dgrd di WSJT-X: i valori si possono confrontare con quelli di WSJT-X."));
            tip.SetToolTip(rbDgfRx1, Lang.T("Tant e Te della tua stazione, presi dal Budget EME della banda: il rumore del cielo pesa quanto pesa davvero sul tuo impianto."));
            grx.Controls.Add(L(Lang.T("Rumore del ricevitore:"))); grx.Controls.Add(rbDgfRx0); grx.Controls.Add(rbDgfRx1);
            bar2.Controls.Add(grx);
            FlowLayoutPanel gc = Coppia();
            gc.Margin = new Padding(S(14), 0, 0, 0);
            rbDgfC0 = new Tondino(); rbDgfC0.Text = Lang.T("solo il centro della Luna");
            rbDgfC1 = new Tondino(); rbDgfC1.Text = string.Format(Lang.Cultura, Lang.T("mediato sul fascio dell'antenna ({0}°)"), "25");
            tip.SetToolTip(rbDgfC0, Lang.T("Il rumore del cielo nel solo punto in cui si trova la Luna (tabella lungo l'eclittica, come WSJT-X)."));
            tip.SetToolTip(rbDgfC1, Lang.T("Il rumore del cielo mediato su tutto il fascio dell'antenna, con la larghezza ricavata dal guadagno impostato nel Budget EME."));
            gc.Controls.Add(L(Lang.T("Cielo:"))); gc.Controls.Add(rbDgfC0); gc.Controls.Add(rbDgfC1);
            bar2.Controls.Add(gc);
            EventHandler cambia = (s, e) =>
            {
                Tondino t = s as Tondino;
                if (dgfCarica || t == null || !t.Checked) return;
                dgfRx = rbDgfRx1.Checked ? 1 : 0; dgfCielo = rbDgfC1.Checked ? 1 : 0;
                if (!caricamento) { SaveSettings(); RecalcDgf(true); if (dgChart != null) RecalcDgrd(); }
            };
            foreach (Tondino t in new Tondino[] { rbDgfRx0, rbDgfRx1, rbDgfC0, rbDgfC1 }) t.CheckedChanged += cambia;
            DgfMostraScelte();
            root.Controls.Add(bar2, 0, 1);

            pnlDgfScroll = new Panel();
            pnlDgfScroll.Dock = DockStyle.Fill;
            pnlDgfScroll.AutoScroll = true;
            pnlDgf = new PannelloDisegno();
            pnlDgf.Location = new Point(0, 0);
            pnlDgf.Paint += DisegnaDgf;
            pnlDgf.Cursor = Cursors.Hand;
            tip.SetToolTip(pnlDgf, Lang.T("Clicca un giorno nel grafico per vedere come si forma il suo Dgrd e i valori sulle altre bande."));
            pnlDgf.MouseClick += (s, e) =>
            {
                if (e.Button != MouseButtons.Left || dgfArea.Width < 10 || dgfT.Count < 2) return;
                if (!dgfArea.Contains(e.Location)) return;
                double fr = (e.X - dgfArea.Left) / dgfArea.Width;
                DateTime t = new DateTime(dgfStart.Ticks + (long)(fr * (dgfEnd - dgfStart).Ticks), DateTimeKind.Utc);
                dgfSel = t.Date;
                pnlDgf.Invalidate();
            };
            pnlDgfScroll.Controls.Add(pnlDgf);
            Action dim = () =>
            {
                int w = Math.Max(S(1100), pnlDgfScroll.ClientSize.Width);
                int h = Math.Max(S(820), pnlDgfScroll.ClientSize.Height);
                if (h > pnlDgfScroll.ClientSize.Height) w = Math.Max(S(1100), pnlDgfScroll.ClientSize.Width - SystemInformation.VerticalScrollBarWidth);
                if (pnlDgf.Size != new Size(w, h)) pnlDgf.Size = new Size(w, h);
            };
            pnlDgfScroll.Resize += (s, e) => dim();
            dim();
            root.Controls.Add(pnlDgfScroll, 0, 2);
            tp.Controls.Add(root);
        }

        FlowLayoutPanel Coppia()
        {
            FlowLayoutPanel c = new FlowLayoutPanel();
            c.AutoSize = true; c.AutoSizeMode = AutoSizeMode.GrowAndShrink; c.WrapContents = false; c.Margin = new Padding(0);
            return c;
        }

        void DgfMostraScelte()
        {
            if (rbDgfRx0 == null) return;
            dgfCarica = true;
            rbDgfRx0.Checked = dgfRx == 0; rbDgfRx1.Checked = dgfRx == 1;
            rbDgfC0.Checked = dgfCielo == 0; rbDgfC1.Checked = dgfCielo == 1;
            dgfCarica = false;
        }

        // ricalcola la serie (ogni 30 minuti) solo se cambiano giorno, frequenza, locator, scelte o impianto
        void RecalcDgf(bool forza)
        {
            if (pnlDgf == null) return;
            double f;
            if (!ReadFreq(out f)) f = 144;
            string mhz = cmbFreq.Text.Trim(), khz = cmbKhz == null ? "000" : cmbKhz.Text.Trim();
            lblDgfMhz.Text = mhz.Length > 0 ? mhz : "144"; lblDgfKhz.Text = khz.Length > 0 ? khz : "000";
            BudgetParams bp = BpBanda(bpMe, f);
            rbDgfC1.Text = string.Format(Lang.Cultura, Lang.T("mediato sul fascio dell'antenna ({0}°)"), Math.Round(bp.Fascio(f)).ToString("0", Lang.Cultura));
            DateTime now = DateTime.UtcNow;
            DateTime st = new DateTime(now.Year, now.Month, now.Day, 0, 0, 0, DateTimeKind.Utc);
            lblDgfDal.Text = st.ToString("dd/MM/yyyy", inv);
            int ng = (int)nudDgfGiorni.Value;
            string k = st.ToString("yyyyMMdd", inv) + "|" + ng + "|" + f.ToString("F3", inv) + "|" + me.Lat.ToString("F4", inv) + "|" + me.Lon.ToString("F4", inv)
                + "|" + dgfRx + dgfCielo + "|" + bp.Tant.ToString(inv) + "|" + TeStazione(bp).ToString("F1", inv) + "|" + bp.GAnt.ToString(inv) + "|" + bp.NAnt;
            if (!forza && k == dgfChiave) return;
            dgfChiave = k;
            dgfT.Clear(); dgfOld.Clear(); dgfNew.Clear(); dgfP.Clear(); dgfPerigeo.Clear();
            dgfF = f; dgfStart = st; dgfEnd = st.AddDays(ng);
            if (dgfSel < dgfStart || dgfSel >= dgfEnd) dgfSel = dgfStart;
            if (me.Ok)
            {
                int band = BandaVicina(f);
                for (DateTime t = dgfStart; t <= dgfEnd; t = t.AddMinutes(30))
                {
                    MoonPos p = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, false);
                    dgfT.Add(t); dgfP.Add(p);
                    dgfOld.Add(Moon.Dgrd(p.Lambda, p.DistTopo, band));
                    dgfNew.Add(DgrdDett(p, f, bp, dgfRx, dgfCielo).Dgrd);
                }
                // perigeo: minimo della distanza geocentrica
                for (int i = 1; i + 1 < dgfP.Count; i++)
                    if (dgfP[i].Dist < dgfP[i - 1].Dist && dgfP[i].Dist <= dgfP[i + 1].Dist) dgfPerigeo.Add(dgfT[i]);
            }
            pnlDgf.Invalidate();
        }

        // momento del giorno con il Dgrd migliore (Luna sopra l'orizzonte; se non c'è, il migliore del giorno)
        int DgfMomento(DateTime giorno)
        {
            int best = -1, bestSu = -1;
            for (int i = 0; i < dgfT.Count; i++)
            {
                if (dgfT[i].Date != giorno) continue;
                if (best < 0 || dgfNew[i] > dgfNew[best]) best = i;
                if (dgfP[i].El > 0 && (bestSu < 0 || dgfNew[i] > dgfNew[bestSu])) bestSu = i;
            }
            return bestSu >= 0 ? bestSu : best;
        }

        static string Db1(double v, CultureInfo c) { return (v < 0 ? "−" : "") + Math.Abs(v).ToString("F1", c); }

        void DisegnaDgf(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            CultureInfo ci = Lang.Cultura;
            Rectangle cr = pnlDgf.ClientRectangle;
            using (Brush bf = new SolidBrush(Tema.Back)) g.FillRectangle(bf, cr);
            if (cr.Width < 300) return;
            Color viola = Color.FromArgb(124, 58, 237), grigio = Color.FromArgb(148, 163, 184), azzurro = Color.FromArgb(56, 189, 248);
            Color titCol = Tema.Scuro ? Color.FromArgb(196, 181, 253) : Color.FromArgb(91, 33, 182);
            Color violaT = Tema.Scuro ? Color.FromArgb(196, 181, 253) : Color.FromArgb(109, 40, 217);
            float pad = S(8), gap = S(14);
            float wDx = Math.Max(S(420), (cr.Width - 2 * pad - gap) * 0.34f);
            RectangleF cl = new RectangleF(pad, S(6), cr.Width - 2 * pad - gap - wDx, cr.Height - S(14));
            float xr = cl.Right + gap;
            using (Font ft = FontPx(Lang.FontUi, S(13), true))
            using (Font fs = FontPx(Lang.FontUi, S(12.5f), false))
            using (Font fsb = FontPx(Lang.FontUi, S(12.5f), true))
            using (Font fp = FontPx(Lang.FontUi, S(11.5f), false))
            using (Font fpb = FontPx(Lang.FontUi, S(11.5f), true))
            using (Font fbig = FontPx(Lang.FontUi, S(14), true))
            using (Font fmono = FontPx("Consolas", S(12), false))
            using (Brush bTxt = new SolidBrush(Tema.Fore))
            using (Brush bMut = new SolidBrush(Tema.Muted))
            {
                // ----- scheda del grafico
                Scheda(g, cl, Color.Empty);
                DateTime fine = dgfEnd.AddDays(-1);
                string tit = string.Format(ci, Lang.T("DGRD DI {0} A {1} MHz · DAL {2} AL {3} · 0 dB IN BASSO"),
                    me.Loc.Text.Trim().ToUpperInvariant(), dgfF.ToString("0.000", ci), dgfStart.ToString("dd/MM", inv), fine.ToString("dd/MM/yyyy", inv));
                Testo(g, Spaziato(tit), ft, titCol, new RectangleF(cl.Left + S(16), cl.Top + S(12), cl.Width - S(30), S(22)), StringAlignment.Near, StringAlignment.Near);
                if (!me.Ok || dgfT.Count < 2)
                {
                    Testo(g, Lang.T("Imposta un locator valido nella prima linguetta."), fs, Tema.Muted, new RectangleF(cl.Left + S(16), cl.Top + S(50), cl.Width - S(30), S(40)), StringAlignment.Near, StringAlignment.Near);
                }
                else
                {
                    float yLeg = cl.Bottom - S(118);
                    RectangleF a = new RectangleF(cl.Left + S(62), cl.Top + S(44), cl.Width - S(80), yLeg - cl.Top - S(44) - S(30));
                    dgfArea = a;
                    double mn = 0;
                    for (int i = 0; i < dgfT.Count; i++) mn = Math.Min(mn, Math.Min(dgfOld[i], dgfNew[i]));
                    double ymin = Math.Min(-6, 2 * Math.Floor(mn / 2.0 - 0.01));
                    long t0 = dgfStart.Ticks, t1 = dgfEnd.Ticks;
                    Func<DateTime, float> X = t => a.Left + (float)((t.Ticks - t0) / (double)(t1 - t0)) * a.Width;
                    Func<double, float> Y = v => a.Bottom - (float)(v / ymin) * a.Height;
                    using (Brush bg = new SolidBrush(Tema.Scuro ? Tema.Field : Color.FromArgb(251, 252, 254))) g.FillRectangle(bg, a);
                    using (Pen pg = new Pen(Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(227, 232, 240), 1f))
                    {
                        for (double vv = 0; vv >= ymin - 0.01; vv -= 2)
                        {
                            g.DrawLine(pg, a.Left, Y(vv), a.Right, Y(vv));
                            Testo(g, (vv == 0 ? "0" : "−" + (-vv).ToString("0", ci)) + " dB", fp, Tema.Muted, new RectangleF(a.Left - S(60), Y(vv) - S(8), S(55), S(16)), StringAlignment.Far, StringAlignment.Center);
                        }
                        int nd = (int)Math.Round((dgfEnd - dgfStart).TotalDays);
                        int passo = Math.Max(1, (int)Math.Ceiling(nd / 15.0));
                        for (int d = 0; d < nd; d++)
                        {
                            DateTime gd = dgfStart.AddDays(d);
                            if (d % passo == 0)
                            {
                                g.DrawLine(pg, X(gd), a.Top, X(gd), a.Bottom);
                                Testo(g, gd.ToString("dd/MM", inv), fp, Tema.Muted, new RectangleF(X(gd.AddHours(12)) - S(30), a.Bottom + S(3), S(60), S(16)), StringAlignment.Center, StringAlignment.Near);
                            }
                        }
                    }
                    using (Pen pb = new Pen(Tema.Linea, 1f)) g.DrawRectangle(pb, a.X, a.Y, a.Width, a.Height);
                    // giorno scelto
                    if (dgfSel >= dgfStart && dgfSel < dgfEnd)
                    {
                        float xs = X(dgfSel), xe = X(dgfSel.AddDays(1));
                        using (Brush bs = new SolidBrush(Color.FromArgb(48, azzurro))) g.FillRectangle(bs, xs, a.Top, xe - xs, a.Height);
                        bool per = false;
                        foreach (DateTime tp_ in dgfPerigeo) if (tp_.Date == dgfSel) per = true;
                        string ls = dgfSel.ToString("dd/MM", inv) + (per ? " · " + Lang.T("perigeo") : "");
                        using (Brush bz = new SolidBrush(Color.FromArgb(3, 105, 161)))
                        {
                            SizeF sz = g.MeasureString(ls, fpb);
                            g.DrawString(ls, fpb, bz, Math.Min(a.Right - sz.Width, Math.Max(a.Left, (xs + xe) / 2 - sz.Width / 2)), a.Top + S(3));
                        }
                    }
                    // curve
                    PointF[] po = new PointF[dgfT.Count], pn = new PointF[dgfT.Count];
                    for (int i = 0; i < dgfT.Count; i++) { po[i] = new PointF(X(dgfT[i]), Y(dgfOld[i])); pn[i] = new PointF(X(dgfT[i]), Y(dgfNew[i])); }
                    using (Pen p1 = new Pen(grigio, S(2))) { p1.DashPattern = new float[] { 3f, 2f }; g.DrawLines(p1, po); }
                    using (Pen p2 = new Pen(viola, S(2.6f))) { p2.LineJoin = LineJoin.Round; g.DrawLines(p2, pn); }
                    // il punto peggiore del calcolo attuale, con i due valori
                    int iw = 0;
                    for (int i = 1; i < dgfT.Count; i++) if (dgfOld[i] < dgfOld[iw]) iw = i;
                    {
                        float xw = X(dgfT[iw]);
                        bool sinistra = xw > a.Right - S(220);
                        StringAlignment al = sinistra ? StringAlignment.Far : StringAlignment.Near;
                        float xt = sinistra ? xw - S(250) : xw + S(45);
                        RectangleF rt = new RectangleF(xt, Y(dgfOld[iw]) - S(26), S(205), S(18));
                        BudgetParams bpw = BpBanda(bpMe, dgfF);
                        DgfDett dw = DgrdDett(dgfP[iw], dgfF, bpw, dgfRx, dgfCielo);
                        if (dw.Tsky > 2 * dw.Tref) Testo(g, Lang.T("Luna sulla Via Lattea"), fp, Tema.Muted, rt, al, StringAlignment.Near);
                        Testo(g, Lang.T("attuale") + " " + Db1(dgfOld[iw], ci) + " dB", fpb, Tema.Muted, new RectangleF(xt, rt.Bottom, S(205), S(18)), al, StringAlignment.Near);
                        Testo(g, Lang.T("nuovo") + " " + Db1(dgfNew[iw], ci) + " dB", fpb, violaT, new RectangleF(xt, Math.Max(rt.Bottom + S(18), Y(dgfNew[iw]) - S(9)), S(205), S(18)), al, StringAlignment.Near);
                    }
                    // legenda
                    BudgetParams bp = BpBanda(bpMe, dgfF);
                    DgfDett dl = DgrdDett(dgfP[0], dgfF, bp, dgfRx, dgfCielo);
                    string pRx = dgfRx == 1 ? string.Format(ci, Lang.T("Tant {0} K + Te {1} K"), bp.Tant.ToString("0", ci), dl.Te.ToString("0", ci)) : Lang.T("ricevitore 80 K");
                    string pCi = dgfCielo == 1 ? string.Format(ci, Lang.T("fascio {0}°"), dl.Hp.ToString("0", ci)) : Lang.T("cielo al centro della Luna");
                    string[] lg = {
                        string.Format(ci, Lang.T("calcolo attuale (banda {0}, ricevitore 80 K, cielo al centro della Luna)"), BandaVicina(dgfF)),
                        string.Format(ci, Lang.T("nuovo calcolo ({0} MHz, {1}, {2})"), dgfF.ToString("0.000", ci), pRx, pCi),
                        Lang.T("giorno scelto") };
                    float xl = cl.Left + S(16), yl = yLeg;
                    for (int i = 0; i < 3; i++)
                    {
                        SizeF sz = g.MeasureString(lg[i], fs);
                        if (xl + S(34) + sz.Width > cl.Right - S(10)) { xl = cl.Left + S(16); yl += S(20); }
                        if (i == 0) using (Pen p1 = new Pen(grigio, S(3))) { p1.DashPattern = new float[] { 2f, 1.3f }; g.DrawLine(p1, xl, yl + S(9), xl + S(26), yl + S(9)); }
                        else if (i == 1) using (Pen p2 = new Pen(viola, S(3))) g.DrawLine(p2, xl, yl + S(9), xl + S(26), yl + S(9));
                        else using (Brush bs = new SolidBrush(Color.FromArgb(110, azzurro))) g.FillRectangle(bs, xl, yl + S(4), S(26), S(10));
                        g.DrawString(lg[i], fs, bTxt, xl + S(32), yl);
                        xl += S(32) + sz.Width + S(22);
                    }
                    Testo(g, Lang.T("La distanza pesa uguale su tutte le bande; cambia il peso del rumore del cielo. Dove la Luna passa sulla Via Lattea il nuovo calcolo dà un Dgrd meno severo, perché il fascio largo dell'antenna «vede» una media della zona calda e non solo il suo punto più caldo. I giorni migliori (★) di Distanza e Dgrd si calcolano con il nuovo Dgrd."),
                        fp, Tema.Muted, new RectangleF(cl.Left + S(16), yl + S(28), cl.Width - S(32), cl.Bottom - yl - S(32)), StringAlignment.Near, StringAlignment.Near);
                }

                // ----- colonna destra: tre schede
                float y = S(6), wr = wDx;
                int im = dgfT.Count > 0 ? DgfMomento(dgfSel) : -1;
                // 1) come si forma il Dgrd
                float h1 = S(300);
                RectangleF r1 = new RectangleF(xr, y, wr, h1);
                Scheda(g, r1, Color.Empty);
                if (im >= 0)
                {
                    BudgetParams bp = BpBanda(bpMe, dgfF);
                    DgfDett d = DgrdDett(dgfP[im], dgfF, bp, dgfRx, dgfCielo);
                    string t1 = string.Format(ci, Lang.T("COME SI FORMA IL DGRD · {0} UTC · {1} MHz"), dgfT[im].ToString("dd/MM HH:mm", inv), dgfF.ToString("0.000", ci));
                    int ps = t1.IndexOf(" · ");
                    string t1a = ps > 0 ? t1.Substring(0, ps) : t1, t1b = ps > 0 ? t1.Substring(ps + 3) : "";
                    Testo(g, Spaziato(t1a), ft, titCol, new RectangleF(r1.Left + S(16), r1.Top + S(12), r1.Width - S(28), S(20)), StringAlignment.Near, StringAlignment.Near);
                    Testo(g, t1b, fp, Tema.Muted, new RectangleF(r1.Left + S(16), r1.Top + S(32), r1.Width - S(28), S(18)), StringAlignment.Near, StringAlignment.Near);
                    float yy = r1.Top + S(54);
                    string cielo = dgfCielo == 1 ? string.Format(ci, Lang.T("Cielo dietro la Luna (fascio {0}°)"), d.Hp.ToString("0", ci)) : Lang.T("Cielo dietro la Luna (centro)");
                    string tsys = dgfRx == 1
                        ? string.Format(ci, Lang.T("Tsys: Tant {0} + cielo +{1} + Te {2}"), d.Tant.ToString("0", ci), Math.Max(0, d.Tsky - d.Tref).ToString("0", ci), d.Te.ToString("0", ci))
                        : string.Format(ci, Lang.T("Tsys: 80 K + cielo {0} K"), d.Tsky.ToString("0", ci));
                    string[,] rr = {
                        { Lang.T("Distanza della Luna"), d.Dist.ToString("N0", ci) + " km → " + Db1(d.DbDist, ci) + " dB" },
                        { cielo, string.Format(ci, Lang.T("{0} K, freddo {1} K → {2} K"), d.Tsky.ToString("0", ci), d.Tref.ToString("0", ci), (d.Tsky - d.Tref >= 0 ? "+" : "−") + Math.Abs(d.Tsky - d.Tref).ToString("0", ci)) },
                        { tsys, string.Format(ci, Lang.T("{0} K contro {1} K → {2} dB"), d.Tsys.ToString("0", ci), d.Tsys0.ToString("0", ci), Db1(d.DbCielo, ci)) } };
                    for (int i = 0; i < 3; i++)
                    {
                        // etichetta e valore sulla stessa riga se ci stanno, altrimenti il valore va sotto, a destra
                        float wl = g.MeasureString(rr[i, 0], fs).Width, wv = g.MeasureString(rr[i, 1], fsb).Width;
                        bool una = wl + wv + S(12) <= r1.Width - S(32);
                        Testo(g, rr[i, 0], fs, Tema.Fore, new RectangleF(r1.Left + S(16), yy, r1.Width - S(32), S(20)), StringAlignment.Near, StringAlignment.Center);
                        if (!una) yy += S(19);
                        Testo(g, rr[i, 1], fsb, Tema.Fore, new RectangleF(r1.Left + S(16), yy, r1.Width - S(32), S(20)), StringAlignment.Far, StringAlignment.Center);
                        yy += S(22);
                        using (Pen pl = new Pen(Tema.Linea, 1f)) g.DrawLine(pl, r1.Left + S(16), yy - S(1), r1.Right - S(16), yy - S(1));
                    }
                    Testo(g, "Dgrd", fbig, Tema.Fore, new RectangleF(r1.Left + S(16), yy, S(150), S(24)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, Db1(d.Dgrd, ci) + " dB", fbig, violaT, new RectangleF(r1.Right - S(170), yy, S(154), S(24)), StringAlignment.Far, StringAlignment.Center);
                    yy += S(32);
                    RectangleF rf = new RectangleF(r1.Left + S(16), yy, r1.Width - S(32), Math.Max(S(52), r1.Bottom - yy - S(10)));
                    using (GraphicsPath gp = Arrotondato(rf, S(8)))
                    using (Brush bfm = new SolidBrush(Tema.Scuro ? Color.FromArgb(46, 38, 78) : Color.FromArgb(245, 243, 255))) g.FillPath(bfm, gp);
                    // formule scritte come in un editor di equazioni (frazioni, pedici, esponenti), rimpicciolite se la scheda è stretta
                    string f1 = "Dgrd = −40 · log_{10} \\p{\\frac{d}{356.903 \\t{ km}}} − 10 · log_{10} \\p{\\frac{T_{sys}}{T_{sys, \\t{" + Lang.T("freddo") + "}}}}";
                    string f2 = "T_{sky}(f) = T_{sky}(144) · \\p{\\frac{144}{f}}^{" + 2.6.ToString("0.0", ci) + "}";
                    float pxf = S(15);
                    MBox m1 = null, m2 = null;
                    for (int prova = 0; prova < 8; prova++)
                    {
                        m1 = Formula.Analizza(f1, pxf); m2 = Formula.Analizza(f2, pxf);
                        float hTot = m1.A + m1.D + m2.A + m2.D + S(10);
                        if (Math.Max(m1.W, m2.W) <= rf.Width - S(16) && hTot <= rf.Height - S(8)) break;
                        pxf *= 0.9f;
                    }
                    float gapF = Math.Max(S(4), (rf.Height - (m1.A + m1.D + m2.A + m2.D)) / 3f);
                    float yb1 = rf.Top + gapF + m1.A;
                    m1.Draw(g, rf.Left + S(10), yb1, Tema.Fore);
                    m2.Draw(g, rf.Left + S(10), yb1 + m1.D + gapF + m2.A, Tema.Fore);
                }
                y += h1 + gap;
                // 2) stesso momento sulle altre bande
                List<int> bnd = new List<int>();
                foreach (int b in Bande) if (bandeAttive.Contains(b)) bnd.Add(b);
                float h2 = S(112) + bnd.Count * S(22);
                RectangleF r2 = new RectangleF(xr, y, wr, h2);
                Scheda(g, r2, Color.Empty);
                Testo(g, Spaziato(Lang.T("STESSO MOMENTO SULLE ALTRE BANDE (dB)")), ft, titCol, new RectangleF(r2.Left + S(16), r2.Top + S(12), r2.Width - S(28), S(22)), StringAlignment.Near, StringAlignment.Near);
                if (im >= 0)
                {
                    int iw = 0;
                    for (int i = 1; i < dgfT.Count; i++) if (dgfOld[i] < dgfOld[iw]) iw = i;
                    DgfDett dw0 = DgrdDett(dgfP[iw], dgfF, BpBanda(bpMe, dgfF), dgfRx, dgfCielo);
                    string hA = dgfT[im].ToString("dd/MM HH:mm", inv), hB = dgfT[iw].ToString("dd/MM HH:mm", inv) + " " + (dw0.Tsky > 2 * dw0.Tref ? Lang.T("Via Lattea") : Lang.T("peggiore"));
                    // colonne: MHz | Tant | momento A attuale, nuovo | momento B attuale, nuovo
                    float x0c = r2.Left + S(16), wc = wr - S(32);
                    float[] cx = { x0c, x0c + wc * 0.20f, x0c + wc * 0.36f, x0c + wc * 0.52f, x0c + wc * 0.68f, x0c + wc * 0.84f, x0c + wc };
                    float yh = r2.Top + S(40);
                    Testo(g, "MHz", fpb, Tema.Muted, new RectangleF(cx[0], yh, S(80), S(32)), StringAlignment.Near, StringAlignment.Far);
                    Testo(g, "Tant", fpb, Tema.Muted, new RectangleF(cx[1], yh, cx[2] - cx[1], S(32)), StringAlignment.Far, StringAlignment.Far);
                    Testo(g, hA + "\n" + Lang.T("attuale · nuovo"), fpb, Tema.Muted, new RectangleF(cx[2], yh, cx[4] - cx[2], S(32)), StringAlignment.Far, StringAlignment.Far);
                    Testo(g, hB + "\n" + Lang.T("attuale · nuovo"), fpb, Tema.Muted, new RectangleF(cx[4], yh, cx[6] - cx[4], S(32)), StringAlignment.Far, StringAlignment.Far);
                    float yy = yh + S(36);
                    int bandSel = BandaVicina(dgfF);
                    foreach (int b in bnd)
                    {
                        double fb = b == bandSel ? dgfF : DgfFreqEme[Array.IndexOf(Bande, b)];
                        BudgetParams bpb = BpBanda(bpMe, b);
                        MoonPos pa = dgfP[im], pw = dgfP[iw];
                        double oa = Moon.Dgrd(pa.Lambda, pa.DistTopo, b), na = DgrdDett(pa, fb, bpb, dgfRx, dgfCielo).Dgrd;
                        double ow = Moon.Dgrd(pw.Lambda, pw.DistTopo, b), nw = DgrdDett(pw, fb, bpb, dgfRx, dgfCielo).Dgrd;
                        if (b == bandSel) using (Brush bs = new SolidBrush(Tema.Scuro ? Color.FromArgb(60, 124, 58, 237) : Color.FromArgb(237, 233, 254))) g.FillRectangle(bs, r2.Left + S(10), yy, r2.Width - S(20), S(21));
                        Testo(g, fb.ToString("0.000", ci), fs, Tema.Fore, new RectangleF(cx[0], yy, cx[1] - cx[0], S(21)), StringAlignment.Near, StringAlignment.Center);
                        Testo(g, bpb.Tant.ToString("0", ci) + " K", fs, Tema.Fore, new RectangleF(cx[1], yy, cx[2] - cx[1], S(21)), StringAlignment.Far, StringAlignment.Center);
                        Testo(g, Db1(oa, ci), fs, Tema.Fore, new RectangleF(cx[2], yy, cx[3] - cx[2], S(21)), StringAlignment.Far, StringAlignment.Center);
                        Testo(g, Db1(na, ci), fsb, Tema.Fore, new RectangleF(cx[3], yy, cx[4] - cx[3], S(21)), StringAlignment.Far, StringAlignment.Center);
                        Testo(g, Db1(ow, ci), fs, Tema.Fore, new RectangleF(cx[4], yy, cx[5] - cx[4], S(21)), StringAlignment.Far, StringAlignment.Center);
                        Testo(g, Db1(nw, ci), fsb, Tema.Fore, new RectangleF(cx[5], yy, cx[6] - cx[5], S(21)), StringAlignment.Far, StringAlignment.Center);
                        yy += S(22);
                        using (Pen pl = new Pen(Tema.Linea, 1f)) g.DrawLine(pl, r2.Left + S(16), yy - S(1), r2.Right - S(16), yy - S(1));
                    }
                    Testo(g, Lang.T("Tant e Te presi dal Budget EME di ogni banda."), fp, Tema.Muted, new RectangleF(r2.Left + S(16), yy + S(4), r2.Width - S(32), S(32)), StringAlignment.Near, StringAlignment.Near);
                }
                y += h2 + gap;
                // 3) perché cambia con la frequenza
                RectangleF r3 = new RectangleF(xr, y, wr, Math.Max(S(170), cl.Bottom - y));
                Scheda(g, r3, Color.Empty);
                Testo(g, Spaziato(Lang.T("PERCHÉ CAMBIA CON LA FREQUENZA")), ft, titCol, new RectangleF(r3.Left + S(16), r3.Top + S(12), r3.Width - S(28), S(22)), StringAlignment.Near, StringAlignment.Near);
                string pt = "• " + Lang.T("Il rumore del cielo scende con la frequenza (indice 2,6): a 50 MHz è migliaia di kelvin, a 432 MHz poche decine.") + "\n"
                    + "• " + Lang.T("Quanto pesa dipende dal rumore proprio della stazione: con Tant e Te veri, non con 80 K uguali per tutti.") + "\n"
                    + "• " + Lang.T("Il fascio dell'antenna allarga o stringe la zona di cielo che entra nel calcolo.") + "\n"
                    + "• " + Lang.T("Il DX ha il suo Dgrd, calcolato con la sua stazione.");
                Testo(g, pt, fs, Tema.Fore, new RectangleF(r3.Left + S(16), r3.Top + S(40), r3.Width - S(32), r3.Height - S(48)), StringAlignment.Near, StringAlignment.Near);
            }
        }

        // ---------- Linguetta Radar GRAVES (bozzetto approvato) ----------
        // Il radar francese GRAVES (143,050 MHz CW, Broye-lès-Pesmes, JN27SI) illumina il cielo a sud con quattro
        // schiere a fasi: settori D, C, B, A di 45° ciascuno tra 90° e 270° di azimut, ognuno diviso in 6 passi di 7,5°
        // illuminati uno dopo l'altro, nello stesso istante in tutti e quattro i settori (PE1ITR, Bolidozor).
        const double GrLat = 47.348, GrLon = 5.515, GrH = 200, GrMHz = 143.050;
        const double GrElMin = 15, GrElMax = 40;   // elevazione (vista da GRAVES) con cui le eco lunari si ricevono bene
        static readonly string[] GrSettori = { "D", "C", "B", "A" };   // da 90° a 270°
        static readonly Color[] GrColSett = { Color.FromArgb(216, 205, 245), Color.FromArgb(198, 218, 245), Color.FromArgb(167, 139, 250), Color.FromArgb(248, 215, 180) };
        TabPage tpGraves;
        PannelloDisegno pnlGr;
        Panel pnlGrScroll;
        ComboBox cmbGrSeq;
        Spunta chkGrSuono;
        System.Windows.Forms.Timer tmrGr;
        bool grFinPrec;
        DateTime grGiorno = DateTime.MinValue; string grChiave = "";
        bool[] grInFascio = new bool[720], grSopra = new bool[720], grMio = new bool[720];   // passi di 2 minuti nelle 24 ore UTC
        int[] grSett = new int[720];

        double GrPasso { get { return cmbGrSeq != null && cmbGrSeq.SelectedIndex == 1 ? 3.2 : 0.8; } }
        double GrCiclo { get { return GrPasso * 6; } }

        // settore (0..3 = D, C, B, A) e passo (0..5) che contengono un azimut; -1 se fuori dai 90°-270°
        static int GrSettore(double az, out int passo)
        {
            passo = -1;
            if (az < 90 || az >= 270) return -1;
            int s = (int)((az - 90) / 45.0);
            passo = Math.Min(5, (int)((az - 90 - 45 * s) / 7.5));
            return s;
        }

        static bool GrNelFascio(MoonPos g) { return g.Az >= 90 && g.Az < 270 && g.ElGeo >= GrElMin && g.ElGeo <= GrElMax; }

        void BuildGravesTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 1; root.RowCount = 2;
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Padding = new Padding(S(4));

            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true; bar.AutoSizeMode = AutoSizeMode.GrowAndShrink; bar.Dock = DockStyle.Fill; bar.WrapContents = true;
            Label lt = L(Lang.T("Radar GRAVES"));
            lt.Font = new Font(Lang.FontUi, 10F * fontFactor, FontStyle.Bold);
            Label li = L(string.Format(Lang.Cultura, "· {0:0.000} MHz CW · JN27SI (Broye-lès-Pesmes, {1:0.000}° N {2:0.000}° E)", GrMHz, GrLat, GrLon));
            Pillola bNow = new Pillola(Lang.T("Adesso").ToUpper(Lang.Cultura), StilePillola.Pieno, ColPillola, new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bNow.Margin = new Padding(S(10), S(2), S(3), S(2));
            bNow.Click += (s, e) => { grChiave = ""; pnlGr.Invalidate(); };
            Pillola bDx = new Pillola(Lang.T("METTI GRAVES COME DX"), StilePillola.Pieno, Color.FromArgb(124, 58, 237), new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bDx.Margin = new Padding(S(6), S(2), S(3), S(2));
            bDx.Click += (s, e) => ImpostaGraves();
            tip.SetToolTip(bDx, Lang.T("Radar GRAVES come stazione DX"));
            cmbGrSeq = new Tendina();
            cmbGrSeq.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbGrSeq.Items.Add(string.Format(Lang.Cultura, Lang.T("{0} s per passo · ciclo {1} s"), 0.8.ToString("0.0", Lang.Cultura), 4.8.ToString("0.0", Lang.Cultura)) + " (PE1ITR 2021)");
            cmbGrSeq.Items.Add(string.Format(Lang.Cultura, Lang.T("{0} s per passo · ciclo {1} s"), 3.2.ToString("0.0", Lang.Cultura), 19.2.ToString("0.0", Lang.Cultura)) + " (PE1ITR 2007)");
            cmbGrSeq.SelectedIndex = 0;
            cmbGrSeq.Width = S(290);
            cmbGrSeq.SelectedIndexChanged += (s, e) => { pnlGr.Invalidate(); if (!caricamento) SaveSettings(); };
            chkGrSuono = new Spunta();
            chkGrSuono.Text = Lang.T("Avviso sonoro all'apertura della finestra");
            chkGrSuono.AutoSize = true;
            chkGrSuono.Margin = new Padding(S(12), S(3), S(3), S(3));
            chkGrSuono.CheckedChanged += (s, e) => { if (!caricamento) SaveSettings(); };
            tip.SetToolTip(chkGrSuono, Lang.T("Un suono quando si apre la finestra comune con GRAVES (Luna nel fascio del radar e dentro i limiti della tua antenna)."));
            bar.Controls.Add(lt); bar.Controls.Add(li); bar.Controls.Add(bNow); bar.Controls.Add(bDx);
            bar.Controls.Add(L(Lang.T("Sequenza del fascio:"))); bar.Controls.Add(cmbGrSeq); bar.Controls.Add(chkGrSuono);
            root.Controls.Add(bar, 0, 0);

            pnlGrScroll = new Panel();
            pnlGrScroll.Dock = DockStyle.Fill;
            pnlGrScroll.AutoScroll = true;
            pnlGr = new PannelloDisegno();
            pnlGr.Location = new Point(0, 0);
            pnlGr.Paint += DisegnaGraves;
            pnlGrScroll.Controls.Add(pnlGr);
            Action dim = () =>
            {
                int w = Math.Max(S(900), pnlGrScroll.ClientSize.Width);
                int h = Math.Max(S(1060), pnlGrScroll.ClientSize.Height);
                if (h > pnlGrScroll.ClientSize.Height) w = Math.Max(S(900), pnlGrScroll.ClientSize.Width - SystemInformation.VerticalScrollBarWidth);
                if (pnlGr.Size != new Size(w, h)) pnlGr.Size = new Size(w, h);
            };
            pnlGrScroll.Resize += (s, e) => dim();
            dim();
            root.Controls.Add(pnlGrScroll, 0, 1);
            tp.Controls.Add(root);

            // il fascio cambia passo ogni 0,8 s: la pagina si ridisegna 5 volte al secondo, solo quando è visibile
            tmrGr = new System.Windows.Forms.Timer();
            tmrGr.Interval = 200;
            tmrGr.Tick += (s, e) =>
            {
                if (tabs == null || tabs.SelectedTab != tpGraves || !this.Visible) { GrControllaSuono(); return; }
                pnlGr.Invalidate();
            };
            tmrGr.Start();
        }

        // tabella delle 24 ore UTC del giorno (passi di 2 minuti): ricalcolata quando cambiano giorno, locator o limiti
        void GrPrepara(DateTime giorno)
        {
            string k = giorno.ToString("yyyyMMdd", inv) + "|" + me.Lat.ToString("F4", inv) + "|" + me.Lon.ToString("F4", inv) + "|"
                + me.Az1.Value + "|" + me.Az2.Value + "|" + me.El1.Value + "|" + me.El2.Value + "|" + ChiaveTerreno + "|" + DateTime.UtcNow.ToString("yyyyMMddHH", inv);
            if (k == grChiave) return;
            grChiave = k; grGiorno = giorno;
            for (int i = 0; i < 720; i++)
            {
                DateTime t = giorno.AddMinutes(2 * i);
                MoonPos g = Moon.Compute(t, GrLat, GrLon, GrH, false);
                int ps;
                grSopra[i] = g.ElGeo > 0;
                grInFascio[i] = GrNelFascio(g);
                grSett[i] = grInFascio[i] ? GrSettore(g.Az, out ps) : -1;
                bool ok = false;
                if (me.Ok) { MoonPos p = Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, false); me.Valuta(p, out ok); }
                grMio[i] = ok;
            }
        }

        // finestra comune (Luna nel fascio e dentro i limiti della mia antenna) attorno all'istante t, a passi di 1 minuto
        bool GrComune(DateTime t)
        {
            if (!me.Ok) return false;
            MoonPos g = Moon.Compute(t, GrLat, GrLon, GrH, false);
            if (!GrNelFascio(g)) return false;
            bool ok; me.Valuta(Moon.Compute(t, me.Lat, me.Lon, (double)me.H.Value, false), out ok);
            return ok;
        }

        void GrControllaSuono()
        {
            bool ora = me != null && me.Ok && GrComune(DateTime.UtcNow);
            if (ora && !grFinPrec && chkGrSuono != null && chkGrSuono.Checked) { try { System.Media.SystemSounds.Exclamation.Play(); } catch { } }
            grFinPrec = ora;
        }

        void DisegnaGraves(object sender, PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            PreparaGrafica(g);
            CultureInfo ci = Lang.Cultura;
            Rectangle cr = pnlGr.ClientRectangle;
            using (Brush bf = new SolidBrush(Tema.Back)) g.FillRectangle(bf, cr);
            if (cr.Width < 200) return;
            DateTime now = DateTime.UtcNow;
            GrControllaSuono();
            GrPrepara(now.Date);
            MoonPos mg = Moon.Compute(now, GrLat, GrLon, GrH, false);
            int passo; int sett = GrSettore(mg.Az, out passo);
            bool fascio = GrNelFascio(mg);
            bool comune = GrComune(now);
            Color viola = Color.FromArgb(124, 58, 237), blu = Color.FromArgb(31, 111, 209);
            Color titCol = Tema.Scuro ? Color.FromArgb(196, 181, 253) : Color.FromArgb(91, 33, 182);

            float x0 = S(8), y = S(6), wTot = cr.Width - S(16);
            using (Font fh = FontPx(Lang.FontUi, S(12), false))
            using (Font fv = FontPx(Lang.FontUi, S(28), true))
            using (Font fs = FontPx(Lang.FontUi, S(13), false))
            using (Font fsb = FontPx(Lang.FontUi, S(13), true))
            using (Font ft = FontPx(Lang.FontUi, S(14), true))
            using (Font fp = FontPx(Lang.FontUi, S(12), false))
            using (Font fpb = FontPx(Lang.FontUi, S(12), true))
            {
                // --- quattro schede
                float gap = S(14), wc = (wTot - 3 * gap) / 4f, hc = S(104);
                string[] tit = new string[4], val = new string[4], sot = new string[4];
                Color[] col = new Color[4];
                tit[0] = Lang.T("LUNA NEL FASCIO DI GRAVES");
                val[0] = fascio ? string.Format(ci, Lang.T("SÌ · settore {0}"), GrSettori[sett]) : Lang.T("NO");
                sot[0] = string.Format(ci, fascio ? Lang.T("Luna da GRAVES: Az {0}° · El {1}° (passo {2} di 6)") : Lang.T("Luna da GRAVES: Az {0}° · El {1}° (fuori dal fascio)"),
                    mg.Az.ToString("F1", ci), mg.ElGeo.ToString("F1", ci), passo + 1);
                col[0] = fascio ? Tema.OkFg : Tema.Muted;
                // finestra comune: quando chiude o quando si apre (cerca minuto per minuto nelle prossime 24 ore)
                tit[1] = Lang.T("FINESTRA COMUNE CON TE");
                DateTime tf = now; int lim = 24 * 60;
                if (comune)
                {
                    int m = 1; while (m < lim && GrComune(now.AddMinutes(m))) m++;
                    tf = now.AddMinutes(m);
                    TimeSpan rest = tf - now;
                    val[1] = Lang.T("aperta") + " · " + string.Format(ci, Lang.T("{0} h {1} min"), (int)rest.TotalHours, rest.Minutes.ToString("00", ci));
                    sot[1] = string.Format(ci, Lang.T("chiude alle {0} UTC"), tf.ToString("HH:mm", inv));
                    col[1] = blu;
                }
                else
                {
                    int m = 1; while (m < lim && !GrComune(now.AddMinutes(m))) m++;
                    val[1] = Lang.T("chiusa");
                    sot[1] = m < lim ? string.Format(ci, Lang.T("si apre alle {0} UTC"), now.AddMinutes(m).ToString("HH:mm", inv)) : Lang.T("nessuna finestra nelle prossime 24 ore");
                    col[1] = Tema.Muted;
                }
                if (!me.Ok) sot[1] = Lang.T("Imposta un locator valido nella prima linguetta.");
                // Doppler bistatico GRAVES -> Luna -> me e ritardo dell'eco
                tit[2] = string.Format(ci, Lang.T("DOPPLER DELL'ECO SU {0}"), GrMHz.ToString("0.000", ci));
                double dop = 0, rit = 0;
                if (me.Ok)
                {
                    double h = (double)me.H.Value;
                    double r1 = Moon.Compute(now.AddSeconds(-30), GrLat, GrLon, GrH, false).DistTopo + Moon.Compute(now.AddSeconds(-30), me.Lat, me.Lon, h, false).DistTopo;
                    double r2 = Moon.Compute(now.AddSeconds(30), GrLat, GrLon, GrH, false).DistTopo + Moon.Compute(now.AddSeconds(30), me.Lat, me.Lon, h, false).DistTopo;
                    dop = -GrMHz * 1e6 * ((r2 - r1) / 60.0) / 299792.458;
                    rit = (mg.DistTopo + Moon.Compute(now, me.Lat, me.Lon, h, false).DistTopo) / 299792.458;
                    val[2] = (dop >= 0 ? "+" : "−") + Math.Abs(dop).ToString("F0", ci) + " Hz";
                    double fr = GrMHz + dop / 1e6;
                    string frs = fr.ToString("0.000000", ci);
                    frs = frs.Substring(0, frs.Length - 3) + " " + frs.Substring(frs.Length - 3);
                    sot[2] = string.Format(ci, Lang.T("ascolta a {0} MHz · ritardo dell'eco ≈ {1} s"), frs, rit.ToString("0.00", ci));
                }
                else { val[2] = "—"; sot[2] = Lang.T("Imposta un locator valido nella prima linguetta."); }
                col[2] = Color.FromArgb(217, 119, 6);
                // prossimo passaggio del fascio sulla Luna (sequenza legata all'ora UTC)
                tit[3] = Lang.T("PROSSIMO PASSAGGIO DEL FASCIO SULLA LUNA");
                double ciclo = GrCiclo, pp = GrPasso;
                double sec = now.TimeOfDay.TotalSeconds, fase = sec % ciclo;
                double prox = 0;
                if (fascio)
                {
                    double ini = passo * pp;
                    prox = (fase >= ini && fase < ini + pp) ? 0 : ((ini - fase) % ciclo + ciclo) % ciclo;
                    val[3] = prox <= 0 ? Lang.T("adesso") : string.Format(ci, Lang.T("tra {0} s"), prox.ToString("0.0", ci));
                    List<string> arr = new List<string>();
                    double t0 = sec + prox + (prox <= 0 ? ini - fase : 0) + rit;
                    for (int k = 0; k < 3; k++) { double ts = (t0 + k * ciclo) % 60.0; arr.Add(":" + ts.ToString("00.0", ci)); }
                    sot[3] = string.Format(ci, Lang.T("ogni {0} s · l'eco arriva {1} s dopo: a {2}"), ciclo.ToString("0.0", ci), rit.ToString("0.0", ci), string.Join(" · ", arr.ToArray()) + " …");
                    col[3] = viola;
                }
                else { val[3] = "—"; sot[3] = Lang.T("La Luna non è nel fascio di GRAVES in questo momento."); col[3] = Tema.Muted; }
                for (int i = 0; i < 4; i++)
                {
                    RectangleF r = new RectangleF(x0 + i * (wc + gap), y, wc, hc);
                    Scheda(g, r, col[i] == Tema.Muted ? Tema.Linea : col[i]);
                    Testo(g, Spaziato(tit[i]), fh, Tema.Muted, new RectangleF(r.Left + S(20), r.Top + S(10), r.Width - S(26), S(18)), StringAlignment.Near, StringAlignment.Near);
                    Testo(g, val[i], fv, col[i], new RectangleF(r.Left + S(18), r.Top + S(28), r.Width - S(24), S(40)), StringAlignment.Near, StringAlignment.Center);
                    Testo(g, sot[i], fs, Tema.Fore, new RectangleF(r.Left + S(20), r.Top + S(70), r.Width - S(26), S(24)), StringAlignment.Near, StringAlignment.Center);
                }
                y += hc + S(16);

                // --- il cielo visto da GRAVES (sinistra) e ricostruzione cronologica (destra)
                float hMid = S(600), wL = Math.Max(S(360), wTot * 0.28f), wR = wTot - wL - gap;
                RectangleF cl = new RectangleF(x0, y, wL, hMid), crr = new RectangleF(x0 + wL + gap, y, wR, hMid);
                Scheda(g, cl, Color.Empty); Scheda(g, crr, Color.Empty);
                Testo(g, Spaziato(Lang.T("IL CIELO VISTO DA GRAVES")), ft, titCol, new RectangleF(cl.Left + S(18), cl.Top + S(14), cl.Width - S(30), S(22)), StringAlignment.Near, StringAlignment.Near);
                float rad = Math.Min(cl.Width - S(90), S(360)) / 2f;
                PointF c = new PointF(cl.Left + cl.Width / 2f, cl.Top + S(70) + rad);
                Func<double, double, PointF> P = (az, el) =>
                {
                    double rr = rad * (90 - Math.Max(0, el)) / 90.0, a = az * Math.PI / 180;
                    return new PointF(c.X + (float)(rr * Math.Sin(a)), c.Y - (float)(rr * Math.Cos(a)));
                };
                using (Brush bc = new SolidBrush(Tema.Scuro ? Color.FromArgb(40, 255, 255, 255) : Color.FromArgb(241, 244, 250))) g.FillEllipse(bc, c.X - rad, c.Y - rad, 2 * rad, 2 * rad);
                // i quattro settori (spicchi da 45°) tra 90° e 270°
                for (int s = 0; s < 4; s++)
                    using (Brush bs = new SolidBrush(Color.FromArgb(Tema.Scuro ? 120 : 255, GrColSett[s])))
                        g.FillPie(bs, c.X - rad, c.Y - rad, 2 * rad, 2 * rad, (float)(90 + 45 * s - 90), 45f);
                // il passo illuminato adesso nel settore della Luna (o in tutti i settori, che si muovono insieme)
                {
                    int pAdesso = (int)(fase / pp) % 6;
                    for (int s = 0; s < 4; s++)
                    {
                        bool qui = fascio && s == sett;
                        using (Brush bp = new SolidBrush(qui ? Color.FromArgb(240, 250, 204, 21) : Color.FromArgb(70, 250, 204, 21)))
                            g.FillPie(bp, c.X - rad, c.Y - rad, 2 * rad, 2 * rad, (float)(90 + 45 * s + 7.5 * pAdesso - 90), 7.5f);
                    }
                }
                using (Pen pr = new Pen(Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(200, 206, 218)))
                {
                    for (int el = 0; el < 90; el += 30) { float rr = rad * (90 - el) / 90f; g.DrawEllipse(pr, c.X - rr, c.Y - rr, 2 * rr, 2 * rr); }
                    g.DrawLine(pr, c.X - rad, c.Y, c.X + rad, c.Y); g.DrawLine(pr, c.X, c.Y - rad, c.X, c.Y + rad);
                }
                for (int s = 0; s < 4; s++)
                {
                    PointF pl = P(90 + 45 * s + 22.5, 30);
                    Testo(g, GrSettori[s], ft, s == 2 ? Color.White : titCol, new RectangleF(pl.X - S(15), pl.Y - S(12), S(30), S(24)), StringAlignment.Center, StringAlignment.Center);
                }
                string[] card = { "N", "E", "S", Lang.T("O") };
                for (int k = 0; k < 4; k++)
                {
                    PointF pc = P(90 * k, -12);
                    double a = 90 * k * Math.PI / 180;
                    pc = new PointF(c.X + (float)((rad + S(14)) * Math.Sin(a)), c.Y - (float)((rad + S(14)) * Math.Cos(a)));
                    Testo(g, card[k], fsb, Tema.Fore, new RectangleF(pc.X - S(15), pc.Y - S(11), S(30), S(22)), StringAlignment.Center, StringAlignment.Center);
                }
                // percorso della Luna nelle prossime 12 ore (sopra l'orizzonte di GRAVES)
                using (Pen pt = new Pen(Tema.Fore, S(1.4f)))
                {
                    pt.DashStyle = DashStyle.Dash;
                    PointF? prev = null;
                    for (int m = 0; m <= 720; m += 10)
                    {
                        MoonPos q = Moon.Compute(now.AddMinutes(m), GrLat, GrLon, GrH, false);
                        if (q.ElGeo < 0) { prev = null; continue; }
                        PointF pq = P(q.Az, q.ElGeo);
                        if (prev != null) g.DrawLine(pt, prev.Value, pq);
                        prev = pq;
                    }
                }
                Testo(g, Lang.T("percorso della Luna nelle prossime 12 h"), fp, Tema.Muted, new RectangleF(c.X - rad, c.Y - rad - S(4), 2 * rad, S(18)), StringAlignment.Center, StringAlignment.Near);
                if (mg.ElGeo >= 0)
                {
                    PointF pm = P(mg.Az, mg.ElGeo);
                    using (Brush bm = new SolidBrush(Color.FromArgb(29, 36, 51))) g.FillEllipse(bm, pm.X - S(9), pm.Y - S(9), S(18), S(18));
                    using (Pen pw = new Pen(Color.White, S(2))) g.DrawEllipse(pw, pm.X - S(9), pm.Y - S(9), S(18), S(18));
                    TestoBordato(g, Lang.T("Luna").ToUpper(ci), fsb, Color.White, pm.X + S(10), pm.Y - S(26));
                }
                string spieg = Lang.T("Quattro schiere a fasi coprono il cielo a sud, da 90° a 270° di azimut, in quattro settori di 45° (D, C, B, A); ogni settore è diviso in 6 passi da 7,5°, illuminati uno dopo l'altro, nello stesso momento in tutti e quattro i settori. Il fascio è largo circa 25° in elevazione: le eco lunari si ricevono bene con la Luna tra 15° e 40° di elevazione vista da GRAVES.");
                Testo(g, spieg, fs, Tema.Fore, new RectangleF(cl.Left + S(18), c.Y + rad + S(26), cl.Width - S(36), cl.Bottom - (c.Y + rad + S(26)) - S(10)), StringAlignment.Near, StringAlignment.Near);

                // ricostruzione cronologica delle 24 ore UTC
                Testo(g, Spaziato(string.Format(ci, Lang.T("RICOSTRUZIONE CRONOLOGICA DELLE TRASMISSIONI · {0} UTC"), now.ToString("dd/MM", inv))), ft, titCol,
                    new RectangleF(crr.Left + S(18), crr.Top + S(14), crr.Width - S(30), S(22)), StringAlignment.Near, StringAlignment.Near);
                float lx = crr.Left + S(18), wl = Math.Min(S(170), crr.Width * 0.18f), bx = lx + wl, bw = crr.Right - S(18) - bx, rh = S(26), ry = crr.Top + S(48);
                Func<double, float> Xh = hh => bx + (float)(hh / 24.0 * bw);
                string[] righe = { Lang.T("Luna da GRAVES"), string.Format(ci, Lang.T("Luna da {0}"), me.Ok ? me.Loc.Text.Trim().ToUpper(inv).Substring(0, Math.Min(6, me.Loc.Text.Trim().Length)) : "—"), Lang.T("Settore illuminato"), Lang.T("Finestra comune") };
                Color fondoBarra = Tema.Scuro ? Color.FromArgb(50, 255, 255, 255) : Color.FromArgb(236, 239, 244);
                for (int rr = 0; rr < 4; rr++)
                {
                    float yy = ry + rr * S(46);
                    Testo(g, righe[rr], rr == 3 ? fsb : fs, Tema.Fore, new RectangleF(lx, yy, wl - S(6), rh), StringAlignment.Near, StringAlignment.Center);
                    using (Brush bb = new SolidBrush(fondoBarra)) g.FillRectangle(bb, bx, yy + S(3), bw, rh - S(6));
                    int i0 = 0;
                    while (i0 < 720)
                    {
                        int i1 = i0;
                        Func<int, int> chiave = i =>
                        {
                            if (rr == 0) return grInFascio[i] ? 2 : (grSopra[i] ? 1 : 0);
                            if (rr == 1) return grMio[i] ? 1 : 0;
                            if (rr == 2) return grSett[i] + 1;
                            return grInFascio[i] && grMio[i] ? 1 : 0;
                        };
                        int kv = chiave(i0);
                        while (i1 < 720 && chiave(i1) == kv) i1++;
                        if (kv > 0)
                        {
                            Color cb = rr == 0 ? (kv == 2 ? Color.FromArgb(167, 139, 250) : Color.FromArgb(170, 200, 245)) : rr == 1 ? Color.FromArgb(120, 200, 150)
                                : rr == 2 ? GrColSett[kv - 1] : Color.FromArgb(22, 163, 74);
                            RectangleF rb = new RectangleF(Xh(i0 / 30.0), yy + S(3), Xh(i1 / 30.0) - Xh(i0 / 30.0), rh - S(6));
                            using (Brush bk = new SolidBrush(cb)) g.FillRectangle(bk, rb);
                            if (rr == 2 && rb.Width > S(14)) Testo(g, GrSettori[kv - 1], fsb, Color.FromArgb(29, 36, 51), rb, StringAlignment.Center, StringAlignment.Center);
                            if (rr == 3)
                            {
                                DateTime a = now.Date.AddMinutes(2 * i0), b = now.Date.AddMinutes(2 * i1);
                                TimeSpan d = b - a;
                                string tw = a.ToString("HH:mm", inv) + " → " + b.ToString("HH:mm", inv) + " UTC · " + string.Format(ci, Lang.T("{0} h {1} min"), (int)d.TotalHours, d.Minutes.ToString("00", ci));
                                if (g.MeasureString(tw, fpb).Width < rb.Width - S(8)) Testo(g, tw, fpb, Color.White, new RectangleF(rb.Left + S(6), rb.Top, rb.Width - S(8), rb.Height), StringAlignment.Near, StringAlignment.Center);
                            }
                        }
                        i0 = i1;
                    }
                }
                float yAx = ry + 4 * S(46) - S(10);
                for (int hh = 0; hh <= 24; hh += 3)
                    Testo(g, hh.ToString("00", inv), fp, Tema.Muted, new RectangleF(Xh(hh) - S(15), yAx, S(30), S(18)), StringAlignment.Center, StringAlignment.Near);
                float xn = Xh(now.TimeOfDay.TotalHours);
                using (Pen pn = new Pen(Color.FromArgb(220, 38, 38), S(2))) g.DrawLine(pn, xn, ry - S(4), xn, ry + 3 * S(46) + rh);
                using (Brush br = new SolidBrush(Color.FromArgb(220, 38, 38))) g.DrawString(Lang.T("adesso") + " " + now.ToString("HH:mm", inv), fpb, br, xn + S(3), ry - S(6));

                // dettaglio dei prossimi 10 secondi
                float yd = yAx + S(34);
                if (fascio)
                {
                    string sl = GrSettori[sett];
                    Testo(g, string.Format(ci, Lang.T("Dettaglio dei prossimi 10 s: passi del fascio nel settore {0} ({1} s ciascuno) e arrivo dell'eco"), sl, pp.ToString("0.0", ci)),
                        fsb, Tema.Fore, new RectangleF(bx, yd, bw, S(20)), StringAlignment.Near, StringAlignment.Near);
                    float yb = yd + S(26), hb = S(26);
                    double t0 = sec, t1 = sec + 10;
                    Func<double, float> Xs = ts => bx + (float)((ts - t0) / 10.0 * bw);
                    double ini = Math.Floor(t0 / pp) * pp;
                    for (double ts = ini; ts < t1; ts += pp)
                    {
                        int pk = (int)Math.Round((ts % ciclo) / pp) % 6;
                        float xa = Math.Max(bx, Xs(ts)), xb = Math.Min(bx + bw, Xs(ts + pp));
                        if (xb - xa < 2) continue;
                        bool luna = pk == passo;
                        RectangleF rb = new RectangleF(xa + 1, yb, xb - xa - 2, hb);
                        using (Brush bk = new SolidBrush(luna ? Color.FromArgb(250, 204, 21) : (Tema.Scuro ? Color.FromArgb(60, 167, 139, 250) : Color.FromArgb(237, 233, 254)))) g.FillRectangle(bk, rb);
                        string tb = sl + pk.ToString(inv) + (luna && rb.Width > S(70) ? " · " + Lang.T("Luna") : "");
                        Testo(g, tb, luna ? fpb : fp, luna ? Color.FromArgb(29, 36, 51) : Tema.Fore, rb, StringAlignment.Center, StringAlignment.Center);
                        if (luna)
                        {
                            double te = ts + rit;
                            float xe0 = Math.Max(bx, Xs(te)), xe1 = Math.Min(bx + bw, Xs(te + pp));
                            if (xe1 > xe0 + 2)
                            {
                                using (Brush bg = new SolidBrush(Color.FromArgb(22, 163, 74))) g.FillRectangle(bg, xe0, yb + hb + S(8), xe1 - xe0, S(16));
                                Testo(g, string.Format(ci, Lang.T("eco attesa (+{0} s)"), rit.ToString("0.0", ci)), fpb, Color.FromArgb(22, 163, 74),
                                    new RectangleF(xe1 + S(4), yb + hb + S(6), S(200), S(20)), StringAlignment.Near, StringAlignment.Center);
                            }
                        }
                    }
                    for (int k = 0; k <= 5; k++)
                    {
                        double ts = t0 + k * 2;
                        Testo(g, ":" + (ts % 60).ToString("00.0", ci), fp, Tema.Muted, new RectangleF(Xs(ts) - S(30), yb + hb + S(30), S(60), S(18)), k == 0 ? StringAlignment.Near : StringAlignment.Center, StringAlignment.Near);
                    }
                    yd = yb + hb + S(58);
                }
                else
                {
                    Testo(g, Lang.T("La Luna non è nel fascio di GRAVES in questo momento: il dettaglio dei passi compare quando entra in un settore."), fs, Tema.Muted,
                        new RectangleF(bx, yd, bw, S(40)), StringAlignment.Near, StringAlignment.Near);
                    yd += S(50);
                }
                // nota sulla sequenza e pastiglia «orologio del PC sincronizzato»
                string nota = Lang.T("La sequenza è legata all'ora UTC (PE1ITR): dal 2021 i passi durano 0,8 s e il ciclo di un settore 4,8 s; nel 2007 erano 3,2 s e 19,2 s. La stazione di comando a volte sposta la sequenza di qualche passo: il dettaglio è una previsione da confermare con l'ascolto.");
                RectangleF rn = new RectangleF(lx, yd, crr.Width - S(36), Math.Max(S(40), crr.Bottom - yd - S(40)));
                Testo(g, nota, fs, Tema.Fore, rn, StringAlignment.Near, StringAlignment.Near);
                string oro = Lang.T("orologio del PC sincronizzato");
                SizeF so = g.MeasureString(oro, fpb);
                SizeF sn = g.MeasureString(nota, fs, (int)rn.Width);
                RectangleF ro = new RectangleF(lx, Math.Min(crr.Bottom - S(32), yd + sn.Height + S(6)), so.Width + S(16), S(22));
                using (GraphicsPath po = Arrotondato(ro, S(8)))
                using (Brush bo = new SolidBrush(Color.FromArgb(254, 243, 199))) g.FillPath(bo, po);
                Testo(g, oro, fpb, Color.FromArgb(146, 64, 14), ro, StringAlignment.Center, StringAlignment.Center);
                y += hMid + S(16);

                // --- come ascoltare l'eco (sinistra) e fonti (destra)
                float hBot = Math.Max(S(250), cr.Height - y - S(10)), wA = (wTot - gap) / 2f;
                RectangleF ca = new RectangleF(x0, y, wA, hBot), cf = new RectangleF(x0 + wA + gap, y, wA, hBot);
                Scheda(g, ca, Color.Empty); Scheda(g, cf, Color.Empty);
                Testo(g, Spaziato(Lang.T("COME ASCOLTARE L'ECO (NJ9R, PE1ITR)")), ft, titCol, new RectangleF(ca.Left + S(18), ca.Top + S(14), ca.Width - S(30), S(22)), StringAlignment.Near, StringAlignment.Near);
                string[][] passi = {
                    new string[] { Lang.T("Ricevitore"), Lang.T("SSB su 143,050 MHz (o 143,049 5), banda audio ≥ 2,4 kHz, AGC spento, noise blanker attivo, niente filtri, notch o DSP") },
                    new string[] { Lang.T("Antenna"), Lang.T("Sulla Luna vista da te; con antenna fissa bastano 0° – 15° di elevazione al sorgere o al tramonto") },
                    new string[] { Lang.T("Waterfall"), Lang.T("L'eco è una linea tratteggiata a circa 1240 Hz (± Doppler); gli aerei sono righe vicino al segnale diretto") },
                    new string[] { Lang.T("Prova"), Lang.T("Muovi il rotore a piccoli passi fino al massimo e confronta con la posizione calcolata (§ 1.11)") } };
                float c1 = ca.Left + S(18), c2 = c1 + Math.Min(S(110), ca.Width * 0.2f), wcol = ca.Right - S(18) - c2, ya = ca.Top + S(48);
                Testo(g, Lang.T("Passo"), fp, Tema.Muted, new RectangleF(c1, ya, c2 - c1, S(20)), StringAlignment.Near, StringAlignment.Near);
                Testo(g, Lang.T("Che cosa fare"), fp, Tema.Muted, new RectangleF(c2, ya, wcol, S(20)), StringAlignment.Near, StringAlignment.Near);
                ya += S(24);
                using (Pen pl = new Pen(Tema.Linea))
                    foreach (string[] ps in passi)
                    {
                        g.DrawLine(pl, c1, ya, ca.Right - S(18), ya);
                        float hr = Math.Max(S(26), g.MeasureString(ps[1], fs, (int)wcol).Height + S(8));
                        Testo(g, ps[0], fs, Tema.Fore, new RectangleF(c1, ya + S(4), c2 - c1 - S(6), hr), StringAlignment.Near, StringAlignment.Near);
                        Testo(g, ps[1], fs, Tema.Fore, new RectangleF(c2, ya + S(4), wcol, hr), StringAlignment.Near, StringAlignment.Near);
                        ya += hr;
                    }
                Testo(g, Spaziato(Lang.T("Fonti").ToUpper(ci)), ft, titCol, new RectangleF(cf.Left + S(18), cf.Top + S(14), cf.Width - S(30), S(22)), StringAlignment.Near, StringAlignment.Near);
                string[] fonti = {
                    "[1] Rob Hardenberg PE1ITR, “The 143.050MHz Graves Radar a VHF Beacon” (DUBUS 4/2007) " + Lang.T("e") + " “Graves Radar Update April 2021” – pe1itr.com/graves",
                    "[2] Bolidozor wiki, “Graves” – " + Lang.T("schiere, settori e tempi del fascio"),
                    "[3] Wikipedia, “GRAVES (system)” – " + Lang.T("trasmettitore a Broye-lès-Pesmes (47,348° N 5,515° E), ricevitore a Revest-du-Bion, in servizio dal 2005"),
                    "[4] Relu Jianu NJ9R, “2M EME the easy way… the secret sauce to success”, rev. 1.1 (2025)",
                    "[5] Grupo Bandas Altas DX, “Desafío EME GRAVES” – " + Lang.T("ricezione dell'eco con stazioni piccole") };
                float yf = cf.Top + S(48);
                foreach (string fo in fonti)
                {
                    float hf = g.MeasureString(fo, fs, (int)(cf.Width - S(36))).Height + S(6);
                    Testo(g, fo, fs, Tema.Fore, new RectangleF(cf.Left + S(18), yf, cf.Width - S(36), hf), StringAlignment.Near, StringAlignment.Near);
                    yf += hf;
                }
            }
        }

        void BuildSolarTab(TabPage tp)
        {
            sfuStations = StazioniNote();
            sfuCachePath = Path.Combine(Path.GetDirectoryName(settingsPath), "solar-radio-flux.json");
            foreach (int f in Bande) sfuManual[f] = SfuPredefinito(f);

            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 2;
            root.RowCount = 4;
            root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 55f));
            root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 45f));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Absolute, S(112)));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 62f));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 38f));
            root.Padding = new Padding(S(4));

            // Barra: banda e istante (sincronizzati con la linguetta Budget EME)
            FlowLayoutPanel bar = new FlowLayoutPanel();
            bar.AutoSize = true;
            bar.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            bar.Dock = DockStyle.Fill;
            cmbBand3 = new Tendina();
            cmbBand3.DropDownStyle = ComboBoxStyle.DropDownList;
            foreach (int f in bandeAttive) cmbBand3.Items.Add(NomeBanda(f));
            cmbBand3.SelectedIndex = bandeAttive.IndexOf(curBand);
            cmbBand3.Width = S(120);
            cmbBand3.SelectedIndexChanged += (s, e) =>
            {
                if (!syncing && !ricostruzioneBande && cmbBand3.SelectedIndex >= 0) cmbBand.SelectedIndex = cmbBand3.SelectedIndex;
            };
            dtpS = new DateTimePicker();
            dtpS.Format = DateTimePickerFormat.Custom;
            dtpS.CustomFormat = "dd/MM/yyyy  HH:mm";
            dtpS.Width = S(150);
            dtpS.Value = dtpB.Value;
            dtpS.ValueChanged += (s, e) => { if (!syncing) dtpB.Value = dtpS.Value; };
            Pillola bNow = new Pillola(Lang.T("Adesso").ToUpper(Lang.Cultura), StilePillola.Pieno, ColPillola, new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bNow.Margin = new Padding(S(6), S(2), S(3), S(2));
            bNow.Click += (s, e) => { dtpB.Value = NowUtcMinute(); RecalcBudget(); };
            Pillola bRow = new Pillola(Lang.T("Usa la riga della tabella").ToUpper(Lang.Cultura), StilePillola.Pieno, ColPillola, new Font(Lang.FontUi, 9F * fontFactor, FontStyle.Bold));
            bRow.Margin = new Padding(S(3), S(2), S(3), S(2));
            bRow.Click += (s, e) => UsaRigaSelezionata();
            Label nb = L(Lang.T("   Parametri delle stazioni: quelli della linguetta \"Budget EME\"."));
            nb.ForeColor = Tema.Muted;
            bar.Controls.Add(L(Lang.T("Banda"))); bar.Controls.Add(cmbBand3);
            bar.Controls.Add(L(Lang.T("Istante (UTC)"))); bar.Controls.Add(dtpS); bar.Controls.Add(bNow); bar.Controls.Add(bRow);
            bar.Controls.Add(nb);
            root.Controls.Add(bar, 0, 0);
            root.SetColumnSpan(bar, 2);

            // indicatori
            pnlSfuKpi = new PannelloDisegno();
            pnlSfuKpi.Dock = DockStyle.Fill;
            pnlSfuKpi.Paint += DisegnaSfuKpi;
            root.Controls.Add(pnlSfuKpi, 0, 1);
            root.SetColumnSpan(pnlSfuKpi, 2);

            // a sinistra: fonte dei dati e scelte per il calcolo
            TableLayoutPanel sx = new TableLayoutPanel();
            sx.Dock = DockStyle.Fill;
            sx.ColumnCount = 1; sx.RowCount = 2;
            sx.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            sx.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            sx.Margin = new Padding(0);
            TableLayoutPanel gd = new TableLayoutPanel();
            gd.Dock = DockStyle.Fill;
            gd.ColumnCount = 1;
            gd.RowCount = 3;
            gd.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            gd.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            gd.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            FlowLayoutPanel fu = new FlowLayoutPanel();
            fu.AutoSize = true;
            fu.AutoSizeMode = AutoSizeMode.GrowAndShrink;
            fu.Dock = DockStyle.Fill;
            cmbSfuFonte = new Tendina();
            cmbSfuFonte.DropDownStyle = ComboBoxStyle.DropDownList;
            cmbSfuFonte.Items.AddRange(new object[] {
                new VoceFonte(Lang.T("NOAA SWPC · rete RSTN, 245 – 15400 MHz (consigliata)"), "NOAA SWPC · " + Lang.T("rete RSTN, 245 – 15400 MHz"), " " + Lang.T("(consigliata: 4 stazioni, 8 frequenze)")),
                new VoceFonte(Lang.T("NOAA SWPC · F10.7 (2800 MHz), stima grossolana"), "NOAA SWPC · " + Lang.T("solo F10.7"), " " + Lang.T("(2800 MHz, Penticton): il resto dello spettro è stimato")),
                new VoceFonte(Lang.T("Penticton (Canada, DRAO) · F10.7 (2800 MHz), stima grossolana"), Lang.T("Penticton DRAO (Canada)") + " · F10.7", " " + Lang.T("osservato, tre misure al giorno")),
                new VoceFonte(Lang.T("Learmonth (Australia, BoM) · Sole quieto, 8 frequenze"), Lang.T("Learmonth (Australia, BoM)"), " · " + Lang.T("Sole quieto, 8 frequenze")),
                new VoceFonte(Lang.T("Indirizzo personalizzato (formato RSTN)"), Lang.T("Indirizzo personalizzato…"), " " + Lang.T("(file JSON nel formato SWPC)")) });
            cmbSfuFonte.SelectedIndex = 0;
            cmbSfuFonte.Width = S(390);
            cmbSfuFonte.DropDownWidth = S(560);
            cmbSfuFonte.DrawMode = DrawMode.OwnerDrawFixed;
            cmbSfuFonte.ItemHeight = S(22);
            cmbSfuFonte.DrawItem += (s, e) =>
            {
                e.DrawBackground();
                if (e.Index < 0) return;
                VoceFonte v = cmbSfuFonte.Items[e.Index] as VoceFonte;
                bool sel = (e.State & DrawItemState.Selected) != 0;
                Color ct = sel ? SystemColors.HighlightText : cmbSfuFonte.ForeColor;
                TextFormatFlags tf = TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.NoPadding | TextFormatFlags.SingleLine;
                Rectangle r = new Rectangle(e.Bounds.X + S(4), e.Bounds.Y, e.Bounds.Width - S(6), e.Bounds.Height);
                if (v == null || (e.State & DrawItemState.ComboBoxEdit) != 0)
                {
                    TextRenderer.DrawText(e.Graphics, cmbSfuFonte.Items[e.Index].ToString(), cmbSfuFonte.Font, r, ct, tf | TextFormatFlags.EndEllipsis);
                    return;
                }
                using (Font fb = new Font(cmbSfuFonte.Font, FontStyle.Bold))
                {
                    int wb = TextRenderer.MeasureText(e.Graphics, v.Grassetto, fb, r.Size, tf).Width;
                    TextRenderer.DrawText(e.Graphics, v.Grassetto, fb, r, ct, tf);
                    TextRenderer.DrawText(e.Graphics, v.Resto, cmbSfuFonte.Font, new Rectangle(r.X + wb, r.Y, Math.Max(1, r.Width - wb), r.Height), ct, tf | TextFormatFlags.EndEllipsis);
                }
            };
