        void AggiornaTerraDx(DateTime now)
        {
            string k = now.ToString("yyyyMMddHHmm", inv) + DxLoc + ChiaveTerreno + usaTerrenoDx + (chkDx != null && chkDx.Checked) + me.Loc.Text + me.El1.Value + me.El2.Value + me.Az1.Value + me.Az2.Value
                + dx.El1.Value + dx.El2.Value + dx.Az1.Value + dx.Az2.Value + Lang.Idx + "|" + stazPol + polDx + (trk.Striscia != null ? trk.StrisciaT0.Ticks : 0);
            if (k == trkDxTerraChiave) return;
            trkDxTerraChiave = k;
            int tipo = -1; string badge = "", testo = "";
            int st = StatoDx;
            if (usaTerrenoDx && chkDx != null && chkDx.Checked && st >= 0)
            {
                if (st == 3) { tipo = 2; badge = Lang.T("terreno non disponibile"); testo = Lang.T("SRTM1 copre da 56° S a 60° N"); }
                else if (st == 2) { tipo = 2; badge = Lang.T("non calcolato"); testo = Lang.T("serve un locatore di almeno 6 caratteri"); }
                else if (!OrizzonteDxValido) { tipo = 2; badge = Lang.T("da calcolare"); testo = Lang.T("premi CALCOLA L'ORIZZONTE DEL DX in «Il mio orizzonte»"); }
                else
                {
                    tipo = st == 0 ? 0 : 1;
                    badge = st == 0 ? Lang.T("calcolato") : Lang.T("indicativo: locatore a 6 caratteri");
                    string ti = st == 1 ? "~" : "";
                    PassaggioLuna ps = CalcolaPassaggio(now, true);
                    Func<DateTime, string> H = t => ti + t.ToString("HH:mm", inv);
                    if (!ps.Ok) testo = "";
                    else if (ps.TerraSorge == DateTime.MinValue) testo = Lang.T("Luna dietro il terreno del DX per tutto il passaggio");
                    else if (now < ps.AstroSorge) testo = string.Format(Lang.T("sorge per il terreno del DX alle {0} UTC"), H(ps.TerraSorge));
                    else if (now < ps.TerraSorge) testo = string.Format(Lang.T("Luna dietro il terreno del DX fino alle {0} UTC"), H(ps.TerraSorge));
                    else if (now <= ps.TerraTramonta) testo = string.Format(Lang.T("Luna sopra il terreno del DX fino alle {0} UTC"), H(ps.TerraTramonta));
                    else testo = string.Format(Lang.T("Luna dietro il terreno del DX dalle {0} UTC"), H(ps.TerraTramonta));
                    double persa = ps.Ok ? Math.Max(0, ps.MinComuneSenza - ps.MinComune) : 0;
                    if (persa >= 1) testo += " · " + string.Format(Lang.T("finestra comune persa {0}"), ti + Durata(persa, Lang.Cultura));
                }
            }
            // polarizzazione (v1.9.6): adesso, o il prossimo tratto a rischio nella barra delle 24 ore
            int ptipo = -1; string pbadge = "", ptesto = "";
            if (chkDx != null && chkDx.Checked && dx.Ok && me.Ok)
            {
                double f;
                if (!ReadFreq(out f)) f = 144;
                int pd = PolEffDx(polDx, f);
                MoonPos p = Moon.Compute(now, me.Lat, me.Lon, (double)me.H.Value, false), q = Moon.Compute(now, dx.Lat, dx.Lon, (double)dx.H.Value, false);
                double dp = Moon.PolOffset(Moon.PolAngle(me.Lat, p.Az, p.ElGeo), Moon.PolAngle(dx.Lat, q.Az, q.ElGeo));
                int rn = RischioPol(dp, f, stazPol, pd);
                if (rn > 0 && p.El >= 0 && q.El >= 0)
                    ptesto = string.Format(Lang.Cultura, Lang.T("Dpol {0:F0}° adesso: {1}"), dp, ConsiglioPol(f));
                else
                {
                    rn = 0;
                    byte[] sv = trk.Striscia;
                    if (sv != null && trk.StrisciaT0 != DateTime.MinValue)
                    {
                        int i0 = Math.Max(0, (int)((now - trk.StrisciaT0).TotalMinutes / 5));
                        int i = i0;
                        while (i < sv.Length && (sv[i] & 48) == 0) i++;
                        if (i < sv.Length)
                        {
                            int j = i;
                            while (j < sv.Length && (sv[j] & 48) != 0) { if ((sv[j] & 32) != 0) rn = 2; else rn = Math.Max(rn, 1); j++; }
                            ptesto = string.Format(Lang.T("dalle {0} alle {1} UTC: {2}"), trk.StrisciaT0.AddMinutes(5 * i).ToString("HH:mm", inv),
                                trk.StrisciaT0.AddMinutes(5 * j).ToString("HH:mm", inv), ConsiglioPol(f));
                        }
                    }
                }
                if (rn > 0)
                {
                    ptipo = rn == 2 ? 3 : 1;
                    pbadge = rn == 2 ? Lang.T("collegamento a rischio") : Lang.T("un senso può mancare");
                }
            }
            bool cambia = (tipo >= 0) != (trkDxTerraTipo >= 0) || (ptipo >= 0) != (trkPolTipo >= 0);
            trkDxTerraTipo = tipo; trkDxTerraBadge = badge; trkDxTerraTesto = testo;
            trkPolTipo = ptipo; trkPolBadge = pbadge; trkPolTesto = ptesto;
            if (trkRigaSchede != null)
            {
                float h = S(112) + RigheDx * S(24);
                if (Math.Abs(trkRigaSchede.Height - h) > 0.5f) trkRigaSchede.Height = h;
            }
            if (cardDx != null) cardDx.Invalidate();
            if (cambia && cardDx != null && cardDx.Parent != null) cardDx.Parent.PerformLayout();
        }

        void DisegnaTerraDx(Graphics g)
        {
            trkDxTerraRett = RectangleF.Empty;
            RectangleF r = new RectangleF(0, 0, cardDx.ClientSize.Width - S(3), cardDx.ClientSize.Height - S(5));
            // riga della polarizzazione sopra quella del terreno
            if (trkPolTipo >= 0)
            {
                float yp = r.Bottom - S(28) - (trkDxTerraTipo >= 0 ? S(26) : 0), xp = r.Left + S(12);
                using (Font f = FontPx(Lang.FontUi, S(12.5f), false))
                using (Font fb = FontPx(Lang.FontUi, S(11.5f), true))
                {
                    string et = "⇄ " + Lang.T("Polarizzazione:");
                    float we = g.MeasureString(et, f).Width;
                    Testo(g, et, f, Tema.Fore, new RectangleF(xp, yp, we + S(4), S(22)), StringAlignment.Near, StringAlignment.Center);
                    float xe = Badge(g, trkPolBadge, fb, trkPolTipo, xp + we + S(4), yp + S(11));
                    Testo(g, trkPolTesto, f, Tema.Fore, new RectangleF(xe + S(6), yp, Math.Max(S(10), r.Right - S(10) - xe - S(6)), S(22)), StringAlignment.Near, StringAlignment.Center);
                }
            }
            if (trkDxTerraTipo < 0) return;
            float y = r.Bottom - S(28), x = r.Left + S(12);
            using (Font f = FontPx(Lang.FontUi, S(12.5f), false))
            using (Font fb = FontPx(Lang.FontUi, S(11.5f), true))
            {
                string et = "▲ " + Lang.T("Terreno DX:");
                float we = g.MeasureString(et, f).Width;
                Testo(g, et, f, Tema.Fore, new RectangleF(x, y, we + S(4), S(22)), StringAlignment.Near, StringAlignment.Center);
                float xe = Badge(g, trkDxTerraBadge, fb, trkDxTerraTipo, x + we + S(4), y + S(11));
                Testo(g, trkDxTerraTesto, f, Tema.Fore, new RectangleF(xe + S(6), y, Math.Max(S(10), r.Right - S(10) - xe - S(6)), S(22)), StringAlignment.Near, StringAlignment.Center);
            }
            trkDxTerraRett = new RectangleF(r.Left, y - S(2), r.Width, S(26));
        }

