                MostraVistaOriz(); MostraStazOriz();
                if (tabs != null && tpOriz != null) tabs.SelectedTab = tpOriz;
            };
            cardDx.Paint += (s, e) =>
            {
                DisegnaScheda(e.Graphics, cardDx, Lang.T("Stazione DX — nominativo e locator WWL"), null, Color.Empty, subDx, subDxCol, "", txtTrkDx, Tema.Linea, 1f, subDxTag, RigheDx * S(26));
                DisegnaTerraDx(e.Graphics);
                DisegnaCornice(e.Graphics, txtTrkDxCall, dxAttivo ? ColAttivo : Tema.Linea, dxAttivo ? 3f : 1f);
            };
            txtTrkLoc.TextChanged += (s, e) =>
