        int caviTipRiga = -1;
        ComboBox cmbCaviTipo, cmbCaviDiam, cmbCaviBanda, cmbCaviCalcBanda, cmbCaviOrd;
        bool caviClicTesta;
        bool caviInv;   // ordine per nome, costruttore o tipo: false = A → Z, true = Z → A
        Label lblNotaCavi;
        NumericUpDown nudCaviLen;
        PannelloDisegno pnlCaviGrafico, pnlCaviCalc;
        readonly List<Cavo> caviMostrati = new List<Cavo>();
        readonly HashSet<Cavo> caviSpuntati = new HashSet<Cavo>();
        readonly List<RectangleF> caviRighe = new List<RectangleF>();
        readonly List<Pillola> caviFiltri = new List<Pillola>();
        static readonly Color[] ColCavi = { Color.FromArgb(31, 111, 209), Color.FromArgb(204, 51, 68), Color.FromArgb(23, 128, 61), Color.FromArgb(217, 119, 6), Color.FromArgb(91, 63, 168), Color.FromArgb(15, 139, 141) };

        [DllImport("user32.dll", EntryPoint = "SendMessageW", CharSet = CharSet.Unicode)]
        static extern IntPtr SendMessageTesto(IntPtr hWnd, int msg, IntPtr wParam, string lParam);

        static string TipoCavo(string t)
        {
            switch (t)
            {
                case "flessibile": return Lang.T("flessibile");
                case "superflessibile": return Lang.T("superflessibile");
                case "semirigido": return Lang.T("semirigido");
                default: return Lang.T("personalizzato");
            }
        }

        // colore della curva (e della casella) di un cavo spuntato: nell'ordine della tabella
        Color ColoreCavo(Cavo c)
        {
            int k = 0;
            foreach (Cavo x in caviMostrati)
            {
                if (!caviSpuntati.Contains(x)) continue;
                if (x == c) return ColCavi[k % ColCavi.Length];
                k++;
            }
            return ColCavi[0];
        }

        void BuildCaviTab(TabPage tp)
        {
            TableLayoutPanel root = new TableLayoutPanel();
            root.Dock = DockStyle.Fill;
            root.ColumnCount = 2; root.RowCount = 2;
            root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 66f));
            root.ColumnStyles.Add(new ColumnStyle(SizeType.Percent, 34f));
            root.RowStyles.Add(new RowStyle(SizeType.AutoSize));
            root.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            root.Padding = new Padding(S(4));

            // barra: ricerca con la lente dentro, filtri a pastiglia, diametro; a destra banda evidenziata e "+ Aggiungi"
            TableLayoutPanel barT = new TableLayoutPanel();
            barT.AutoSize = true; barT.AutoSizeMode = AutoSizeMode.GrowAndShrink; barT.Dock = DockStyle.Fill;
            barT.ColumnCount = 2; barT.RowCount = 1;
