            {
                if (Piattaforma.Windows) { try { SendMessageTesto(txtCercaCavi.Handle, 0x1501, (IntPtr)1, Lang.T("Cerca: nome, sigla, costruttore…")); } catch { } }   // EM_SETCUEBANNER
            };
            PannelloDisegno cerca = new PannelloDisegno();
