            cerca.Margin = new Padding(S(2), S(3), S(10), S(3));
            cerca.Controls.Add(txtCercaCavi);
            txtCercaCavi.Location = new Point(S(30), (cerca.Height - txtCercaCavi.Height) / 2);
            cerca.Paint += (s, e) =>
            {
                Graphics g = e.Graphics;
                PreparaGrafica(g);
                g.Clear(Tema.Back);
