                float cx = S(14), cy = cerca.Height / 2f - S(1), rr = S(5);
                using (Pen pl = new Pen(Tema.Muted, S(1.6f)))
                {
                    g.DrawEllipse(pl, cx - rr, cy - rr, 2 * rr, 2 * rr);
                    g.DrawLine(pl, cx + rr * 0.7f, cy + rr * 0.7f, cx + rr * 1.7f, cy + rr * 1.7f);
                }
