            cmbCaviOrd.SelectedIndexChanged += (s, e) => { if (!caviClicTesta) caviInv = false; RiempiCavi(); };
            Label lo = L(Lang.T("Ordina per")); lo.Margin = new Padding(S(3), S(9), S(3), S(3));
