            barDx.Controls.Add(lo); barDx.Controls.Add(cmbCaviOrd);
            barDx.Controls.Add(lb); barDx.Controls.Add(cmbCaviBanda); barDx.Controls.Add(bAgg);
            barT.Controls.Add(bar, 0, 0); barT.Controls.Add(barDx, 1, 0);
            root.Controls.Add(barT, 0, 0); root.SetColumnSpan(barT, 2);

            // tabella disegnata: intestazione fissa e righe di altezza variabile (nomi equivalenti a capo)
            TableLayoutPanel tab = new TableLayoutPanel();
            tab.ColumnCount = 1; tab.RowCount = 2;
            tab.RowStyles.Add(new RowStyle(SizeType.Absolute, S(28)));
            tab.RowStyles.Add(new RowStyle(SizeType.Percent, 100f));
            tab.Margin = new Padding(0);
            pnlCaviTesta = new PannelloDisegno(); pnlCaviTesta.Dock = DockStyle.Fill; pnlCaviTesta.Margin = new Padding(0);
            pnlCaviTesta.Paint += DisegnaTestaCavi;
            // clic sull'intestazione di una banda: ordina per perdita in quella banda (crescente, poi decrescente); su Ø: per diametro
            pnlCaviTesta.Cursor = Cursors.Hand;
            pnlCaviTesta.MouseClick += (s, e) =>
            {
                if (e.Button != MouseButtons.Left) return;
                float[] cxh = ColonneCavi(pnlCavi != null ? pnlCavi.Width : pnlCaviTesta.Width);
                for (int i = 0; i < 4 + CaviDb.Fb.Length; i++)
                {
                    if (e.X < cxh[i] || e.X >= cxh[i + 1]) continue;
                    if (i == 3) { cmbCaviOrd.SelectedIndex = 0; return; }
                    if (i < 3)
                    {
                        // cavo, costruttore, tipo: un clic dalla A alla Z, il secondo dalla Z alla A
                        int oi = 3 + i;
                        caviClicTesta = true;
                        if (cmbCaviOrd.SelectedIndex == oi) { caviInv = !caviInv; RiempiCavi(); }
                        else { caviInv = false; cmbCaviOrd.SelectedIndex = oi; }
                        caviClicTesta = false;
                        return;
                    }
                    int bi = i - 4;
                    if (cmbCaviBanda.SelectedIndex == bi && cmbCaviOrd.SelectedIndex == 1) cmbCaviOrd.SelectedIndex = 2;
                    else
                    {
                        cmbCaviOrd.SelectedIndex = 1;
                        cmbCaviBanda.SelectedIndex = bi;
                    }
                    return;   // le due tendine aggiornano la tabella da sole
                }
            };
            pnlCaviHost = new Panel(); pnlCaviHost.Dock = DockStyle.Fill; pnlCaviHost.AutoScroll = true; pnlCaviHost.Margin = new Padding(0);
            pnlCaviHost.Tag = "su-carta";
