                lines.Add("budget_schema=" + budgetSchemaLarg.ToString(inv));
                if (cmbGrSeq != null) lines.Add("graves_seq=" + cmbGrSeq.SelectedIndex.ToString(inv));
                if (chkGrSuono != null) lines.Add("graves_suono=" + (chkGrSuono.Checked ? "1" : "0"));
                lines.Add("dgf_rx=" + dgfRx.ToString(inv));
                lines.Add("trk_fumetto=" + (trkFumettoVisto ? "1" : "0"));
                lines.Add("dgf_cielo=" + dgfCielo.ToString(inv));
                if (nudDgfGiorni != null) lines.Add("dgf_giorni=" + nudDgfGiorni.Value.ToString(inv));
                List<string> cs_ = new List<string>();
                for (int i = ColFisse; i < colScelte.Length; i++) if (colScelte[i]) cs_.Add(i.ToString(inv));
                lines.Add("colonne=" + (cs_.Count == 0 ? "-" : string.Join(",", cs_.ToArray())));
                lines.Add("grigio_tono=" + grigioTono.ToString(inv));
                lines.Add("mappa=" + cmbMappa.SelectedIndex.ToString(inv));
                lines.Add("map_eme=" + (chkSoloEme.Checked ? "1" : "0"));
                if (mapInit)
                {
                    lines.Add("map_zoom=" + mapZoom.ToString(inv));
                    lines.Add("map_lat=" + YToLat(mapCy, mapZoom).ToString("R", inv));
                    lines.Add("map_lon=" + XToLon(mapCx, mapZoom).ToString("R", inv));
                }
                lines.Add("rifrazione=" + (chkRefr.Checked ? "1" : "0"));
                lines.Add("solopuntabili=" + (chkOnly.Checked ? "1" : "0"));
                SalvaBanda(curBand);
                lines.Add("banda=" + curBand.ToString(inv));
                lines.Add("polbudget=" + (chkPol.Checked ? "1" : "0"));
                lines.Add("bw=" + cmbBw.Text);
                if (cmbTau != null) lines.Add("tau=" + LeggiTau().ToString("R", inv));
                if (cmbRos != null) lines.Add("ros=" + LeggiRos().ToString("R", inv));
                if (chkEco != null) lines.Add("b_eco=" + (chkEco.Checked ? "1" : "0"));
                lines.Add("tema=" + Tema.Chiave);
                lines.Add("aggiorna_salta=" + aggSalta);
                lines.Add("aggiorna_ultimo=" + aggUltimo.ToString(CultureInfo.InvariantCulture));
                lines.Add("lingua=" + Lang.Codici[cmbLingua.SelectedIndex]);
                lines.Add("font_nome=" + (cmbFontNome != null && cmbFontNome.SelectedItem is VoceFont && ((VoceFont)cmbFontNome.SelectedItem).Tipo == 2 ? ((VoceFont)cmbFontNome.SelectedItem).Nome : ""));
                lines.Add("nominativo=" + txtCall.Text.Trim());
                lines.Add("lotw_utente=" + lotwUtente);
                lines.Add("lotw_password=" + lotwPassword);
                lines.Add("complessi=" + (chkComplessi.Checked ? "1" : "0"));
                lines.Add("dati_principale=" + (chkDatiMain.Checked ? "1" : "0"));
                List<string> lb = new List<string>();
                foreach (int f in bandeAttive) lb.Add(f.ToString(inv));
                lines.Add("bande=" + string.Join(",", lb.ToArray()));
                List<string> ln = new List<string>();
                foreach (int f in Bande) ln.Add(f.ToString(inv));
                lines.Add("bande_note=" + string.Join(",", ln.ToArray()));   // bande che esistevano quando l'elenco è stato salvato
                lines.Add("dgrd_giorni=" + nudDgGiorni.Value.ToString(inv));
                lines.Add("font_tabelle=" + fontTabelle.ToString("0.#", inv));
                lines.Add("font_moduli=" + ((float)nudFontMod.Value).ToString("0.#", inv));
                lines.Add("sfu_url=" + txtSfuUrl.Text.Trim());
                lines.Add("sfu_auto=" + (chkSfuAuto.Checked ? "1" : "0"));
                lines.Add("sfu_fonte5=" + FonteSfu.ToString(inv));
                lines.Add("sfu_staz_me=" + cmbSfuMe.SelectedIndex.ToString(inv));
                lines.Add("sfu_staz_dx=" + cmbSfuDx.SelectedIndex.ToString(inv));
                lines.Add("sfu_lobi_me=" + nudSlMe.Value.ToString(inv));
                lines.Add("sfu_lobi_dx=" + nudSlDx.Value.ToString(inv));
                lines.Add("sfu_manuale=" + (chkSfuMan.Checked ? "1" : "0"));
                foreach (int f in Bande) lines.Add("sfu_man_" + f.ToString(inv) + "=" + sfuManual[f].ToString("R", inv));
                foreach (int f in Bande)
                    foreach (string k in BudgetParams.Keys)
                    {
                        lines.Add("b" + f.ToString(inv) + "_me_" + k + "=" + bpMe[f].Get(k).ToString("R", inv));
                        lines.Add("b" + f.ToString(inv) + "_dx_" + k + "=" + bpDx[f].Get(k).ToString("R", inv));
                        if (bpMeAlt.ContainsKey(f)) lines.Add("b" + f.ToString(inv) + "_mea_" + k + "=" + bpMeAlt[f].Get(k).ToString("R", inv));
                        if (bpDxAlt.ContainsKey(f)) lines.Add("b" + f.ToString(inv) + "_dxa_" + k + "=" + bpDxAlt[f].Get(k).ToString("R", inv));
                    }
                File.WriteAllLines(settingsPath, lines.ToArray(), Encoding.UTF8);
            }
            catch { }
        }

        void SetNud(NumericUpDown n, string v)
        {
            decimal d;
            if (decimal.TryParse(v, NumberStyles.Number, inv, out d))
            {
                if (d < n.Minimum) d = n.Minimum;
                if (d > n.Maximum) d = n.Maximum;
                n.Value = d;
            }
        }

        static void SetCombo(ComboBox c, string v)
        {
            int i;
            if (int.TryParse(v, NumberStyles.Integer, CultureInfo.InvariantCulture, out i) && i >= 0 && i < c.Items.Count)
                c.SelectedIndex = i;
        }

        int caviBaseFile = -1;   // cavi del programma nella versione che ha scritto le impostazioni (fino alla v30: 34)

        void LoadBudgetKey(string key, string v)
        {
            // formato: b144_me_p
            string[] parts = key.Split('_');
            if (parts.Length != 3 || parts[0].Length < 2 || parts[0][0] != 'b') return;
            int f;
            if (!int.TryParse(parts[0].Substring(1), NumberStyles.Integer, inv, out f)) return;
            if (Array.IndexOf(Bande, f) < 0 || Array.IndexOf(BudgetParams.Keys, parts[2]) < 0) return;
            double d;
            if (!double.TryParse(v, NumberStyles.Float, inv, out d)) return;
            // cavi personalizzati: l'indice salvato si sposta del numero di cavi aggiunti al database dalla versione che l'ha salvato
            if (parts[2] == "cavoant" || parts[2] == "cavopa" || parts[2] == "cavodis")
            {
                if (caviBaseFile < 0)
                {
                    int nb;
                    caviBaseFile = int.TryParse(LeggiImpostazione("cavi_base"), NumberStyles.Integer, inv, out nb) && nb > 0 ? nb : 34;
                }
                if (d >= caviBaseFile) d += CaviDb.NumBase - caviBaseFile;
            }
            if (parts[1] == "me") bpMe[f].Put(parts[2], d);
            else if (parts[1] == "dx") bpDx[f].Put(parts[2], d);
            else if (parts[1] == "mea" || parts[1] == "dxa")
            {
                Dictionary<int, BudgetParams> da = parts[1] == "mea" ? bpMeAlt : bpDxAlt;
                if (!da.ContainsKey(f)) da[f] = BudgetParams.Default(f);
                da[f].Put(parts[2], d);
            }
        }

        void LoadSettings()
        {
            int banda = curBand;
            List<int> bandeCaricate = null, bandeNote = null;
            string adifDaCaricare = "";
            int mzL = 0;
            double mlatL = double.NaN, mlonL = double.NaN;
            try
            {
                if (!File.Exists(settingsPath)) return;
                foreach (string line in File.ReadAllLines(settingsPath))
                {
                    int k = line.IndexOf('=');
                    if (k <= 0) continue;
                    string key = line.Substring(0, k).Trim();
                    string v = line.Substring(k + 1).Trim();
                    switch (key)
                    {
                        case "locator": me.Loc.Text = v; break;
                        case "quota": SetNud(me.H, v); break;
                        case "az1": SetNud(me.Az1, v); break;
                        case "az2": SetNud(me.Az2, v); break;
                        case "el1": SetNud(me.El1, v); break;
                        case "el2": SetNud(me.El2, v); break;
                        case "dx": chkDx.Checked = v == "1"; break;
                        case "dx_locator": dx.Loc.Text = v; break;
                        case "dx_nominativo": if (txtDxCall != null) { txtDxCall.Text = v; dxCallPrec = v.Trim(); } break;
                        case "dx_quota": SetNud(dx.H, v); break;
                        case "dx_az1": SetNud(dx.Az1, v); break;
                        case "dx_az2": SetNud(dx.Az2, v); break;
                        case "dx_el1": SetNud(dx.El1, v); break;
                        case "dx_el2": SetNud(dx.El2, v); break;
                        case "durata_giorni": SetNud(nudDur, v); break;
                        case "passo": SetNud(nudStep, v); break;
                        case "freq": if (v.Length > 0) cmbFreq.Text = v; break;
                        case "khz": cmbKhz.Text = v; break;
                        case "adif": adifDaCaricare = v; break;
                        case "dg_col_dgrd":
                        case "dg_col_dist":
                            {
                                int argb;
                                Color cc = int.TryParse(v, NumberStyles.Integer, inv, out argb) ? Color.FromArgb(argb) : Color.Empty;
                                if (key == "dg_col_dgrd") dgColDg = cc; else dgColKm = cc;
                                AggiornaStileDg();
                                break;
                            }
                        case "dg_sp_dgrd":
                        case "dg_sp_dist":
                            {
                                decimal sp;
                                if (decimal.TryParse(v, NumberStyles.Float, inv, out sp) && sp >= 1 && sp <= 8)
                                {
                                    if (key == "dg_sp_dgrd") nudSpDg.Value = sp; else nudSpKm.Value = sp;
                                }
                                break;
                            }
                        case "punt_sfuma": chkPuntSfuma.Checked = v != "0"; break;
                        case "dg_decl": if (chkDgDec != null) chkDgDec.Checked = v != "0"; break;
                        case "dg_verde": if (chkDgVerde != null) chkDgVerde.Checked = v == "1"; break;
                        case "colonne":
                            {
                                colScelte = new bool[26];
                                foreach (string x in v.Split(','))
                                {
                                    int ix;
                                    if (int.TryParse(x.Trim(), NumberStyles.Integer, inv, out ix) && ix >= ColFisse && ix < colScelte.Length) colScelte[ix] = true;
                                }
                                TestoPulsanteColonne();
                                break;
                            }
                        case "grigio_opacita": { int gv; if (int.TryParse(v, NumberStyles.Integer, inv, out gv)) ImpostaGrigi(gv, grigioTono); break; }
                        case "graves_seq": if (cmbGrSeq != null && (v == "0" || v == "1")) cmbGrSeq.SelectedIndex = v == "1" ? 1 : 0; break;
                        case "graves_suono": if (chkGrSuono != null) chkGrSuono.Checked = v == "1"; break;
                        case "dgf_rx": dgfRx = v == "0" ? 0 : 1; DgfMostraScelte(); break;
                        case "trk_fumetto": trkFumettoVisto = v == "1"; break;
                        case "dgf_cielo": dgfCielo = v == "0" ? 0 : 1; DgfMostraScelte(); break;
                        case "dgf_giorni": { int gg; if (nudDgfGiorni != null && int.TryParse(v, NumberStyles.Integer, inv, out gg)) nudDgfGiorni.Value = Math.Max(7, Math.Min(61, gg)); break; }
                        case "budget_schema": { int bw2; if (int.TryParse(v, NumberStyles.Integer, inv, out bw2)) { budgetSchemaLarg = Math.Max(300, Math.Min(1500, bw2)); if (budgetRoot != null) budgetRoot.ColumnStyles[2].Width = S(budgetSchemaLarg); } break; }
                        case "grigio_velo": grigioVelo = v != "0"; if (chkVelo != null) chkVelo.Checked = grigioVelo; break;
                        case "grigio_tono": { int gv; if (int.TryParse(v, NumberStyles.Integer, inv, out gv)) ImpostaGrigi(grigioOpacita, gv); break; }
                        case "punt_mappa":
                            {
                                int pm;
                                if (int.TryParse(v, NumberStyles.Integer, inv, out pm) && pm >= 0 && pm < cmbPuntMappa.Items.Count) cmbPuntMappa.SelectedIndex = pm;
                                break;
                            }
                        case "punt_zoom":
                            {
                                int pz;
                                if (int.TryParse(v, NumberStyles.Integer, inv, out pz)) { puntZoom = Math.Max(3, Math.Min(19, pz)); AggiornaZoomPunt(); }
                                break;
                            }
                        case "terreno": usaTerreno = v != "0"; break;
                        case "terreno_dx": usaTerrenoDx = v == "1"; break;
                        case "terreno_dx_antenna": { decimal x; if (decimal.TryParse(v, NumberStyles.Float, inv, out x)) antDxSuolo = Math.Max(0, Math.Min(300, x)); break; }
                        case "terreno_dx_raggio": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) orizDxRaggioIdx = Math.Max(0, Math.Min(OrizDxRaggi.Length - 1, x)); break; }
                        case "orizzonte_stazione": orizStaz = v == "1" ? 1 : 0; break;
                        case "prova_modo": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) stazModoVoce = Math.Max(0, Math.Min(BudgetParams.ModiOrdine.Length - 1, x)); break; }
                        case "prova_temperature": stazTemp = v != "0"; break;
                        case "aggiorna_salta": aggSalta = v; break;
                        case "skynoise_indice_0": case "skynoise_indice_1": case "skynoise_indice_2": case "skynoise_indice_3":
                        case "skynoise_c_0": case "skynoise_c_1": case "skynoise_c_2": case "skynoise_c_3":
                            {
                                double x;
                                int ib = key[key.Length - 1] - '0';
                                if (double.TryParse(v, NumberStyles.Float, inv, out x)) { if (key.StartsWith("skynoise_indice_")) cieloBeta[ib] = x; else cieloC[ib] = x; }
                                break;
                            }
                        case "aggiorna_ultimo": long.TryParse(v, NumberStyles.Integer, CultureInfo.InvariantCulture, out aggUltimo); break;
                        case "prova_no_paese": stazNoPaese = v == "1"; if (chkStazPaese != null) chkStazPaese.Checked = stazNoPaese; break;
                        case "prova_pol": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) stazPol = Math.Max(0, Math.Min(3, x)); break; }
                        case "pol_dx": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) polDx = Math.Max(-1, Math.Min(3, x)); break; }
                        case "orizzonte_vista": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) orizVista = Math.Max(0, Math.Min(1, x)); break; }
                        case "orizzonte_raggio": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) orizRaggioIdx = Math.Max(0, Math.Min(OrizRaggi.Length - 1, x)); break; }
                        case "orizzonte_passo": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) orizPassoIdx = Math.Max(0, Math.Min(OrizPassi.Length - 1, x)); break; }
                        case "orizzonte_k": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) orizKIdx = Math.Max(0, Math.Min(OrizK.Length - 1, x)); break; }
                        case "orizzonte_sfondo": orizSfondo = v != "0"; break;
                        case "orizzonte_colori": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) orizPal = Math.Max(0, Math.Min(2, x)); break; }
                        case "skynoise_diagramma": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) cieloDiag = Math.Max(0, Math.Min(2, x)); break; }
                        case "skynoise_mappa": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) cieloMappa = Math.Max(0, Math.Min(3, x)); break; }
                        case "skynoise_banda": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) cieloBanda = Math.Max(0, Math.Min(3, x)); break; }
                        case "skynoise_sotto": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) cieloSotto = Math.Max(0, Math.Min(1, x)); break; }
                        case "skynoise_nec": cieloNec = v; break;
                        case "skynoise_yanec": cieloYanec = v; break;
                        case "rumore_segnala": rumSegnala = v != "0"; break;
                        case "rumore_soglia": { int x; if (int.TryParse(v, NumberStyles.Integer, inv, out x)) rumSoglia = Math.Max(1, Math.Min(10, x)); break; }
                        case "cielo_colori":
                            {
                                int pc;
                                if (int.TryParse(v, NumberStyles.Integer, inv, out pc) && pc >= 0 && pc < cmbSkyColori.Items.Count) cmbSkyColori.SelectedIndex = pc;
                                break;
                            }
                        case "mappa": SetCombo(cmbMappa, v); break;
                        case "map_eme": chkSoloEme.Checked = v == "1"; break;
                        case "map_zoom": int.TryParse(v, NumberStyles.Integer, inv, out mzL); break;
                        case "map_lat": double.TryParse(v, NumberStyles.Float, inv, out mlatL); break;
                        case "map_lon": double.TryParse(v, NumberStyles.Float, inv, out mlonL); break;
                        case "rifrazione": chkRefr.Checked = v == "1"; break;
                        case "solopuntabili": chkOnly.Checked = v == "1"; break;
                        case "polbudget": chkPol.Checked = v == "1"; break;
                        case "nominativo": txtCall.Text = v; break;
                        case "lotw_utente": lotwUtente = v; break;
                        case "lotw_password": lotwPassword = v; break;
                        case "complessi": chkComplessi.Checked = v == "1"; break;
                        case "dati_principale": chkDatiMain.Checked = v == "1"; break;
                        case "bande_note":
                            {
                                bandeNote = new List<int>();
                                foreach (string x in v.Split(','))
                                {
                                    int bx;
                                    if (int.TryParse(x.Trim(), NumberStyles.Integer, inv, out bx)) bandeNote.Add(bx);
                                }
                            }
                            break;
                        case "bande":
                            {
                                bandeCaricate = new List<int>();
                                foreach (string x in v.Split(','))
                                {
                                    int bx;
                                    if (int.TryParse(x.Trim(), NumberStyles.Integer, inv, out bx) && Array.IndexOf(Bande, bx) >= 0) bandeCaricate.Add(bx);
                                }
                                break;
                            }
                        case "dgrd_giorni": SetNud(nudDgGiorni, v); break;
                        case "bw": if (cmbBw.Items.Contains(v)) cmbBw.SelectedItem = v; break;
                        case "ros": { double rv; if (cmbRos != null && double.TryParse(v, NumberStyles.Float, inv, out rv) && Array.IndexOf(RosValori, rv) >= 0) cmbRos.SelectedIndex = Array.IndexOf(RosValori, rv); break; }
                        case "tau": { double tv; if (cmbTau != null && double.TryParse(v, NumberStyles.Float, inv, out tv) && Array.IndexOf(TauValori, tv) >= 0) cmbTau.SelectedIndex = Array.IndexOf(TauValori, tv); break; }
                        case "b_eco": if (chkEco != null) chkEco.Checked = v == "1"; break;
                        case "sfu_url": if (v.Length > 0) txtSfuUrl.Text = v; break;
                        case "sfu_auto": chkSfuAuto.Checked = v == "1"; break;
                        case "sfu_fonte": { int fv; if (int.TryParse(v, NumberStyles.Integer, inv, out fv) && fv >= 0 && fv <= 3) cmbSfuFonte.SelectedIndex = fv == 3 ? SfuPersonale : fv; break; }
                        case "sfu_fonte5": { int fv; if (int.TryParse(v, NumberStyles.Integer, inv, out fv) && fv >= 0 && fv < cmbSfuFonte.Items.Count) cmbSfuFonte.SelectedIndex = fv; break; }
                        case "sfu_staz_me": SetCombo(cmbSfuMe, v); break;
                        case "sfu_staz_dx": SetCombo(cmbSfuDx, v); break;
                        case "sfu_lobi_me": SetNud(nudSlMe, v); break;
                        case "sfu_lobi_dx": SetNud(nudSlDx, v); break;
                        case "sfu_manuale": chkSfuMan.Checked = v == "1"; break;
                        case "sfu_man_50":
                        case "sfu_man_144":
                        case "sfu_man_432":
                            {
                                double dv;
                                if (double.TryParse(v, NumberStyles.Float, inv, out dv) && dv > 0)
                                    sfuManual[int.Parse(key.Substring(8), inv)] = dv;
                                break;
                            }
                        case "banda":
                            {
                                int bb;
                                if (int.TryParse(v, NumberStyles.Integer, inv, out bb) && Array.IndexOf(Bande, bb) >= 0) banda = bb;
                                break;
                            }
                        default:
                            if (key.StartsWith("sfu_man_"))
                            {
                                double dv;
                                int fb;
                                if (int.TryParse(key.Substring(8), NumberStyles.Integer, inv, out fb) && Array.IndexOf(Bande, fb) >= 0
                                    && double.TryParse(v, NumberStyles.Float, inv, out dv) && dv > 0)
                                    sfuManual[fb] = dv;
                            }
                            else LoadBudgetKey(key, v);
                            break;
                    }
                }
            }
            catch { }
            if (mzL > 0 && !double.IsNaN(mlatL) && !double.IsNaN(mlonL)) CentraMappa(mlatL, mlonL, mzL);
            if (adifDaCaricare.Length > 0 && File.Exists(adifDaCaricare)) CaricaAdif(adifDaCaricare, false);
            // Applica la banda salvata senza sovrascrivere i parametri appena letti
            // le bande nuove (che non esistevano quando l'elenco è stato salvato) entrano subito nelle tendine
            if (bandeCaricate != null && bandeCaricate.Count > 0)
                foreach (int f in Bande)
                    if (!bandeCaricate.Contains(f) && (bandeNote == null || !bandeNote.Contains(f))) bandeCaricate.Add(f);
            if (bandeCaricate != null && bandeCaricate.Count > 0) ApplicaBande(bandeCaricate, false);
            if (!bandeAttive.Contains(banda)) banda = bandeAttive[0];
            curBand = banda;
            ricostruzioneBande = true;
            cmbBand.SelectedIndex = bandeAttive.IndexOf(banda);
            ricostruzioneBande = false;
            CaricaBanda(banda);
        }
    }

    // Pannello disegnato a mano, senza sfarfallio e con lo sfondo trasparente
    // Casella numerica con l'unità scritta dentro (es. "3 m", "17,0 dBi"), come nei bozzetti; frecce nascoste a richiesta
    class NudUnita : NumericUpDown
    {
        string unita = "", formato;
        bool senzaFrecce;

        public string Unita { get { return unita; } set { unita = value ?? ""; UpdateEditText(); } }
        // formato del numero (es. "0.#" per togliere gli zeri inutili); null = cifre decimali fisse
        public string Formato { get { return formato; } set { formato = value; UpdateEditText(); } }
        // frecce nascoste una volta sola (restano la rotellina e i tasti freccia); la larghezza del testo la decide
        // UpDownBase: cambiarla in OnLayout faceva ripartire l'impaginazione all'infinito (v28c)
        public bool SenzaFrecce
        {
            get { return senzaFrecce; }
            set
            {
                senzaFrecce = value;
                foreach (Control c in this.Controls) if (!(c is TextBox) && !(c is FrecceNud)) c.Visible = !value;   // frecce di sistema
                if (value && frecce == null)
                {
                    // nuovo stile: frecce ^ v affiancate a destra; la casella si allarga dello spazio in più che occupano
                    frecce = new FrecceNud(this);
                    this.Controls.Add(frecce);
                    frecce.BringToFront();
                    int extra = LargFrecce - Math.Max(16, SystemInformation.VerticalScrollBarWidth);
                    if (extra > 0) this.Width += extra;
                    Disponi();
                }
                this.Invalidate();
            }
        }

        FrecceNud frecce;
        // zona delle frecce affiancate (coordinate della casella), per i separatori disegnati dalla cornice
        public Rectangle ZonaFrecce { get { return frecce != null && frecce.Visible ? frecce.Bounds : Rectangle.Empty; } }
        int LargFrecce { get { return 2 * Math.Max(16, (int)Math.Round(this.Font.Height * 1.25)); } }

        [DllImport("user32.dll", EntryPoint = "SendMessage")]
        static extern IntPtr SendMessageNud(IntPtr hWnd, int msg, IntPtr wParam, IntPtr lParam);

        // la zona delle frecce copre la destra della casella: Windows sposta il testo con il margine destro,
        // Mono (Linux e macOS) accorcia la casella del testo
        bool inLayout;
        void Disponi()
        {
            if (frecce == null || inLayout) return;
            int wz = LargFrecce;
            Rectangle z = new Rectangle(Math.Max(0, this.ClientSize.Width - wz), 0, Math.Min(wz, this.ClientSize.Width), this.ClientSize.Height);
            if (frecce.Bounds != z) frecce.Bounds = z;
            if (this.Controls.Count < 2) return;
            Control ed = null;
            foreach (Control c in this.Controls) if (c is TextBox) ed = c;
            if (ed == null) return;
            inLayout = true;
            try
            {
                if (Piattaforma.Windows)
                {
                    if (ed.IsHandleCreated)
                    {
                        int m = Math.Max(0, ed.Right - z.Left + 2);
                        SendMessageNud(ed.Handle, 0xD3, (IntPtr)2, (IntPtr)(m << 16));   // EM_SETMARGINS, EC_RIGHTMARGIN
                    }
                }
                else
                {
                    int wv = Math.Max(10, z.Left - ed.Left - 1);
                    if (ed.Width > wv) ed.Width = wv;
                }
            }
            catch { }
            finally { inLayout = false; }
        }
        protected override void OnLayout(LayoutEventArgs e) { base.OnLayout(e); Disponi(); }
        protected override void OnSizeChanged(EventArgs e) { base.OnSizeChanged(e); Disponi(); }
        protected override void OnFontChanged(EventArgs e) { base.OnFontChanged(e); Disponi(); }
        protected override void OnHandleCreated(EventArgs e) { base.OnHandleCreated(e); Disponi(); }
        protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); if (frecce != null) frecce.Invalidate(); }
        protected override void OnBackColorChanged(EventArgs e) { base.OnBackColorChanged(e); if (frecce != null) frecce.Invalidate(); }
        public void Su() { UpButton(); }
        public void Giu() { DownButton(); }

        // UpDownBase è "Opaque": senza le frecce lo spazio dove stavano non viene ridipinto e restano pezzi di
        // scritte di altri controlli (si vede con caratteri grandi, es. Calibri al 125 %). Lo riempiamo con il fondo.
        protected override void OnPaint(PaintEventArgs e)
        {
            using (SolidBrush b = new SolidBrush(this.BackColor))   // lo stesso fondo della casella interna, anche da spenta e con i temi scuri
                e.Graphics.FillRectangle(b, this.ClientRectangle);
            base.OnPaint(e);
        }

        protected override void UpdateEditText()
        {
            string n = formato != null ? this.Value.ToString(formato, CultureInfo.CurrentCulture)
                : this.Value.ToString("F" + this.DecimalPlaces.ToString(CultureInfo.InvariantCulture), CultureInfo.CurrentCulture);
            if (n.StartsWith("-")) n = "−" + n.Substring(1);
            string nt = unita.Length > 0 ? n + " " + unita : n;
            if (this.Text == nt) return;
            this.ChangingText = true;
            this.Text = nt;
        }

        protected override void ValidateEditText()
        {
            string t = (this.Text ?? "").Replace('−', '-');
            StringBuilder sb = new StringBuilder();
            foreach (char c in t)
                if (char.IsDigit(c) || c == '-' || c == '+' || c == ',' || c == '.') sb.Append(c);
                else if (sb.Length > 0 && !char.IsWhiteSpace(c)) break;
            if (this.Text != sb.ToString())
            {
                this.ChangingText = true;
                this.Text = sb.ToString();
            }
            base.ValidateEditText();
        }
    }

    // Frecce delle caselle dei numeri nel nuovo stile: due celle affiancate, ^ (aumenta) e v (diminuisce),
    // separate da linee sottili; tenendo premuto il valore continua a cambiare
    class FrecceNud : Control
    {
        readonly NudUnita nud;
        int sopra = -1, premuta = -1;
        readonly System.Windows.Forms.Timer ripeti = new System.Windows.Forms.Timer();
        public FrecceNud(NudUnita n)
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            nud = n;
            this.Cursor = Cursors.Hand;
            this.TabStop = false;
            ripeti.Tick += (s, e) => { ripeti.Interval = 60; Passo(); };
        }
        int Cella(Point p) { if (!this.ClientRectangle.Contains(p)) return -1; return p.X < this.Width / 2 ? 0 : 1; }
        void Passo() { if (premuta == 0) nud.Su(); else if (premuta == 1) nud.Giu(); }
        protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); int k = Cella(e.Location); if (k != sopra) { sopra = k; Invalidate(); } }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); sopra = -1; Invalidate(); }
        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left || !nud.Enabled) return;
            premuta = Cella(e.Location);
            Passo();
            ripeti.Interval = 400; ripeti.Start();
            Invalidate();
        }
        protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); ripeti.Stop(); premuta = -1; Invalidate(); }
        protected override void Dispose(bool disposing) { if (disposing) ripeti.Dispose(); base.Dispose(disposing); }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color fondo = nud.BackColor;
            using (Brush b = new SolidBrush(fondo)) g.FillRectangle(b, this.ClientRectangle);
            float w = this.Width / 2f, h = this.Height;
            Color linea = Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(206, 212, 221);
            Color cf = !nud.Enabled ? Color.FromArgb(160, 166, 176) : (Tema.Scuro ? Color.FromArgb(225, 230, 240) : Color.FromArgb(68, 68, 68));
            for (int k = 0; k < 2; k++)
            {
                RectangleF c = new RectangleF(k * w, 0, w, h);
                if ((sopra == k || premuta == k) && nud.Enabled)
                    using (Brush bh = new SolidBrush(Color.FromArgb(premuta == k ? 70 : 38, 31, 111, 209))) g.FillRectangle(bh, c.X + 1, c.Y + 2, c.Width - 2, c.Height - 4);
                float cx = c.X + w / 2f, cy = h / 2f, d = Math.Max(3.5f, Math.Min(w * 0.30f, h / 4.2f));
                using (Pen p = new Pen(sopra == k && nud.Enabled ? Color.FromArgb(31, 111, 209) : cf, Math.Max(1.1f, h / 20f)))
                {
                    p.StartCap = LineCap.Round; p.EndCap = LineCap.Round; p.LineJoin = LineJoin.Round;
                    if (k == 0) g.DrawLines(p, new PointF[] { new PointF(cx - d, cy + d / 2f), new PointF(cx, cy - d / 2f), new PointF(cx + d, cy + d / 2f) });
                    else g.DrawLines(p, new PointF[] { new PointF(cx - d, cy - d / 2f), new PointF(cx, cy + d / 2f), new PointF(cx + d, cy - d / 2f) });
                }
            }
            using (Pen ps = new Pen(linea, 1f))
            {
                // come in YA-MS: separatori a tutta altezza, da bordo a bordo
                g.DrawLine(ps, 0.5f, 0, 0.5f, h);
                g.DrawLine(ps, w, 0, w, h);
            }
        }
    }

    // Pulsanti nello stile dei bozzetti v28: pieno (fondo colorato e testo bianco), con bordo (fondo bianco),
    // casella (interruttore con bordo colorato e quadratino di spunta; grigia quando è spenta)

    // Terre emerse da Natural Earth (ne_50m_land, pubblico dominio), griglia di 0,2° (1800 × 900) codificata a corse:
    // per ogni riga, lunghezze alterne mare/terra in varint, poi base64. Serve alla linguetta Luna sul mondo.
    static class TerreEmerse
    {
        public const int W = 1800, H = 900;
        static byte[] maschera;
        public static byte[] Maschera { get { if (maschera == null) maschera = Decodifica(); return maschera; } }
        static byte[] Decodifica()
        {
            byte[] d = Convert.FromBase64String(Dati);
            byte[] m = new byte[W * H];
            int i = 0;
            for (int y = 0; y < H; y++)
            {
                int x = 0; bool terra = false;
                while (x < W && i < d.Length)
                {
                    int n = 0, sh = 0;
                    while (true) { int c = d[i++]; n |= (c & 127) << sh; sh += 7; if (c < 128) break; }
                    if (terra) for (int k = 0; k < n && x + k < W; k++) m[y * W + x + k] = 1;
                    x += n; terra = !terra;
                }
            }
            return m;
        }
        const string Dati = "";
    }

    enum StilePillola { Pieno, Bordo, Casella }

    // Casella di spunta con lo stesso aspetto della Pillola "Casella" (bordo arrotondato, quadratino colorato
    // con la spunta bianca, testo in grassetto). Il colore è quello della linguetta in cui si trova (ColoriLinguette),
    // oppure quello scelto con Colore.
    class Spunta : CheckBox
    {
        public Color Colore = Color.Empty;
        public static readonly Dictionary<Control, Color> ColoriLinguette = new Dictionary<Control, Color>();
        public static Color Predefinito = Color.FromArgb(31, 111, 209);
        bool sopra;

        public Spunta()
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
            this.BackColor = Color.Transparent;
            this.Cursor = Cursors.Hand;
            this.Font = new Font(this.Font, FontStyle.Bold);
        }

        Color ColoreUsato()
        {
            if (!Colore.IsEmpty) return Colore;
            for (Control c = this.Parent; c != null; c = c.Parent)
            {
                Color k;
                if (ColoriLinguette.TryGetValue(c, out k)) return k;
            }
            return Predefinito;
        }

        public override Size GetPreferredSize(Size proposed)
        {
            int h = this.Font.Height;
            Size t = TextRenderer.MeasureText(this.Text ?? "", this.Font, Size.Empty, TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
            return new Size(t.Width + (int)(h * 2.95f), (int)(h * 1.75f));
        }

        protected override void OnFontChanged(EventArgs e)
        {
            if (!this.Font.Bold) { this.Font = new Font(this.Font, FontStyle.Bold); return; }
            base.OnFontChanged(e);
        }
        protected override void OnMouseEnter(EventArgs e) { sopra = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { sopra = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnCheckedChanged(EventArgs e) { Invalidate(); base.OnCheckedChanged(e); }
        protected override void OnEnabledChanged(EventArgs e) { Invalidate(); base.OnEnabledChanged(e); }

        static Color Mescola(Color a, Color b, float k)
        {
            return Color.FromArgb((int)(a.R + (b.R - a.R) * k), (int)(a.G + (b.G - a.G) * k), (int)(a.B + (b.B - a.B) * k));
        }
        static Rectangle Rect(RectangleF r) { return new Rectangle((int)Math.Round(r.X), (int)Math.Round(r.Y), (int)Math.Round(r.Width), (int)Math.Round(r.Height)); }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            int h = this.Font.Height;
            float bw = Math.Max(1.2f, h / 9f);
            RectangleF r = new RectangleF(bw / 2 + 0.5f, bw / 2 + 0.5f, this.Width - bw - 1.5f, this.Height - bw - 1.5f);
            float rag = Math.Min(r.Height / 2f, h * 0.42f);
            Color col = ColoreUsato();
            Color carta = Tema.Scuro ? Tema.Field : Color.White;
            Color grigio = Tema.Scuro ? Color.FromArgb(120, 128, 140) : Color.FromArgb(150, 156, 166);
            bool acceso = this.Enabled && this.Checked;
            Color c = acceso ? col : grigio;
            using (GraphicsPath p = MainForm.Arrotondato(r, rag))
            {
                Color fondo = acceso ? Mescola(carta, col, Tema.Scuro ? 0.15f : 0.06f) : (sopra && this.Enabled ? Mescola(carta, col, 0.05f) : carta);
                using (Brush b = new SolidBrush(fondo)) g.FillPath(b, p);
                using (Pen pn = new Pen(c, bw * (acceso ? 1.6f : 1.2f))) g.DrawPath(pn, p);
            }
            float q = h * 0.9f;
            RectangleF box = new RectangleF(r.X + h * 0.42f, r.Y + (r.Height - q) / 2, q, q);
            using (GraphicsPath pb = MainForm.Arrotondato(box, q * 0.2f))
            {
                if (acceso)
                {
                    using (Brush bb = new SolidBrush(col)) g.FillPath(bb, pb);
                    using (Pen pv = new Pen(Color.White, Math.Max(1.5f, q / 7f)))
                    {
                        pv.StartCap = LineCap.Round; pv.EndCap = LineCap.Round; pv.LineJoin = LineJoin.Round;
                        g.DrawLines(pv, new PointF[] { new PointF(box.X + q * 0.24f, box.Y + q * 0.52f), new PointF(box.X + q * 0.43f, box.Y + q * 0.70f), new PointF(box.X + q * 0.77f, box.Y + q * 0.32f) });
                    }
                }
                else
                {
                    using (Brush bb = new SolidBrush(carta)) g.FillPath(bb, pb);
                    using (Pen pg = new Pen(grigio, bw)) g.DrawPath(pg, pb);
                }
            }
            float xt = box.Right + h * 0.45f;
            Color ct = !this.Enabled ? grigio : (acceso ? (Tema.Scuro ? Mescola(col, Color.White, 0.5f) : col) : (Tema.Scuro ? Tema.Fore : Color.FromArgb(55, 65, 81)));
            TextFormatFlags tfs = TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding | TextFormatFlags.EndEllipsis;
            TextRenderer.DrawText(g, this.Text, this.Font, Rect(new RectangleF(xt, r.Y, Math.Max(1, r.Right - xt - h * 0.3f), r.Height)), ct, tfs);
            if (this.Focused && this.ShowFocusCues)
                using (Pen pf = new Pen(Color.FromArgb(120, col), 1f)) { pf.DashStyle = DashStyle.Dot; g.DrawRectangle(pf, Rect(new RectangleF(xt - 2, r.Y + 3, Math.Max(1, r.Right - xt - h * 0.2f), r.Height - 6))); }
        }
    }

    // Scelta tonda (radio) disegnata come Spunta: cerchio colorato pieno quando è scelta
    class Tondino : RadioButton
    {
        bool sopra;
        public Tondino()
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
            this.BackColor = Color.Transparent;
            this.Cursor = Cursors.Hand;
            this.AutoSize = true;
        }
        public override Size GetPreferredSize(Size proposed)
        {
            int h = this.Font.Height;
            Size t = TextRenderer.MeasureText(this.Text ?? "", this.Font, Size.Empty, TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
            return new Size(t.Width + (int)(h * 1.7f), (int)(h * 1.75f));
        }
        protected override void OnMouseEnter(EventArgs e) { sopra = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { sopra = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnCheckedChanged(EventArgs e) { Invalidate(); base.OnCheckedChanged(e); }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            using (Brush bf = new SolidBrush(this.Parent != null ? this.Parent.BackColor : Tema.Back)) g.FillRectangle(bf, this.ClientRectangle);
            int h = this.Font.Height;
            float q = h * 0.85f, bw = Math.Max(1.4f, h / 8f);
            RectangleF c = new RectangleF(h * 0.2f, (this.Height - q) / 2f, q, q);
            Color verde = Color.FromArgb(22, 163, 74), grigio = Tema.Scuro ? Color.FromArgb(150, 158, 170) : Color.FromArgb(71, 85, 105);
            using (Brush bc = new SolidBrush(Tema.Scuro ? Tema.Field : Color.White)) g.FillEllipse(bc, c);
            using (Pen pc = new Pen(this.Checked ? verde : (sopra ? Color.FromArgb(31, 111, 209) : grigio), bw)) g.DrawEllipse(pc, c);
            if (this.Checked)
            {
                float d = q * 0.45f;
                using (Brush bv = new SolidBrush(verde)) g.FillEllipse(bv, c.X + (q - d) / 2f, c.Y + (q - d) / 2f, d, d);
            }
            TextRenderer.DrawText(g, this.Text, this.Font, new Rectangle((int)(c.Right + h * 0.35f), 0, this.Width - (int)(c.Right + h * 0.35f), this.Height),
                this.Enabled ? Tema.Fore : Tema.Muted, TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding);
        }
    }

    // Pulsante normale disegnato come la Pillola piena (sfondo colorato arrotondato, scritta bianca in grassetto):
    // blu per le azioni, grigio ardesia per Annulla/Chiudi; nel tema notte un po' più chiari
    class Pulsante : Button
    {
        // nuovo stile: i pulsanti si scrivono in maiuscolo (OK resta OK)
        public bool Maiuscolo = true;
        string Scritta { get { string t = this.Text ?? ""; return Maiuscolo ? t.ToUpper(Lang.Cultura) : t; } }
        protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Invalidate(); }
        public Color Colore = Color.Empty;
        bool sopra, giu;
        public Pulsante()
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
            this.BackColor = Color.Transparent;
            this.Cursor = Cursors.Hand;
            this.Font = new Font(this.Font, FontStyle.Bold);
        }
        protected override void OnFontChanged(EventArgs e)
        {
            if (!this.Font.Bold) { this.Font = new Font(this.Font, FontStyle.Bold); return; }
            base.OnFontChanged(e);
        }
        protected override void OnMouseEnter(EventArgs e) { sopra = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { sopra = false; giu = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseDown(MouseEventArgs e) { giu = true; Invalidate(); base.OnMouseDown(e); }
        protected override void OnMouseUp(MouseEventArgs e) { giu = false; Invalidate(); base.OnMouseUp(e); }
        protected override void OnEnabledChanged(EventArgs e) { Invalidate(); base.OnEnabledChanged(e); }
        public override Size GetPreferredSize(Size proposed)
        {
            Size t = TextRenderer.MeasureText(Scritta, this.Font, Size.Empty, TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
            int h = this.Font.Height;
            return new Size(t.Width + (int)(h * 1.8f), (int)(h * 1.9f));
        }
        static Color Mescola(Color a, Color b, float k)
        {
            return Color.FromArgb((int)(a.R + (b.R - a.R) * k), (int)(a.G + (b.G - a.G) * k), (int)(a.B + (b.B - a.B) * k));
        }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color baseC = !Colore.IsEmpty ? Colore : (this.DialogResult == DialogResult.Cancel || this.DialogResult == DialogResult.No ? Color.FromArgb(75, 85, 99) : Color.FromArgb(31, 111, 209));
            if (Tema.Scuro) baseC = Mescola(baseC, Color.White, 0.12f);
            Color c = !this.Enabled ? Color.FromArgb(150, 156, 166) : (giu ? Mescola(baseC, Color.Black, 0.18f) : (sopra ? Mescola(baseC, Color.White, 0.12f) : baseC));
            int h = this.Font.Height;
            float bw = Math.Max(1.2f, h / 9f);
            RectangleF r = new RectangleF(1, 1, this.Width - 2.5f, this.Height - bw - 2.5f);
            float rag = Math.Min(r.Height / 2f, h * 0.42f);
            using (Brush om = new SolidBrush(Color.FromArgb(40, 0, 0, 0)))
            using (GraphicsPath po = MainForm.Arrotondato(new RectangleF(r.X, r.Y + bw, r.Width, r.Height), rag)) g.FillPath(om, po);
            using (GraphicsPath p = MainForm.Arrotondato(r, rag))
            using (Brush b = new SolidBrush(c)) g.FillPath(b, p);
            TextRenderer.DrawText(g, Scritta, this.Font, new Rectangle((int)r.X, (int)r.Y, (int)r.Width, (int)r.Height), Color.White,
                TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPrefix | TextFormatFlags.EndEllipsis);
            if (this.Focused && this.ShowFocusCues)
                using (Pen pf = new Pen(Color.FromArgb(160, 255, 255, 255), 1f)) { pf.DashStyle = DashStyle.Dot; g.DrawRectangle(pf, r.X + 3, r.Y + 3, r.Width - 7, r.Height - 7); }
        }
    }

    class Pillola : Control, IButtonControl
    {
        DialogResult risultato = DialogResult.None;
        public DialogResult DialogResult { get { return risultato; } set { risultato = value; } }
        public void NotifyDefault(bool value) { }
        public void PerformClick() { if (this.Enabled) OnClick(EventArgs.Empty); }
        public StilePillola Stile;
        public Color Colore;
        public string Nota = "";      // testo piccolo grigio dopo la scritta (es. "⇄ Budget")
        public bool Maiuscolo = true; // nuovo stile: i pulsanti (Pieno, Bordo) si scrivono in maiuscolo; false per le pastiglie dei filtri
        bool sopra, giu, spunta;
        string Scritta { get { string t = this.Text ?? ""; return Maiuscolo && Stile != StilePillola.Casella ? t.ToUpper(Lang.Cultura) : t; } }
        public event EventHandler CheckedChanged;

        public Pillola(string testo, StilePillola stile, Color colore, Font f)
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor | ControlStyles.Selectable, true);
            this.BackColor = Color.Transparent;
            this.Text = testo; Stile = stile; Colore = colore; this.Font = f;
            this.Cursor = Cursors.Hand;
            this.AutoSize = true;
            this.TabStop = true;
            this.Size = GetPreferredSize(Size.Empty);
        }

        public bool Checked
        {
            get { return spunta; }
            set
            {
                if (spunta == value) return;
                spunta = value; Invalidate();
                if (CheckedChanged != null) CheckedChanged(this, EventArgs.Empty);
            }
        }

        public override Size GetPreferredSize(Size proposed)
        {
            int h = this.Font.Height;
            Size t = TextRenderer.MeasureText(Scritta, this.Font, Size.Empty, TextFormatFlags.NoPadding | TextFormatFlags.SingleLine);
            int w = t.Width + (int)(h * 1.5f);
            if (Stile == StilePillola.Casella)
            {
                w += (int)(h * 1.45f);
                if (!string.IsNullOrEmpty(Nota))
                    using (Font fn = new Font(this.Font.FontFamily, this.Font.Size * 0.8f, FontStyle.Regular))
                        w += TextRenderer.MeasureText(Nota, fn, Size.Empty, TextFormatFlags.NoPadding | TextFormatFlags.SingleLine).Width + h / 2;
            }
            return new Size(w, (int)(h * 1.85f));
        }

        void Ridimensiona() { if (this.AutoSize) this.Size = GetPreferredSize(Size.Empty); }
        protected override void OnTextChanged(EventArgs e) { base.OnTextChanged(e); Ridimensiona(); Invalidate(); }
        protected override void OnFontChanged(EventArgs e) { base.OnFontChanged(e); Ridimensiona(); Invalidate(); }
        public void Aggiorna() { Ridimensiona(); Invalidate(); }
        protected override void OnMouseEnter(EventArgs e) { sopra = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { sopra = false; giu = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseDown(MouseEventArgs e) { if (e.Button == MouseButtons.Left) { giu = true; Invalidate(); } base.OnMouseDown(e); }
        protected override void OnMouseUp(MouseEventArgs e) { giu = false; Invalidate(); base.OnMouseUp(e); }
        protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); Invalidate(); }
        protected override void OnClick(EventArgs e)
        {
            if (Stile == StilePillola.Casella) Checked = !Checked;
            base.OnClick(e);
            if (risultato != DialogResult.None)
            {
                Form f = this.FindForm();
                if (f != null) f.DialogResult = risultato;
            }
        }
        protected override void OnKeyDown(KeyEventArgs e)
        {
            if (e.KeyCode == Keys.Space || e.KeyCode == Keys.Enter) { OnClick(EventArgs.Empty); e.Handled = true; }
            base.OnKeyDown(e);
        }

        const TextFormatFlags Centro = TextFormatFlags.HorizontalCenter | TextFormatFlags.VerticalCenter | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding;
        static Rectangle Rect(RectangleF r) { return new Rectangle((int)Math.Round(r.X), (int)Math.Round(r.Y), (int)Math.Round(r.Width), (int)Math.Round(r.Height)); }

        static Color Mescola(Color a, Color b, float k)
        {
            return Color.FromArgb((int)(a.R + (b.R - a.R) * k), (int)(a.G + (b.G - a.G) * k), (int)(a.B + (b.B - a.B) * k));
        }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            g.TextRenderingHint = System.Drawing.Text.TextRenderingHint.AntiAliasGridFit;
            int h = this.Font.Height;
            float bw = Math.Max(1.2f, h / 9f);
            RectangleF r = new RectangleF(bw / 2 + 0.5f, bw / 2 + 0.5f, this.Width - bw - 1.5f, this.Height - bw - 1.5f);
            float rag = Math.Min(r.Height / 2f, h * 0.42f);
            Color carta = Tema.Scuro ? Tema.Field : Color.White;
            Color grigio = Tema.Scuro ? Color.FromArgb(120, 128, 140) : Color.FromArgb(150, 156, 166);
            bool on = this.Enabled;
            using (GraphicsPath p = MainForm.Arrotondato(r, rag))
            using (StringFormat sf = new StringFormat())
            {
                sf.LineAlignment = StringAlignment.Center;
                sf.FormatFlags = StringFormatFlags.NoWrap;
                sf.Trimming = StringTrimming.EllipsisCharacter;
                if (Stile == StilePillola.Pieno)
                {
                    Color c = !on ? grigio : (giu ? Mescola(Colore, Color.Black, 0.18f) : (sopra ? Mescola(Colore, Color.White, 0.12f) : Colore));
                    using (Brush om = new SolidBrush(Color.FromArgb(40, 0, 0, 0)))
                    using (GraphicsPath po = MainForm.Arrotondato(new RectangleF(r.X, r.Y + bw, r.Width, r.Height), rag)) g.FillPath(om, po);
                    using (Brush b = new SolidBrush(c)) g.FillPath(b, p);
                    TextRenderer.DrawText(g, Scritta, this.Font, Rect(r), Color.White, Centro);
                }
                else if (Stile == StilePillola.Bordo)
                {
                    Color c = on ? Colore : grigio;
                    using (Brush b = new SolidBrush(sopra && on ? Mescola(carta, Colore, 0.08f) : carta)) g.FillPath(b, p);
                    using (Pen pn = new Pen(Mescola(c, carta, 0.25f), bw)) g.DrawPath(pn, p);
                    TextRenderer.DrawText(g, Scritta, this.Font, Rect(r), Tema.Scuro ? Mescola(c, Color.White, 0.5f) : c, Centro);
                }
                else
                {
                    bool acceso = on && spunta;
                    Color c = acceso ? Colore : grigio;
                    using (Brush b = new SolidBrush(acceso ? Mescola(carta, Colore, Tema.Scuro ? 0.15f : 0.06f) : carta)) g.FillPath(b, p);
                    using (Pen pn = new Pen(c, bw * (acceso ? 1.6f : 1.2f))) g.DrawPath(pn, p);
                    float q = h * 0.95f;
                    RectangleF box = new RectangleF(r.X + h * 0.45f, r.Y + (r.Height - q) / 2, q, q);
                    using (GraphicsPath pb = MainForm.Arrotondato(box, q * 0.2f))
                    {
                        if (acceso)
                        {
                            using (Brush bb = new SolidBrush(Colore)) g.FillPath(bb, pb);
                            using (Pen pv = new Pen(Color.White, Math.Max(1.5f, q / 7f)))
                            {
                                pv.StartCap = LineCap.Round; pv.EndCap = LineCap.Round; pv.LineJoin = LineJoin.Round;
                                g.DrawLines(pv, new PointF[] { new PointF(box.X + q * 0.24f, box.Y + q * 0.52f), new PointF(box.X + q * 0.43f, box.Y + q * 0.70f), new PointF(box.X + q * 0.77f, box.Y + q * 0.32f) });
                            }
                        }
                        else
                        {
                            using (Brush bb = new SolidBrush(carta)) g.FillPath(bb, pb);
                            using (Pen pg = new Pen(grigio, bw)) g.DrawPath(pg, pb);
                        }
                    }
                    float xt = box.Right + h * 0.5f;
                    sf.Alignment = StringAlignment.Near;
                    Color ct = acceso ? (Tema.Scuro ? Mescola(Colore, Color.White, 0.5f) : Colore) : (Tema.Scuro ? Tema.Fore : Color.FromArgb(55, 65, 81));
                    TextFormatFlags tfs = TextFormatFlags.VerticalCenter | TextFormatFlags.Left | TextFormatFlags.SingleLine | TextFormatFlags.NoPadding;
                    float wt = TextRenderer.MeasureText(g, this.Text, this.Font, Size.Empty, tfs).Width;
                    TextRenderer.DrawText(g, this.Text, this.Font, Rect(new RectangleF(xt, r.Y, r.Right - xt, r.Height)), ct, tfs | TextFormatFlags.EndEllipsis);
                    if (!string.IsNullOrEmpty(Nota))
                        using (Font fn = new Font(this.Font.FontFamily, this.Font.Size * 0.8f, FontStyle.Regular))
                            TextRenderer.DrawText(g, Nota, fn, Rect(new RectangleF(xt + wt + h * 0.5f, r.Y, Math.Max(1, r.Right - xt - wt - h * 0.5f), r.Height)),
                                Tema.Scuro ? Tema.Muted : Color.FromArgb(120, 126, 136), tfs);
                }
            }
            if (this.Focused && this.ShowFocusCues)
                using (Pen pf = new Pen(Color.FromArgb(120, Colore))) { pf.DashStyle = DashStyle.Dot; g.DrawRectangle(pf, 2, 2, this.Width - 5, this.Height - 5); }
        }
    }

    // Tendina con gli angoli arrotondati: la ComboBox sta dentro una cornice disegnata che ne copre i bordi squadrati
    // Menu a tendina con lo stesso aspetto in tutti gli schemi di colori: tendina piatta, bordo arrotondato e freccia
    // a "v" sottile (come quelle della barra delle impostazioni). Disegna sopra la tendina di sistema dopo ogni WM_PAINT.
    class Tendina : ComboBox
    {
        public bool Cornice = true;          // false quando sta già dentro una CorniceTonda
        public Color Fondo = Color.Empty;    // colore di ciò che sta dietro gli angoli (vuoto = il primo genitore opaco)
        public bool SuCarta;                 // la tendina sta su una scheda bianca disegnata (Tema.Carta)
        public Tendina() { this.FlatStyle = FlatStyle.Flat; }

        protected override void WndProc(ref Message m)
        {
            base.WndProc(ref m);
            if (m.Msg == 0x000F || m.Msg == 0x0085)   // WM_PAINT, WM_NCPAINT
                try { Ridisegna(); } catch { }
        }
        protected override void OnMouseEnter(EventArgs e) { base.OnMouseEnter(e); Invalidate(); }
        protected override void OnMouseLeave(EventArgs e) { base.OnMouseLeave(e); Invalidate(); }

        Color Dietro()
        {
            if (!Fondo.IsEmpty) return Fondo;
            if (SuCarta) return Tema.Carta;
            for (Control c = this.Parent; c != null; c = c.Parent)
                if (c.BackColor.A == 255) return c.BackColor;
            return Tema.Back;
        }

        void Ridisegna()
        {
            if (!this.IsHandleCreated || this.Width < 10 || this.Height < 8) return;
            using (Graphics g = Graphics.FromHwnd(this.Handle))
            {
                g.SmoothingMode = SmoothingMode.AntiAlias;
                Rectangle cr = this.ClientRectangle;
                Color campo = this.Enabled ? this.BackColor : (Tema.Scuro ? Tema.Section : Color.FromArgb(243, 244, 246));
                // zona della freccia: fondo del campo e "v" sottile
                int wf = Math.Max(14, SystemInformation.VerticalScrollBarWidth);
                Rectangle rf = new Rectangle(cr.Right - wf - 1, cr.Top + 1, wf, cr.Height - 2);
                using (Brush b = new SolidBrush(campo)) g.FillRectangle(b, rf);
                FrecciaCornice.Chevron(g, rf, this.Enabled ? (Tema.Scuro ? Color.FromArgb(200, 206, 216) : Color.FromArgb(68, 68, 68)) : Color.FromArgb(160, 166, 176));
                if (!Cornice) return;
                // angoli arrotondati: fuori dal bordo il colore di ciò che sta dietro
                float rag = FrecciaCornice.RaggioTendina(this.Font, cr.Height);
                RectangleF rb = new RectangleF(0.5f, 0.5f, cr.Width - 1.5f, cr.Height - 1.5f);
                using (GraphicsPath p = MainForm.Arrotondato(rb, rag))
                {
                    using (Region fuori = new Region(new Rectangle(0, 0, cr.Width, cr.Height)))
                    {
                        fuori.Exclude(p);
                        using (Brush bd = new SolidBrush(Dietro())) g.FillRegion(bd, fuori);
                    }
                    bool sopra = this.ClientRectangle.Contains(this.PointToClient(Control.MousePosition));
                    using (Pen pn = new Pen(FrecciaCornice.BordoTendina(this.Focused, sopra), 1f)) g.DrawPath(pn, p);
                }
            }
        }
    }

    class CorniceTonda : Panel
    {
        public readonly Control Dentro;
        FrecciaCornice freccia;
        public CorniceTonda(Control cb)
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
            this.BackColor = Color.Transparent;
            Dentro = cb;
            if (cb is ComboBox) ((ComboBox)cb).FlatStyle = FlatStyle.Flat;
            if (cb is UpDownBase) ((UpDownBase)cb).BorderStyle = BorderStyle.None;   // caselle dei numeri: il bordo è la cornice tonda
            if (cb is TextBox) ((TextBox)cb).BorderStyle = BorderStyle.None;         // caselle di testo: idem
            Tendina td = cb as Tendina;
            if (td != null) td.Cornice = false;
            this.Controls.Add(cb);
            // nuovo stile: la freccia delle tendine e l'icona del calendario sono disegnate da YAEC, uguali su tutti i sistemi
            ComboBox cmb = cb as ComboBox;
            DateTimePicker dtp = cb as DateTimePicker;
            if ((cmb != null && cmb.DropDownStyle == ComboBoxStyle.DropDownList) || (dtp != null && !dtp.ShowUpDown))
            {
                freccia = new FrecciaCornice(cb);
                this.Controls.Add(freccia);
                freccia.BringToFront();
            }
            this.AutoSize = false;
            Disponi();
            cb.SizeChanged += (s, e) => Disponi();
            cb.EnabledChanged += (s, e) => Invalidate();
        }

        int Bordo { get { return Math.Max(3, Dentro.Font.Height / 4); } }

        void Disponi()
        {
            int b = Bordo;
            bool combo = Dentro is ComboBox || Dentro is DateTimePicker;
            Dentro.Location = combo ? new Point(b + 1, b - 1) : new Point(b + 2, b);
            Size sz = combo ? new Size(Dentro.Width + 2 * b + 2, Dentro.Height + 2 * b - 2) : new Size(Dentro.Width + 2 * b + 4, Dentro.Height + 2 * b);
            if (this.Size != sz) this.Size = sz;
            // nasconde il bordo squadrato della tendina piatta
            if (combo) Dentro.Region = new Region(new Rectangle(1, 1, Math.Max(1, Dentro.Width - 2), Math.Max(1, Dentro.Height - 2)));
            if (freccia != null)
            {
                int wf = Math.Max(S16(), SystemInformation.VerticalScrollBarWidth) + 2;
                freccia.Bounds = new Rectangle(Dentro.Right - wf - 1, Dentro.Top + 1, wf, Math.Max(4, Dentro.Height - 2));
            }
            Invalidate();
        }

        int S16() { return Math.Max(14, Dentro.Font.Height); }

        public override Size GetPreferredSize(Size proposed) { int b = Bordo; return (Dentro is ComboBox || Dentro is DateTimePicker) ? new Size(Dentro.Width + 2 * b + 2, Dentro.Height + 2 * b - 2) : new Size(Dentro.Width + 2 * b + 4, Dentro.Height + 2 * b); }

        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            RectangleF r = new RectangleF(1, 1, this.Width - 3, this.Height - 3);
            bool cmb = Dentro is ComboBox || Dentro is UpDownBase || Dentro is TextBox;
            if (cmb) { FrecciaCornice.DisegnaCampoTendina(g, r, Dentro, Dentro.Focused, freccia != null && freccia.Sopra, Dentro.Left); return; }
            using (GraphicsPath p = MainForm.Arrotondato(r, Math.Min(r.Height / 2f, Dentro.Font.Height * 0.45f)))
            {
                using (Brush b = new SolidBrush(Dentro.BackColor)) g.FillPath(b, p);
                bool attivo = Dentro.Focused || (freccia != null && freccia.Sopra);
                using (Pen pn = new Pen(attivo ? Color.FromArgb(31, 111, 209) : (Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(195, 203, 217)), 1.3f)) g.DrawPath(pn, p);
            }
        }
    }

    // Cornice tonda per i comandi in posizione fissa (schede disegnate, schema del Budget): sta dietro il comando,
    // ne segue posizione, grandezza e visibilità; il bordo squadrato del comando viene nascosto.
    class CorniceDietro : Control
    {
        readonly Control dentro;
        FrecciaCornice freccia;
        CorniceDietro(Control c)
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor, true);
            this.BackColor = Color.Transparent;
            this.TabStop = false;
            dentro = c;
        }
        int Bordo { get { return Math.Max(2, dentro.Font.Height / 6); } }
        public static void Applica(Control c)
        {
            Control p = c.Parent;
            if (p == null) return;
            if (c is TextBox) ((TextBox)c).BorderStyle = BorderStyle.FixedSingle;
            if (c is ComboBox) ((ComboBox)c).FlatStyle = FlatStyle.Flat;
            Tendina td = c as Tendina;
            if (td != null) td.Cornice = false;
            CorniceDietro cd = new CorniceDietro(c);
            p.Controls.Add(cd);
            cd.SendToBack();
            ComboBox cmb = c as ComboBox;
            DateTimePicker dtp = c as DateTimePicker;
            if ((cmb != null && cmb.DropDownStyle == ComboBoxStyle.DropDownList) || (dtp != null && !dtp.ShowUpDown))
            {
                cd.freccia = new FrecciaCornice(c);
                p.Controls.Add(cd.freccia);
                cd.freccia.BringToFront();
            }
            EventHandler segui = (s, e) => cd.Segui();
            c.LocationChanged += segui; c.SizeChanged += segui; c.VisibleChanged += segui; c.EnabledChanged += segui;
            c.GotFocus += (s, e) => cd.Invalidate(); c.LostFocus += (s, e) => cd.Invalidate();
            cd.Segui();
        }
        void Segui()
        {
            int b = Bordo;
            Rectangle r = dentro.Bounds;
            r.Inflate(b + 1, b);
            if (this.Bounds != r) this.Bounds = r;
            this.Visible = dentro.Visible;
            // il bordo squadrato del comando resta fuori dalla sua regione
            if (!(dentro is TextBox)) dentro.Region = new Region(new Rectangle(1, 1, Math.Max(1, dentro.Width - 2), Math.Max(1, dentro.Height - 2)));
            else dentro.Region = new Region(new Rectangle(1, 1, Math.Max(1, dentro.Width - 2), Math.Max(1, dentro.Height - 2)));
            if (freccia != null)
            {
                int wf = Math.Max(14, dentro.Font.Height) + 2;
                freccia.Bounds = new Rectangle(dentro.Right - wf - 1, dentro.Top + 1, wf, Math.Max(4, dentro.Height - 2));
                freccia.Visible = dentro.Visible;
                freccia.BringToFront();
            }
            Invalidate();
        }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            RectangleF r = new RectangleF(1, 1, this.Width - 3, this.Height - 3);
            Color campo = dentro.Enabled ? dentro.BackColor : (Tema.Scuro ? Tema.Section : Color.FromArgb(243, 244, 246));
            bool attivo = dentro.Focused || (freccia != null && freccia.Sopra);
            if (dentro is ComboBox || dentro is UpDownBase || dentro is TextBox) { FrecciaCornice.DisegnaCampoTendina(g, r, dentro, dentro.Focused, freccia != null && freccia.Sopra, dentro.Left - this.Left); return; }
            using (GraphicsPath p = MainForm.Arrotondato(r, Math.Min(r.Height / 2f, dentro.Font.Height * 0.45f)))
            {
                using (Brush b = new SolidBrush(campo)) g.FillPath(b, p);
                using (Pen pn = new Pen(attivo ? Color.FromArgb(31, 111, 209) : (Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(195, 203, 217)), 1.3f)) g.DrawPath(pn, p);
            }
        }
    }

    // Freccia "v" delle tendine e icona del calendario delle date, disegnate sopra il pulsante di sistema:
    // il clic apre la tendina (o il calendario) come il pulsante originale.
    class FrecciaCornice : Control
    {
        readonly Control dentro;
        public bool Sopra;
        public FrecciaCornice(Control c)
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer | ControlStyles.ResizeRedraw, true);
            dentro = c;
            this.Cursor = Cursors.Hand;
            this.TabStop = false;
            c.EnabledChanged += (s, e) => Invalidate();
            c.BackColorChanged += (s, e) => Invalidate();
        }
        protected override void OnMouseEnter(EventArgs e) { Sopra = true; Invalidate(); if (this.Parent != null) this.Parent.Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { Sopra = false; Invalidate(); if (this.Parent != null) this.Parent.Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseDown(MouseEventArgs e)
        {
            base.OnMouseDown(e);
            if (e.Button != MouseButtons.Left || !dentro.Enabled) return;
            dentro.Focus();
            ComboBox cb = dentro as ComboBox;
            if (cb != null) { cb.DroppedDown = !cb.DroppedDown; return; }
            try { SendKeys.Send("%{DOWN}"); } catch { }   // Alt+Giù apre il calendario della data
        }
        protected override void OnMouseWheel(MouseEventArgs e)
        {
            base.OnMouseWheel(e);
            ComboBox cb = dentro as ComboBox;
            if (cb == null || !cb.Enabled || cb.Items.Count == 0) return;
            int i = cb.SelectedIndex + (e.Delta > 0 ? -1 : 1);
            if (i >= 0 && i < cb.Items.Count) cb.SelectedIndex = i;
        }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            Color campo = dentro.Enabled ? dentro.BackColor : (Tema.Scuro ? Tema.Section : Color.FromArgb(243, 244, 246));
            using (Brush b = new SolidBrush(campo)) g.FillRectangle(b, this.ClientRectangle);
            Color cf = !dentro.Enabled ? Color.FromArgb(160, 166, 176) : (Sopra ? Color.FromArgb(31, 111, 209) : (Tema.Scuro ? Color.FromArgb(200, 206, 216) : Color.FromArgb(71, 85, 105)));
            float cx = this.Width / 2f, cy = this.Height / 2f, h = this.Height;
            if (dentro is DateTimePicker)
            {
                // calendario: cornice con la fascia in alto e due anelli
                float w = Math.Min(this.Width - 4, h * 0.62f), hh = w * 0.9f;
                RectangleF r = new RectangleF(cx - w / 2, cy - hh / 2 + 1, w, hh);
                using (Pen p = new Pen(cf, Math.Max(1.2f, h / 18f)))
                using (Brush bb = new SolidBrush(cf))
                {
                    using (GraphicsPath gp = MainForm.Arrotondato(r, w * 0.15f)) g.DrawPath(p, gp);
                    g.FillRectangle(bb, r.X, r.Y, r.Width, hh * 0.28f);
                    g.DrawLine(p, r.X + w * 0.28f, r.Y - hh * 0.14f, r.X + w * 0.28f, r.Y + hh * 0.1f);
                    g.DrawLine(p, r.Right - w * 0.28f, r.Y - hh * 0.14f, r.Right - w * 0.28f, r.Y + hh * 0.1f);
                    float q = w * 0.14f;
                    for (int i = 0; i < 3; i++) for (int j = 0; j < 2; j++)
                        g.FillRectangle(bb, r.X + w * (0.18f + 0.26f * i), r.Y + hh * (0.45f + 0.25f * j), q, q);
                }
                return;
            }
            Chevron(g, this.ClientRectangle, !dentro.Enabled ? Color.FromArgb(160, 166, 176) : (Sopra ? Color.FromArgb(31, 111, 209) : (Tema.Scuro ? Color.FromArgb(200, 206, 216) : Color.FromArgb(68, 68, 68))));
        }

        // Tendine nello stile di YA-MS (Fluent): angoli appena arrotondati, bordo sottile grigio chiaro, fondo del campo,
        // freccia "v" larga e sottile; bordo blu quando è attiva, grigio più scuro con il mouse sopra.
        public static float RaggioTendina(Font f, float h) { return Math.Min(h / 2f - 1, Math.Max(3f, f.Height * 0.27f)); }
        public static Color BordoTendina(bool attivo, bool sopra)
        {
            if (attivo) return Color.FromArgb(31, 111, 209);
            if (Tema.Scuro) return sopra ? Color.FromArgb(150, 160, 175) : Tema.ChartGrid;
            return sopra ? Color.FromArgb(160, 166, 176) : Color.FromArgb(206, 212, 221);
        }
        public static void DisegnaCampoTendina(Graphics g, RectangleF r, Control c, bool attivo, bool sopra, float xDentro)
        {
            Color campo = c.Enabled ? c.BackColor : (Tema.Scuro ? Tema.Section : Color.FromArgb(243, 244, 246));
            using (GraphicsPath p = MainForm.Arrotondato(r, RaggioTendina(c.Font, r.Height)))
            {
                using (Brush b = new SolidBrush(campo)) g.FillPath(b, p);
                // caselle dei numeri: i due separatori delle frecce arrivano fino al bordo, sopra e sotto
                NudUnita nu = c as NudUnita;
                Rectangle z = nu != null ? nu.ZonaFrecce : Rectangle.Empty;
                if (z.Width > 0)
                    using (Pen ps = new Pen(Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(206, 212, 221), 1f))
                    {
                        float x1 = xDentro + z.Left + 0.5f, x2 = xDentro + z.Left + z.Width / 2f;
                        g.DrawLine(ps, x1, r.Top, x1, r.Bottom);
                        g.DrawLine(ps, x2, r.Top, x2, r.Bottom);
                    }
                using (Pen pn = new Pen(BordoTendina(attivo, sopra), attivo ? 1.3f : 1f)) g.DrawPath(pn, p);
            }
        }
        public static void Chevron(Graphics g, RectangleF r, Color c)
        {
            float cx = r.Left + r.Width / 2f, cy = r.Top + r.Height / 2f;
            float d = Math.Max(3.5f, Math.Min(r.Width * 0.30f, r.Height / 4.2f));
            using (Pen pv = new Pen(c, Math.Max(1.1f, r.Height / 20f)))
            {
                pv.StartCap = LineCap.Round; pv.EndCap = LineCap.Round; pv.LineJoin = LineJoin.Round;
                g.DrawLines(pv, new PointF[] { new PointF(cx - d, cy - d / 2f), new PointF(cx, cy + d / 2f), new PointF(cx + d, cy - d / 2f) });
            }
        }
    }

    // Cursore del nuovo stile: binario sottile, parte scelta in blu e pomello tondo (al posto della TrackBar di sistema)
    class Cursore : Control
    {
        int min = 0, max = 100, val = 0;
        public int TickFrequency = 10, SmallChange = 1, LargeChange = 10;
        public event EventHandler ValueChanged;
        bool trascina, sopra;
        public Cursore()
        {
            this.SetStyle(ControlStyles.UserPaint | ControlStyles.AllPaintingInWmPaint | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.ResizeRedraw | ControlStyles.SupportsTransparentBackColor | ControlStyles.Selectable, true);
            this.BackColor = Color.Transparent;
            this.Cursor = Cursors.Hand;
            this.TabStop = true;
        }
        public int Minimum { get { return min; } set { min = value; if (max < min) max = min; Value = val; Invalidate(); } }
        public int Maximum { get { return max; } set { max = value; if (min > max) min = max; Value = val; Invalidate(); } }
        public int Value
        {
            get { return val; }
            set
            {
                int v = Math.Max(min, Math.Min(max, value));
                if (v == val) return;
                val = v; Invalidate();
                if (ValueChanged != null) ValueChanged(this, EventArgs.Empty);
            }
        }
        float Raggio { get { return Math.Max(6f, Math.Min(this.Height / 2f - 2, this.Font.Height * 0.55f)); } }
        float X0 { get { return Raggio + 2; } }
        float X1 { get { return this.Width - Raggio - 2; } }
        void DaMouse(int x) { if (X1 <= X0) return; Value = (int)Math.Round(min + (x - X0) / (X1 - X0) * (max - min)); }
        protected override void OnMouseDown(MouseEventArgs e) { base.OnMouseDown(e); if (e.Button != MouseButtons.Left || !this.Enabled) return; this.Focus(); trascina = true; this.Capture = true; DaMouse(e.X); }
        protected override void OnMouseMove(MouseEventArgs e) { base.OnMouseMove(e); if (trascina) DaMouse(e.X); }
        protected override void OnMouseUp(MouseEventArgs e) { base.OnMouseUp(e); trascina = false; this.Capture = false; }
        protected override void OnMouseEnter(EventArgs e) { sopra = true; Invalidate(); base.OnMouseEnter(e); }
        protected override void OnMouseLeave(EventArgs e) { sopra = false; Invalidate(); base.OnMouseLeave(e); }
        protected override void OnMouseWheel(MouseEventArgs e) { base.OnMouseWheel(e); if (this.Enabled) Value += e.Delta > 0 ? SmallChange : -SmallChange; }
        protected override bool IsInputKey(Keys k) { return k == Keys.Left || k == Keys.Right || k == Keys.Up || k == Keys.Down || base.IsInputKey(k); }
        protected override void OnKeyDown(KeyEventArgs e)
        {
            base.OnKeyDown(e);
            if (e.KeyCode == Keys.Left || e.KeyCode == Keys.Down) Value -= SmallChange;
            else if (e.KeyCode == Keys.Right || e.KeyCode == Keys.Up) Value += SmallChange;
            else if (e.KeyCode == Keys.PageDown) Value -= LargeChange;
            else if (e.KeyCode == Keys.PageUp) Value += LargeChange;
            else if (e.KeyCode == Keys.Home) Value = min;
            else if (e.KeyCode == Keys.End) Value = max;
        }
        protected override void OnEnabledChanged(EventArgs e) { base.OnEnabledChanged(e); Invalidate(); }
        protected override void OnGotFocus(EventArgs e) { base.OnGotFocus(e); Invalidate(); }
        protected override void OnLostFocus(EventArgs e) { base.OnLostFocus(e); Invalidate(); }
        protected override void OnPaint(PaintEventArgs e)
        {
            Graphics g = e.Graphics;
            g.SmoothingMode = SmoothingMode.AntiAlias;
            float cy = this.Height / 2f, t = Math.Max(3f, this.Font.Height / 5f);
            float x = max > min ? X0 + (float)(val - min) / (max - min) * (X1 - X0) : X0;
            Color blu = this.Enabled ? Color.FromArgb(31, 111, 209) : Color.FromArgb(160, 166, 176);
            Color binario = Tema.Scuro ? Tema.ChartGrid : Color.FromArgb(203, 213, 225);
            using (GraphicsPath p = MainForm.Arrotondato(new RectangleF(X0, cy - t / 2, X1 - X0, t), t / 2))
            using (Brush b = new SolidBrush(binario)) g.FillPath(b, p);
            if (x > X0)
                using (GraphicsPath p = MainForm.Arrotondato(new RectangleF(X0, cy - t / 2, x - X0, t), t / 2))
                using (Brush b = new SolidBrush(blu)) g.FillPath(b, p);
            float r = Raggio;
            using (Brush bo = new SolidBrush(Color.FromArgb(40, 0, 0, 0))) g.FillEllipse(bo, x - r, cy - r + 1.5f, 2 * r, 2 * r);
            using (Brush bk = new SolidBrush(Tema.Scuro ? Tema.Field : Color.White)) g.FillEllipse(bk, x - r, cy - r, 2 * r, 2 * r);
            using (Pen pk = new Pen(blu, (sopra || trascina || this.Focused) ? 2.6f : 2f)) g.DrawEllipse(pk, x - r + 1, cy - r + 1, 2 * r - 2, 2 * r - 2);
        }
    }

    class PannelloDisegno : Panel
    {
        public PannelloDisegno()
        {
            this.SetStyle(ControlStyles.SupportsTransparentBackColor | ControlStyles.OptimizedDoubleBuffer
                | ControlStyles.AllPaintingInWmPaint | ControlStyles.UserPaint | ControlStyles.ResizeRedraw
                | ControlStyles.Selectable, true);
            this.BackColor = Color.Transparent;
        }
    }

