        static string Lingua(string l) { return testi.ContainsKey(l) ? l : "en"; }
        public static string T(string lingua, string chiave) { return testi[Lingua(lingua)][chiave]; }
        public static string[] E(string lingua, string chiave) { return elenchi[Lingua(lingua)][chiave]; }
    }

    // Cartella "data" accanto all'eseguibile: contiene TUTTI i dati del programma
    //   impostazioni.txt        impostazioni (la password LoTW è cifrata con DPAPI di Windows)
    //   solar-radio-flux.json   flussi solari RSTN scaricati da NOAA SWPC
    //   lotw.adi                log scaricato da LoTW
    //   tiles\                  tessere della mappa già scaricate
    // Alla prima esecuzione vi si spostano i dati delle versioni precedenti
    // (AppData\Roaming\LunaCalc e la cartella dell'eseguibile).
    // Windows, Linux o macOS: su Linux e macOS il programma gira con Mono (stesso YAEC.exe)
    static class Piattaforma
    {
        public static readonly bool Windows = Environment.OSVersion.Platform == PlatformID.Win32NT
            || Environment.OSVersion.Platform == PlatformID.Win32Windows;
        public static readonly bool Mac = !Windows && Directory.Exists("/System/Library/CoreServices") && Directory.Exists("/Applications");
        public static readonly bool Linux = !Windows && !Mac;
        public static readonly bool Mono = Type.GetType("Mono.Runtime") != null;
        public static string Nome { get { return Windows ? "Windows" : (Mac ? "macOS" : "Linux"); } }
    }

    // ---------- Orizzonte dal terreno (DEM SRTM1) ----------
    // Riquadri SRTM da 1" (3601 × 3601 quote a 16 bit, big-endian) presi da AWS Open Data (elevation-tiles-prod, formato "skadi")
    // e salvati compressi in data/dem. I riquadri vicini alla stazione si leggono a piena risoluzione, quelli lontani uno
    // ogni tre punti (circa 90 m), che bastano per l'orizzonte e tengono bassa la memoria.
    static class Terreno
    {
        public const string UrlBase = "https://s3.amazonaws.com/elevation-tiles-prod/skadi/";
        class Riquadro { public short[] H; public int N; }
        static readonly Dictionary<string, Riquadro> cache = new Dictionary<string, Riquadro>();
        static readonly object blocco = new object();

        public static string Cartella
        {
            get { string d = Dati.Percorso("dem"); try { Directory.CreateDirectory(d); } catch { } return d; }
        }

        public static string Nome(int lat, int lon)
        {
            return (lat >= 0 ? "N" : "S") + Math.Abs(lat).ToString("00", CultureInfo.InvariantCulture)
                + (lon >= 0 ? "E" : "W") + Math.Abs(lon).ToString("000", CultureInfo.InvariantCulture);
        }

        public static void Svuota() { lock (blocco) cache.Clear(); }

        // Scarica (se manca) e legge il riquadro; fine = piena risoluzione. Restituisce i byte del file compresso (0 se è mare).
        public static long Prepara(int lat, int lon, bool fine)
        {
            string n = Nome(lat, lon);
            string p = Path.Combine(Cartella, n + ".hgt.gz"), mare = Path.Combine(Cartella, n + ".mare");
            lock (blocco)
            {
                Riquadro r;
                if (cache.TryGetValue(n, out r) && (r == null || !fine || r.N == 3601)) return File.Exists(p) ? new FileInfo(p).Length : 0;
            }
            if (!File.Exists(p) && !File.Exists(mare))
            {
                string url = UrlBase + n.Substring(0, 3) + "/" + n + ".hgt.gz";
                try
                {
                    byte[] b = Dati.Scarica(url, 120000);
                    if (b.Length < 1000) throw new IOException("short");
                    Dati.ScriviAtomico(p, b);
                }
                catch (WebException ex)
                {
                    HttpWebResponse hr = ex.Response as HttpWebResponse;
                    if (hr != null && (hr.StatusCode == HttpStatusCode.NotFound || hr.StatusCode == HttpStatusCode.Forbidden))
                    {
                        // riquadro senza terre emerse: mare a quota 0
                        try { File.WriteAllText(mare, ""); } catch { }
                    }
                    else throw;
                }
            }
            Riquadro q = null;
            if (File.Exists(p))
            {
                byte[] raw;
                using (FileStream fs = File.OpenRead(p))
                using (System.IO.Compression.GZipStream z = new System.IO.Compression.GZipStream(fs, System.IO.Compression.CompressionMode.Decompress))
                using (MemoryStream ms = new MemoryStream())
                {
                    z.CopyTo(ms);
                    raw = ms.ToArray();
                }
                int n0 = (int)Math.Round(Math.Sqrt(raw.Length / 2.0));
                if (n0 < 100 || n0 * n0 * 2 != raw.Length) throw new IOException("DEM " + n);
                int passo = fine || n0 < 3601 ? 1 : 3;
                int nn = (n0 - 1) / passo + 1;
                short[] h = new short[nn * nn];
                for (int i = 0; i < nn; i++)
                    for (int j = 0; j < nn; j++)
                    {
                        int k = ((i * passo) * n0 + j * passo) * 2;
                        short v = (short)((raw[k] << 8) | raw[k + 1]);
                        h[i * nn + j] = v < -500 ? (short)0 : v;   // vuoti dei dati (−32768): quota 0
                    }
                q = new Riquadro(); q.H = h; q.N = nn;
            }
            lock (blocco) cache[n] = q;
            return File.Exists(p) ? new FileInfo(p).Length : 0;
        }

        // Quota del terreno (m) con interpolazione bilineare; 0 sul mare o se il riquadro non è caricato
        public static double Quota(double lat, double lon)
        {
            int la = (int)Math.Floor(lat), lo = (int)Math.Floor(lon);
            Riquadro r;
            lock (blocco) { if (!cache.TryGetValue(Nome(la, lo), out r)) return 0; }
            if (r == null) return 0;
            int n = r.N;
            double y = (la + 1 - lat) * (n - 1), x = (lon - lo) * (n - 1);
            int i = Math.Max(0, Math.Min(n - 2, (int)y)), j = Math.Max(0, Math.Min(n - 2, (int)x));
            double fy = y - i, fx = x - j;
            double a = r.H[i * n + j], b = r.H[i * n + j + 1], c = r.H[(i + 1) * n + j], d = r.H[(i + 1) * n + j + 1];
            return (a * (1 - fx) + b * fx) * (1 - fy) + (c * (1 - fx) + d * fx) * fy;
        }

        // Quota più alta di un riquadro caricato
        public static int Massimo(int lat, int lon)
        {
            Riquadro r;
            lock (blocco) { if (!cache.TryGetValue(Nome(lat, lon), out r) || r == null) return 0; }
            int m = 0;
            foreach (short v in r.H) if (v > m) m = v;
            return m;
        }

        // Punto a distanza d (m) e azimut az (gradi) da (lat, lon), su una sfera di 6371 km
        public static void Destinazione(double lat, double lon, double az, double d, out double la2, out double lo2)
        {
            double R = 6371000.0, f1 = lat * Math.PI / 180.0, l1 = lon * Math.PI / 180.0, b = az * Math.PI / 180.0, dr = d / R;
            double sf2 = Math.Sin(f1) * Math.Cos(dr) + Math.Cos(f1) * Math.Sin(dr) * Math.Cos(b);
            double f2 = Math.Asin(Math.Max(-1, Math.Min(1, sf2)));
            double l2 = l1 + Math.Atan2(Math.Sin(b) * Math.Sin(dr) * Math.Cos(f1), Math.Cos(dr) - Math.Sin(f1) * Math.Sin(f2));
            la2 = f2 * 180.0 / Math.PI; lo2 = l2 * 180.0 / Math.PI;
        }
    }

    // Un ostacolo dell'orizzonte: settore di azimut, elevazione, distanza e nome (da OpenStreetMap, se raggiungibile)
    class Ostacolo
    {
        public double Az1, Az2, AzPicco, ElMax, ElMin, Dist, Lat, Lon;
        public bool Varco, Mare;
        public double LatTerra = double.NaN, LonTerra = double.NaN;   // varco: la prima terra lontana in quella direzione
        public string Nome = "";
    }

    // L'orizzonte calcolato: elevazione del terreno grado per grado (passo scelto), con i dati del calcolo.
    // Salvato in data/dem/orizzonte.txt, così vale anche alla riapertura del programma.
    class Orizzonte
    {
        public double Passo = 0.5, Lat, Lon, Suolo, Antenna, Raggio, K = 4.0 / 3.0, HMax;
        public double[] El = new double[0], Dist = new double[0];
        public string Loc = "";
        public int Riquadri, RiquadriMare, LatMin, LatMax, LonMin, LonMax;
        public long Byte;
        public DateTime Quando;
        public List<Ostacolo> Ostacoli = new List<Ostacolo>();

        public bool Valido { get { return El.Length > 0; } }
        public double MaxEl { get { double m = -90; foreach (double v in El) if (v > m) m = v; return m; } }

        // elevazione del terreno (gradi) all'azimut az, interpolata
        public double Elev(double az)
        {
            int n = El.Length;
            if (n == 0) return double.NaN;
            double x = (((az % 360.0) + 360.0) % 360.0) / Passo;
            int i = (int)Math.Floor(x) % n;
            double f = x - Math.Floor(x);
            return El[i] * (1 - f) + El[(i + 1) % n] * f;
        }
        public double Distanza(double az)
        {
            int n = Dist.Length;
            if (n == 0) return 0;
            int i = (int)Math.Round((((az % 360.0) + 360.0) % 360.0) / Passo) % n;
            return Dist[i];
        }

        static string Percorso { get { return Path.Combine(Terreno.Cartella, "orizzonte.txt"); } }
        // orizzonte di una stazione DX (v1.9.5): un file per locator, data/dem/orizzonte_<LOCATOR>.txt
        public static string NomeFileDx(string loc) { return "orizzonte_" + (loc ?? "").Trim().ToUpperInvariant() + ".txt"; }
        public static string PercorsoDx(string loc) { return Path.Combine(Terreno.Cartella, NomeFileDx(loc)); }
        public double SulSuolo = -1;   // DX: altezza dell'antenna sul suolo (m); −1 = la mia stazione (quota s.l.m.)

        public void Salva() { Salva(Percorso); }
        public void Salva(string percorso)
        {
            CultureInfo iv = CultureInfo.InvariantCulture;
            StringBuilder sb = new StringBuilder();
            sb.AppendLine("# YAEC - orizzonte dal terreno (DEM SRTM1)");
            sb.AppendLine("locator=" + Loc);
            sb.AppendLine("lat=" + Lat.ToString("R", iv)); sb.AppendLine("lon=" + Lon.ToString("R", iv));
            sb.AppendLine("suolo=" + Suolo.ToString("F1", iv)); sb.AppendLine("antenna=" + Antenna.ToString("F1", iv));
            sb.AppendLine("raggio=" + Raggio.ToString("F0", iv)); sb.AppendLine("k=" + K.ToString("R", iv));
            sb.AppendLine("hmax=" + HMax.ToString("F0", iv)); sb.AppendLine("passo=" + Passo.ToString("R", iv));
            sb.AppendLine("riquadri=" + Riquadri.ToString(iv) + "," + RiquadriMare.ToString(iv) + "," + LatMin + "," + LatMax + "," + LonMin + "," + LonMax);
            sb.AppendLine("byte=" + Byte.ToString(iv));
            sb.AppendLine("quando=" + Quando.ToString("yyyy-MM-dd HH:mm", iv));
            foreach (Ostacolo o in Ostacoli)
                sb.AppendLine("ostacolo=" + string.Join(";", new string[] { o.Az1.ToString("F1", iv), o.Az2.ToString("F1", iv), o.AzPicco.ToString("F1", iv),
                    o.ElMax.ToString("F2", iv), o.ElMin.ToString("F2", iv), o.Dist.ToString("F0", iv), o.Lat.ToString("F5", iv), o.Lon.ToString("F5", iv),
                    o.Varco ? (o.Mare ? "2" : "1") : "0", (o.Nome ?? "").Replace(";", ",") }));
            if (SulSuolo >= 0) sb.AppendLine("sulsuolo=" + SulSuolo.ToString("R", iv));
            sb.AppendLine("dati");
            for (int i = 0; i < El.Length; i++) sb.AppendLine(El[i].ToString("F3", iv) + ";" + Dist[i].ToString("F0", iv));
            try { Dati.ScriviAtomico(percorso, Encoding.UTF8.GetBytes(sb.ToString())); } catch { }
        }

        public static Orizzonte Carica() { return Carica(Percorso); }
        public static Orizzonte Carica(string percorso)
        {
            try
            {
                if (!File.Exists(percorso)) return null;
                CultureInfo iv = CultureInfo.InvariantCulture;
                Orizzonte o = new Orizzonte();
                List<double> el = new List<double>(), di = new List<double>();
                bool dati = false;
                foreach (string r0 in File.ReadAllLines(percorso, Encoding.UTF8))
                {
                    string r = r0.Trim();
                    if (r.Length == 0 || r.StartsWith("#")) continue;
                    if (dati)
                    {
                        string[] p = r.Split(';');
                        if (p.Length == 2) { el.Add(double.Parse(p[0], iv)); di.Add(double.Parse(p[1], iv)); }
                        continue;
                    }
                    if (r == "dati") { dati = true; continue; }
                    int k = r.IndexOf('=');
                    if (k < 0) continue;
                    string c = r.Substring(0, k), v = r.Substring(k + 1);
                    switch (c)
                    {
                        case "locator": o.Loc = v; break;
                        case "lat": o.Lat = double.Parse(v, iv); break;
                        case "lon": o.Lon = double.Parse(v, iv); break;
                        case "suolo": o.Suolo = double.Parse(v, iv); break;
                        case "antenna": o.Antenna = double.Parse(v, iv); break;
                        case "sulsuolo": o.SulSuolo = double.Parse(v, iv); break;
                        case "raggio": o.Raggio = double.Parse(v, iv); break;
                        case "k": o.K = double.Parse(v, iv); break;
                        case "hmax": o.HMax = double.Parse(v, iv); break;
                        case "passo": o.Passo = double.Parse(v, iv); break;
                        case "byte": o.Byte = long.Parse(v, iv); break;
                        case "quando": o.Quando = DateTime.ParseExact(v, "yyyy-MM-dd HH:mm", iv); break;
                        case "riquadri":
                            {
                                string[] p = v.Split(',');
                                if (p.Length >= 6) { o.Riquadri = int.Parse(p[0], iv); o.RiquadriMare = int.Parse(p[1], iv); o.LatMin = int.Parse(p[2], iv); o.LatMax = int.Parse(p[3], iv); o.LonMin = int.Parse(p[4], iv); o.LonMax = int.Parse(p[5], iv); }
                                break;
                            }
                        case "ostacolo":
                            {
                                string[] p = v.Split(';');
                                if (p.Length < 10) break;
                                Ostacolo s = new Ostacolo();
                                s.Az1 = double.Parse(p[0], iv); s.Az2 = double.Parse(p[1], iv); s.AzPicco = double.Parse(p[2], iv);
                                s.ElMax = double.Parse(p[3], iv); s.ElMin = double.Parse(p[4], iv); s.Dist = double.Parse(p[5], iv);
                                s.Lat = double.Parse(p[6], iv); s.Lon = double.Parse(p[7], iv); s.Varco = p[8] != "0"; s.Mare = p[8] == "2"; s.Nome = p[9];
                                o.Ostacoli.Add(s);
                                break;
                            }
                    }
                }
                if (el.Count < 36 || Math.Abs(el.Count * o.Passo - 360.0) > 0.01) return null;
                o.El = el.ToArray(); o.Dist = di.ToArray();
                return o;
            }
            catch { return null; }
        }

        // Calcolo completo (da eseguire fuori dal thread dell'interfaccia). raggioKm ≤ 0 = automatico.
        public static Orizzonte Calcola(string loc, double lat, double lon, double antenna, double raggioKm, double passo, double k, Action<string> stato)
        {
            return Calcola(loc, lat, lon, antenna, raggioKm, passo, k, stato, -1);
        }
        // sulSuolo ≥ 0: antenna a quell'altezza sul terreno del DEM (stazione DX, quota non nota)
        public static Orizzonte Calcola(string loc, double lat, double lon, double antenna, double raggioKm, double passo, double k, Action<string> stato, double sulSuolo)
        {
            Orizzonte o = new Orizzonte();
            o.Loc = loc; o.Lat = lat; o.Lon = lon; o.Passo = passo; o.K = k;
            double Reff = 6371000.0 * k;
            CultureInfo ci = Lang.Cultura;
            HashSet<string> fatti = new HashSet<string>();
            long byteTot = 0;
            int nTerra = 0, nMare = 0;
            int laMin = int.MaxValue, laMax = int.MinValue, loMin = int.MaxValue, loMax = int.MinValue;
            // carica tutti i riquadri entro r km (quelli entro 20 km a piena risoluzione); restituisce la quota più alta
            Func<double, double> CaricaFino = r =>
            {
                double dLat = r / 111.0, dLon = r / (111.0 * Math.Max(0.2, Math.Cos(lat * Math.PI / 180.0)));
                int a0 = (int)Math.Floor(lat - dLat), a1 = (int)Math.Floor(lat + dLat), b0 = (int)Math.Floor(lon - dLon), b1 = (int)Math.Floor(lon + dLon);
                List<int[]> elenco = new List<int[]>();
                for (int a = a0; a <= a1; a++)
                    for (int b = b0; b <= b1; b++)
                    {
                        // distanza dalla stazione al punto più vicino del riquadro
                        double cla = Math.Max(a, Math.Min(a + 1, lat)), clo = Math.Max(b, Math.Min(b + 1, lon));
                        double dy = (cla - lat) * 111.0, dx = (clo - lon) * 111.0 * Math.Cos(lat * Math.PI / 180.0);
                        double dmin = Math.Sqrt(dx * dx + dy * dy);
                        if (dmin > r) continue;
                        elenco.Add(new int[] { a, b, dmin < 20 ? 1 : 0 });
                    }
                double hm = 0;
                int nn = 0;
                foreach (int[] t in elenco)
                {
                    nn++;
                    string nome = Terreno.Nome(t[0], t[1]);
                    if (stato != null) stato(string.Format(ci, Lang.T("Riquadro {0} ({1} di {2})…"), nome, nn, elenco.Count));
                    long by = Terreno.Prepara(t[0], t[1], t[2] == 1);
                    if (!fatti.Contains(nome))
                    {
                        fatti.Add(nome);
                        if (by > 0) { nTerra++; byteTot += by; } else nMare++;
                        laMin = Math.Min(laMin, t[0]); laMax = Math.Max(laMax, t[0]); loMin = Math.Min(loMin, t[1]); loMax = Math.Max(loMax, t[1]);
                    }
                    hm = Math.Max(hm, Terreno.Massimo(t[0], t[1]));
                }
                return hm;
            };
            o.Suolo = 0;
            double raggio;
            if (raggioKm > 0)
            {
                raggio = raggioKm;
                o.HMax = CaricaFino(raggio);
                o.Suolo = Terreno.Quota(lat, lon);
            }
            else
            {
                // automatico: il raggio cresce finché il rilievo più alto trovato potrebbe ancora sporgere sopra 0°
                raggio = 60;
                o.HMax = CaricaFino(raggio);
                o.Suolo = Terreno.Quota(lat, lon);
                for (int it = 0; it < 6; it++)
                {
                    double hAnt = Math.Max(antenna, o.Suolo + 2);
                    double rr = (Math.Sqrt(2 * Reff * hAnt) + Math.Sqrt(2 * Reff * Math.Max(1, o.HMax))) / 1000.0;
                    rr = Math.Min(350, Math.Max(30, Math.Ceiling(rr / 10.0) * 10.0));
                    if (rr <= raggio + 1) { raggio = rr; break; }
                    raggio = rr;
                    o.HMax = Math.Max(o.HMax, CaricaFino(raggio));
                }
            }
            o.Raggio = raggio;
            o.Antenna = sulSuolo >= 0 ? o.Suolo + sulSuolo : Math.Max(antenna, o.Suolo + 2);
            o.SulSuolo = sulSuolo;
            o.Riquadri = nTerra; o.RiquadriMare = nMare; o.Byte = byteTot;
            o.LatMin = laMin; o.LatMax = laMax; o.LonMin = loMin; o.LonMax = loMax;
            if (stato != null) stato(Lang.T("Calcolo dell'orizzonte…"));
            int n = (int)Math.Round(360.0 / passo);
            o.El = new double[n]; o.Dist = new double[n];
            double dMax = raggio * 1000.0;
            for (int i = 0; i < n; i++)
            {
                double az = i * passo, best = -90, bestD = 0;
                double d = 90;
                while (d <= dMax)
                {
                    double la2, lo2;
                    Terreno.Destinazione(lat, lon, az, d, out la2, out lo2);
                    double h = Terreno.Quota(la2, lo2);
                    double ang = Math.Atan((h - o.Antenna) / d - d / (2 * Reff)) * 180.0 / Math.PI;
                    if (ang > best) { best = ang; bestD = d; }
                    d += Math.Max(30.0, d * 0.004);
                }
                o.El[i] = best; o.Dist[i] = bestD;
            }
            o.Quando = DateTime.UtcNow;
            o.TrovaOstacoli();
            return o;
        }

        // I tre rilievi più alti (separati da almeno 20°) e il varco più basso
        public void TrovaOstacoli()
        {
            Ostacoli.Clear();
            int n = El.Length;
            if (n == 0) return;
            bool[] preso = new bool[n];
            int sep = (int)Math.Round(20.0 / Passo);
            for (int q = 0; q < 3; q++)
            {
                int im = -1;
                for (int i = 0; i < n; i++)
                {
                    if (preso[i]) continue;
                    bool vicino = false;
                    foreach (Ostacolo o in Ostacoli) { double dd = Math.Abs(i * Passo - o.AzPicco); if (Math.Min(dd, 360 - dd) < sep * Passo) { vicino = true; break; } }
                    if (vicino) continue;
                    if (im < 0 || El[i] > El[im]) im = i;
                }
                if (im < 0 || El[im] < 0.5) break;
                // settore del rilievo: finché l'orizzonte resta vicino al picco (entro il 35 %), senza entrare negli altri
                double soglia = El[im] - Math.Max(1.0, El[im] * 0.35);
                int a = im, b = im;
                while (El[(a - 1 + n) % n] >= soglia && !preso[(a - 1 + n) % n] && (im - a) < n / 4) a--;
                while (El[(b + 1) % n] >= soglia && !preso[(b + 1) % n] && (b - im) < n / 4) b++;
                for (int k = a; k <= b; k++) preso[(k + n) % n] = true;
                Ostacolo s = new Ostacolo();
                s.Az1 = (((a * Passo) % 360) + 360) % 360; s.Az2 = (((b * Passo) % 360) + 360) % 360; s.AzPicco = im * Passo;
                s.ElMax = El[im]; s.ElMin = El[im]; s.Dist = Dist[im];
                Terreno.Destinazione(Lat, Lon, s.AzPicco, s.Dist, out s.Lat, out s.Lon);
                Ostacoli.Add(s);
            }
            // varco: il tratto più basso dell'orizzonte
            int iv = 0;
            for (int i = 1; i < n; i++) if (El[i] < El[iv]) iv = i;
            {
                double soglia = El[iv] + 0.5;
                int a = iv, b = iv;
                while (El[(a - 1 + n) % n] <= soglia && (iv - a) < n / 4) a--;
                while (El[(b + 1) % n] <= soglia && (b - iv) < n / 4) b++;
                double mx = El[iv];
                for (int k = a; k <= b; k++) mx = Math.Max(mx, El[(k + n) % n]);
                Ostacolo s = new Ostacolo();
                s.Varco = true;
                s.Az1 = (((a * Passo) % 360) + 360) % 360; s.Az2 = (((b * Passo) % 360) + 360) % 360; s.AzPicco = iv * Passo;
                s.ElMin = El[iv]; s.ElMax = mx; s.Dist = Dist[iv];
                Terreno.Destinazione(Lat, Lon, s.AzPicco, s.Dist, out s.Lat, out s.Lon);
                s.Mare = Terreno.Quota(s.Lat, s.Lon) < 1;
                // la prima terra oltre il punto che fa da orizzonte, in quella direzione (es. un'isola al largo)
                for (double d = s.Dist + 500; d <= Raggio * 1000.0; d += Math.Max(200.0, d * 0.01))
                {
                    double la, lo;
                    Terreno.Destinazione(Lat, Lon, s.AzPicco, d, out la, out lo);
                    if (Terreno.Quota(la, lo) > 3) { s.LatTerra = la; s.LonTerra = lo; break; }
                }
                Ostacoli.Add(s);
            }
        }

        // Nomi degli ostacoli da OpenStreetMap: la cima più vicina (Overpass), altrimenti il luogo (Nominatim).
        // Se la rete non risponde i nomi restano vuoti.
        public void CercaNomi()
        {
            CultureInfo iv = CultureInfo.InvariantCulture;
            foreach (Ostacolo o in Ostacoli)
            {
                string nome = "";
                try
                {
                    if (!o.Varco)
                    {
                        string q = "[out:json][timeout:20];node(around:3000," + o.Lat.ToString("F5", iv) + "," + o.Lon.ToString("F5", iv) + ")[natural=peak][name];out 20;";
                        string js = Encoding.UTF8.GetString(Dati.Scarica("https://overpass-api.de/api/interpreter?data=" + Uri.EscapeDataString(q), 25000));
                        // la cima più alta tra quelle trovate
                        double bestEle = -1;
                        foreach (System.Text.RegularExpressions.Match m in System.Text.RegularExpressions.Regex.Matches(js, "\"tags\"\\s*:\\s*\\{([^}]*)\\}"))
                        {
                            string t = m.Groups[1].Value;
                            System.Text.RegularExpressions.Match mn = System.Text.RegularExpressions.Regex.Match(t, "\"name\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");
                            if (!mn.Success) continue;
                            System.Text.RegularExpressions.Match mel = System.Text.RegularExpressions.Regex.Match(t, "\"ele\"\\s*:\\s*\"([0-9.]+)");
                            double ele = 0;
                            if (mel.Success) double.TryParse(mel.Groups[1].Value, NumberStyles.Float, iv, out ele);
                            if (ele > bestEle) { bestEle = ele; nome = System.Text.RegularExpressions.Regex.Unescape(mn.Groups[1].Value) + (ele > 0 ? " " + Math.Round(ele).ToString("0", iv) + " m" : ""); }
                        }
                    }
                }
                catch { }
                if (nome.Length == 0)
                {
                    try
                    {
                        System.Threading.Thread.Sleep(1100);   // Nominatim: al massimo una richiesta al secondo
                        double qla = o.Varco && !double.IsNaN(o.LatTerra) ? o.LatTerra : o.Lat, qlo = o.Varco && !double.IsNaN(o.LonTerra) ? o.LonTerra : o.Lon;
                        if (o.Varco && double.IsNaN(o.LatTerra)) throw new Exception("mare aperto");
                        string url = "https://nominatim.openstreetmap.org/reverse?format=jsonv2&zoom=" + (o.Varco ? "10" : "14") + "&accept-language=" + Lang.Codici[Lang.Idx]
                            + "&lat=" + qla.ToString("F5", iv) + "&lon=" + qlo.ToString("F5", iv);
                        string js = Encoding.UTF8.GetString(Dati.Scarica(url, 20000));
                        System.Text.RegularExpressions.Match mn = System.Text.RegularExpressions.Regex.Match(js, "\"name\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");
                        if (mn.Success) nome = System.Text.RegularExpressions.Regex.Unescape(mn.Groups[1].Value);
                        if (nome.Length == 0)
                        {
                            System.Text.RegularExpressions.Match ma = System.Text.RegularExpressions.Regex.Match(js, "\"(?:village|town|city|hamlet|suburb)\"\\s*:\\s*\"((?:[^\"\\\\]|\\\\.)*)\"");
                            if (ma.Success) nome = System.Text.RegularExpressions.Regex.Unescape(ma.Groups[1].Value);
                        }
                    }
                    catch { }
                }
                if (o.Varco && o.Mare)
                    nome = nome.Length > 0 ? Lang.T("mare") + ", " + string.Format(Lang.Cultura, Lang.T("varco verso {0}"), nome) : Lang.T("mare");
                else if (o.Varco && nome.Length > 0) nome = string.Format(Lang.Cultura, Lang.T("varco verso {0}"), nome);
                o.Nome = nome;
            }
        }
    }

    // Impianti dichiarati nell'intestazione dei messaggi della chat EME di N0UK (ramo "attivi" del repository,
    // tools/n0uk_attivi.py): nominativo, data, locator e impianto (es. 4X14HV/1K). Serve a «Stazioni da provare».
    // Riconoscimento del paese dal nominativo con il file cty.dat di AD1C (country-files.com).
    // Il file sta in data\cty.dat: YAEC lo scarica e lo aggiorna ogni 30 giorni; se non ci riesce, copia quello di
    // WSJT-X o di N1MM Logger+ se lo trova sul computer. Le entità solo WAE (nome con *) non si usano: conta il paese DXCC.
    static class Cty
    {
        public static readonly string[] Url = { "https://www.country-files.com/cty/cty.dat", "http://www.country-files.com/cty/cty.dat" };
        static readonly object blocco = new object();
        static Dictionary<string, string> prefissi, esatti;
        static DateTime letto = DateTime.MinValue;
        static volatile bool inCorso;

        public static string Percorso { get { return Dati.Percorso("cty.dat"); } }
        public static bool Presente { get { try { return File.Exists(Percorso); } catch { return false; } } }
        public static string Firma { get { try { return File.Exists(Percorso) ? File.GetLastWriteTimeUtc(Percorso).Ticks.ToString(CultureInfo.InvariantCulture) : "0"; } catch { return "0"; } } }

        static bool Valido(string t) { return t != null && t.Contains("EU:") && t.Contains(";") && t.Length > 20000; }

        // posti dove WSJT-X e N1MM Logger+ tengono la loro copia
        static IEnumerable<string> CopieLocali()
        {
            List<string> l = new List<string>();
            try
            {
                string la = Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData);
                string pf = Environment.GetFolderPath(Environment.SpecialFolder.ProgramFiles);
                string pf86 = Environment.GetEnvironmentVariable("ProgramFiles(x86)") ?? "";
                string doc = Environment.GetFolderPath(Environment.SpecialFolder.MyDocuments);
                string home = Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);
                l.Add(Path.Combine(la, "WSJT-X", "cty.dat"));
                l.Add(Path.Combine(@"C:\WSJT", "wsjtx", "share", "wsjtx", "cty.dat"));
                l.Add(Path.Combine(pf, "wsjtx", "share", "wsjtx", "cty.dat"));
                if (pf86.Length > 0) l.Add(Path.Combine(pf86, "wsjtx", "share", "wsjtx", "cty.dat"));
                l.Add(Path.Combine(doc, "N1MM Logger+", "SupportFiles", "cty.dat"));
                l.Add("/usr/share/wsjtx/cty.dat");
                l.Add("/usr/local/share/wsjtx/cty.dat");
                l.Add(Path.Combine(home, ".local", "share", "WSJT-X", "cty.dat"));
                l.Add("/Applications/wsjtx.app/Contents/Resources/cty.dat");
                l.Add(Path.Combine(home, "Library", "Application Support", "WSJT-X", "cty.dat"));
            }
            catch { }
            return l;
        }

        // Scarica il file se manca o ha più di 30 giorni; se non ci riesce e manca, cerca una copia locale (in silenzio)
        public static bool Aggiorna()
        {
            if (inCorso) return false;
            inCorso = true;
            try
            {
                string p = Percorso;
                if (File.Exists(p) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(p)).TotalDays < 30) return false;
                foreach (string u in Url)
                {
                    try
                    {
                        byte[] b = Dati.Scarica(u, 20000);
                        if (Valido(Encoding.ASCII.GetString(b))) { Dati.ScriviAtomico(p, b); lock (blocco) letto = DateTime.MinValue; return true; }
                    }
                    catch { }
                }
                if (File.Exists(p)) return false;
                foreach (string c in CopieLocali())
                {
                    try
                    {
                        if (!File.Exists(c)) continue;
                        byte[] b = File.ReadAllBytes(c);
                        if (!Valido(Encoding.ASCII.GetString(b))) continue;
                        Dati.ScriviAtomico(p, b);
                        // la data del file copiato: così al prossimo avvio si riprova a scaricare la versione nuova
                        try { File.SetLastWriteTimeUtc(p, File.GetLastWriteTimeUtc(c)); } catch { }
                        lock (blocco) letto = DateTime.MinValue;
                        return true;
                    }
                    catch { }
                }
                return false;
            }
            catch { return false; }
            finally { inCorso = false; }
        }

        static void Carica()
        {
            string p = Percorso;
            if (!File.Exists(p)) { prefissi = null; esatti = null; return; }
            DateTime m = File.GetLastWriteTimeUtc(p);
            if (prefissi != null && m == letto) return;
            Dictionary<string, string> pr = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            Dictionary<string, string> ex = new Dictionary<string, string>(StringComparer.OrdinalIgnoreCase);
            string t = File.ReadAllText(p, Encoding.GetEncoding(28591));
            int i = 0;
            while (i < t.Length)
            {
                int fineTesta = t.IndexOf('\n', i);
                if (fineTesta < 0) break;
                string testa = t.Substring(i, fineTesta - i).Trim();
                int fine = t.IndexOf(';', fineTesta);
                if (fine < 0) break;
                string corpo = t.Substring(fineTesta + 1, fine - fineTesta - 1);
                i = fine + 1;
                string[] campi = testa.Split(':');
                if (campi.Length < 8) continue;
                string nome = campi[0].Trim();
                string prin = campi[7].Trim();
                if (nome.Length == 0 || prin.StartsWith("*")) continue;   // entità solo WAE: si resta nel paese DXCC
                foreach (string v0 in corpo.Split(','))
                {
                    string v = v0.Trim();
                    if (v.Length == 0) continue;
                    // via le correzioni di zona, coordinate, continente e fuso: (..) [..] <..> {..} ~..~
                    v = System.Text.RegularExpressions.Regex.Replace(v, @"\(.*?\)|\[.*?\]|<.*?>|\{.*?\}|~.*?~", "").Trim();
                    if (v.Length == 0) continue;
                    if (v[0] == '=') { string c = v.Substring(1); if (c.Length > 0 && !ex.ContainsKey(c)) ex[c] = nome; }
                    else if (!pr.ContainsKey(v)) pr[v] = nome;
                }
            }
            prefissi = pr; esatti = ex; letto = m;
        }

        static readonly HashSet<string> Suffissi = new HashSet<string>(StringComparer.OrdinalIgnoreCase) { "P", "M", "MM", "AM", "QRP", "A", "B", "LH", "J", "E", "R" };

        static string Prefisso(string c)
        {
            for (int n = c.Length; n >= 1; n--)
            {
                string v;
                if (prefissi.TryGetValue(c.Substring(0, n), out v)) return v;
            }
            return null;
        }

        // Paese DXCC del nominativo (nome di cty.dat), oppure null
        public static string Paese(string call)
        {
            if (string.IsNullOrEmpty(call)) return null;
            string c = call.Trim().ToUpperInvariant();
            lock (blocco)
            {
                try { Carica(); } catch { prefissi = null; }
                if (prefissi == null) return null;
                string v;
                if (esatti.TryGetValue(c, out v)) return v;
                string[] pz = c.Split(new char[] { '/' }, StringSplitOptions.RemoveEmptyEntries);
                List<string> parti = new List<string>();
                foreach (string x in pz) if (!Suffissi.Contains(x) && !(x.Length == 1 && char.IsDigit(x[0]))) parti.Add(x);
                if (parti.Count == 0) return null;
                if (parti.Count == 1) return esatti.TryGetValue(parti[0], out v) ? v : Prefisso(parti[0]);
                // CALL/XX o XX/CALL: la parte più corta è il prefisso del paese in cui si trasmette
                string corto = parti[0].Length <= parti[1].Length ? parti[0] : parti[1];
                return Prefisso(corto);
            }
        }
    }

    static class Impianti
    {
        public const string Url = "https://raw.githubusercontent.com/ic8tem/YAEC/attivi/impianti.gz";
        static readonly object blocco = new object();
        static Dictionary<string, string[]> elenco;
        static DateTime letto = DateTime.MinValue;
        static volatile bool inCorso;

        public static string Percorso { get { return Dati.Percorso("impianti.gz"); } }
        public static string Firma { get { try { return File.Exists(Percorso) ? File.GetLastWriteTimeUtc(Percorso).Ticks.ToString(CultureInfo.InvariantCulture) : "0"; } catch { return "0"; } } }

        static Dictionary<string, string[]> Leggi(byte[] gz)
        {
            Dictionary<string, string[]> d = new Dictionary<string, string[]>(StringComparer.OrdinalIgnoreCase);
            string t;
            using (MemoryStream ms = new MemoryStream(gz))
            using (System.IO.Compression.GZipStream z = new System.IO.Compression.GZipStream(ms, System.IO.Compression.CompressionMode.Decompress))
            using (StreamReader sr = new StreamReader(z, Encoding.ASCII))
                t = sr.ReadToEnd();
            foreach (string r0 in t.Split('\n'))
            {
                string[] p = r0.Trim().Split(' ');
                if (p.Length != 4 || p[0].Length < 3) continue;
                d[p[0]] = new string[] { p[2] == "-" ? "" : p[2], p[3] == "-" ? "" : p[3] };
            }
            return d;
        }

        // Scarica l'elenco se manca o ha più di 20 ore (in silenzio)
        public static bool Aggiorna()
        {
            if (inCorso) return false;
            inCorso = true;
            try
            {
                string p = Percorso;
                if (File.Exists(p) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(p)).TotalHours < 20) return false;
                byte[] b = Dati.Scarica(Url, 20000);
                Leggi(b);
                Dati.ScriviAtomico(p, b);
                lock (blocco) letto = DateTime.MinValue;
                return true;
            }
            catch { return false; }
            finally { inCorso = false; }
        }

        // locator e impianto dichiarati dal nominativo (anche con prefisso o suffisso)
        public static bool Cerca(string call, out string loc, out string imp)
        {
            loc = ""; imp = "";
            if (string.IsNullOrEmpty(call)) return false;
            lock (blocco)
            {
                try
                {
                    string p = Percorso;
                    if (!File.Exists(p)) return false;
                    DateTime m = File.GetLastWriteTimeUtc(p);
                    if (elenco == null || m != letto) { elenco = Leggi(File.ReadAllBytes(p)); letto = m; }
                }
                catch { return false; }
                string[] v;
                string c = call.Trim().ToUpperInvariant();
                if (!elenco.TryGetValue(c, out v))
                {
                    string lungo = "";
                    foreach (string parte in c.Split('/')) if (parte.Length > lungo.Length) lungo = parte;
                    if (!elenco.TryGetValue(lungo, out v)) return false;
                }
                loc = v[0]; imp = v[1];
                return true;
            }
        }
    }

    static class Dati
    {
        public static readonly string[] FileNoti = { "impostazioni.txt", "solar-radio-flux.json", "lotw.adi" };

        // Windows: sottocartella data accanto a YAEC.exe (come sempre).
        // Linux e macOS: il programma è installato in una cartella di sola lettura, quindi la cartella data
        // sta in quella dell'utente: ~/.local/share/YAEC/data (Linux) o ~/Library/Application Support/YAEC/data (macOS).
        static string cartella;
        public static string Cartella
        {
            get
            {
                if (cartella != null) return cartella;
                if (Piattaforma.Windows) cartella = Path.Combine(Application.StartupPath, "data");
                else
                {
                    string casa = Environment.GetEnvironmentVariable("HOME") ?? Environment.GetFolderPath(Environment.SpecialFolder.Personal);
                    string baseDir;
                    if (Piattaforma.Mac) baseDir = Path.Combine(Path.Combine(Path.Combine(casa, "Library"), "Application Support"), "YAEC");
                    else
                    {
                        string xdg = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
                        baseDir = Path.Combine(string.IsNullOrEmpty(xdg) ? Path.Combine(Path.Combine(casa, ".local"), "share") : xdg, "YAEC");
                    }
                    cartella = Path.Combine(baseDir, "data");
                }
                try { Directory.CreateDirectory(cartella); } catch { }
                return cartella;
            }
        }

        public static string Percorso(string nome) { return Path.Combine(Cartella, nome); }

        static string VecchiaAppData()
        {
            try { return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData), "LunaCalc"); }
            catch { return ""; }
        }

        // Sposta un file; se in data esiste già, la copia vecchia viene eliminata (vince quella in data)
        static void SpostaFile(string da, string a)
        {
            try
            {
                if (!File.Exists(da)) return;
                Directory.CreateDirectory(Path.GetDirectoryName(a));
                if (File.Exists(a)) File.Delete(da);
                else File.Move(da, a);
            }
            catch { }
        }

        // Sposta una cartella file per file (File.Move funziona anche tra dischi diversi), poi elimina quelle vuote
        static void SpostaCartella(string da, string a)
        {
            try
            {
                if (!Directory.Exists(da)) return;
                foreach (string f in Directory.GetFiles(da, "*", SearchOption.AllDirectories))
                    SpostaFile(f, Path.Combine(a, f.Substring(da.Length).TrimStart('\\', '/')));
                EliminaVuote(da);
            }
            catch { }
        }

        static void EliminaVuote(string d)
        {
            try
            {
                foreach (string s in Directory.GetDirectories(d)) EliminaVuote(s);
                if (Directory.GetFileSystemEntries(d).Length == 0) Directory.Delete(d);
            }
            catch { }
        }

        // Da chiamare all'avvio, prima di leggere le impostazioni
        public static void Prepara()
        {
            try { Directory.CreateDirectory(Cartella); } catch { }
            try { Directory.CreateDirectory(Percorso("tiles")); } catch { }
            if (!Piattaforma.Windows) return;   // Linux e macOS: nessun dato delle versioni beta per Windows da spostare
            // v19-v21: file accanto all'eseguibile (più recenti, quindi spostati per primi)
            foreach (string n in FileNoti) SpostaFile(Path.Combine(Application.StartupPath, n), Percorso(n));
            SpostaCartella(Path.Combine(Application.StartupPath, "tiles"), Percorso("tiles"));
            // fino alla v18: AppData\Roaming\LunaCalc
            string vecchia = VecchiaAppData();
            if (vecchia.Length > 0 && Directory.Exists(vecchia))
            {
                foreach (string n in FileNoti) SpostaFile(Path.Combine(vecchia, n), Percorso(n));
                SpostaCartella(vecchia, Cartella);
                EliminaVuote(vecchia);
            }
            CorreggiPercorsoAdif(vecchia);
        }

        // Il log ADIF scaricato da LoTW si trovava nelle vecchie cartelle: il percorso salvato va aggiornato
        static void CorreggiPercorsoAdif(string vecchia)
        {
            try
            {
                string p = Percorso("impostazioni.txt");
                if (!File.Exists(p)) return;
                string[] righe = File.ReadAllLines(p);
                bool cambiato = false;
                for (int i = 0; i < righe.Length; i++)
                {
                    if (!righe[i].StartsWith("adif=")) continue;
                    string v = righe[i].Substring(5).Trim();
                    if (v.Length == 0 || File.Exists(v)) continue;
                    string dir = "";
                    try { dir = Path.GetDirectoryName(v); } catch { }
                    if (string.Equals(dir, Application.StartupPath, StringComparison.OrdinalIgnoreCase)
                        || (vecchia.Length > 0 && dir.StartsWith(vecchia, StringComparison.OrdinalIgnoreCase)))
                    {
                        string nuovo = Path.Combine(Cartella, v.Substring(dir.Length).TrimStart('\\', '/'));
                        if (File.Exists(nuovo)) { righe[i] = "adif=" + nuovo; cambiato = true; }
                    }
                }
                if (cambiato) File.WriteAllLines(p, righe, Encoding.UTF8);
            }
            catch { }
        }

        static string Impostazione(string chiave)
        {
            try
            {
                string p = Percorso("impostazioni.txt");
                if (!File.Exists(p)) return "";
                foreach (string line in File.ReadAllLines(p))
                    if (line.StartsWith(chiave + "=")) return line.Substring(chiave.Length + 1).Trim();
            }
            catch { }
            return "";
        }

        // Linux e macOS con Mono: spesso Mono non ha il suo archivio dei certificati radice (pacchetto
        // ca-certificates-mono assente) e ogni HTTPS fallisce con TrustFailure. In quel caso la catena del server
        // si verifica con le autorità radice del sistema operativo (il file PEM di /etc/ssl): la verifica resta
        // completa (nome del server, date, catena fino a una radice del sistema), cambia solo l'elenco delle radici.
        static List<System.Security.Cryptography.X509Certificates.X509Certificate2> radiciSistema;
        static HashSet<string> impronteRadici;
        static bool verificaPronta;

        internal static void PreparaVerificaCertificati()
        {
            if (Piattaforma.Windows || verificaPronta) return;
            verificaPronta = true;
            try { ServicePointManager.ServerCertificateValidationCallback = VerificaCertificato; } catch { }
        }

        static void CaricaRadici()
        {
            if (radiciSistema != null) return;
            List<System.Security.Cryptography.X509Certificates.X509Certificate2> l = new List<System.Security.Cryptography.X509Certificates.X509Certificate2>();
            HashSet<string> imp = new HashSet<string>(StringComparer.OrdinalIgnoreCase);
            string[] file = { "/etc/ssl/certs/ca-certificates.crt", "/etc/pki/tls/certs/ca-bundle.crt", "/etc/ssl/ca-bundle.pem",
                "/etc/pki/ca-trust/extracted/pem/tls-ca-bundle.pem", "/etc/ssl/cert.pem", "/usr/local/etc/openssl/cert.pem", "/opt/homebrew/etc/ca-certificates/cert.pem" };
            foreach (string f in file)
            {
                try
                {
                    if (!File.Exists(f)) continue;
                    string t = File.ReadAllText(f);
                    const string A = "-----BEGIN CERTIFICATE-----", B = "-----END CERTIFICATE-----";
                    int i = 0;
                    while ((i = t.IndexOf(A, i, StringComparison.Ordinal)) >= 0)
                    {
                        int j = t.IndexOf(B, i, StringComparison.Ordinal);
                        if (j < 0) break;
                        try
                        {
                            byte[] der = Convert.FromBase64String(t.Substring(i + A.Length, j - i - A.Length).Replace("\r", "").Replace("\n", "").Trim());
                            System.Security.Cryptography.X509Certificates.X509Certificate2 c = new System.Security.Cryptography.X509Certificates.X509Certificate2(der);
                            if (imp.Add(c.Thumbprint)) l.Add(c);
                        }
                        catch { }
                        i = j + B.Length;
                    }
                    if (l.Count > 0) break;
                }
                catch { }
            }
            impronteRadici = imp;
            radiciSistema = l;
        }

        static bool VerificaCertificato(object mittente, System.Security.Cryptography.X509Certificates.X509Certificate cert,
            System.Security.Cryptography.X509Certificates.X509Chain catena, System.Net.Security.SslPolicyErrors errori)
        {
            if (errori == System.Net.Security.SslPolicyErrors.None) return true;
            // nome del server sbagliato o certificato assente: sempre rifiutato
            if ((errori & ~System.Net.Security.SslPolicyErrors.RemoteCertificateChainErrors) != 0 || cert == null) return false;
            try
            {
                CaricaRadici();
                if (radiciSistema.Count == 0) return false;
                using (System.Security.Cryptography.X509Certificates.X509Chain c = new System.Security.Cryptography.X509Certificates.X509Chain())
                {
                    c.ChainPolicy.RevocationMode = System.Security.Cryptography.X509Certificates.X509RevocationMode.NoCheck;
                    c.ChainPolicy.VerificationFlags = System.Security.Cryptography.X509Certificates.X509VerificationFlags.AllowUnknownCertificateAuthority;
                    foreach (System.Security.Cryptography.X509Certificates.X509Certificate2 r in radiciSistema) c.ChainPolicy.ExtraStore.Add(r);
                    if (catena != null)
                        foreach (System.Security.Cryptography.X509Certificates.X509ChainElement el in catena.ChainElements) c.ChainPolicy.ExtraStore.Add(el.Certificate);
                    c.Build(new System.Security.Cryptography.X509Certificates.X509Certificate2(cert));
                    if (c.ChainElements.Count < 2) return false;
                    foreach (System.Security.Cryptography.X509Certificates.X509ChainElement el in c.ChainElements)
                        foreach (System.Security.Cryptography.X509Certificates.X509ChainStatus st in el.ChainElementStatus)
                            if (st.Status != System.Security.Cryptography.X509Certificates.X509ChainStatusFlags.NoError
                                && st.Status != System.Security.Cryptography.X509Certificates.X509ChainStatusFlags.UntrustedRoot)
                                return false;
                    // la radice della catena deve essere una delle autorità del sistema
                    return impronteRadici.Contains(c.ChainElements[c.ChainElements.Count - 1].Certificate.Thumbprint);
                }
            }
            catch { return false; }
        }

        internal static byte[] Scarica(string url, int timeoutMs)
        {
            PreparaVerificaCertificati();
            try
            {
                ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls;
            }
            catch { }
            HttpWebRequest rq = (HttpWebRequest)WebRequest.Create(url);
            rq.Timeout = timeoutMs;
            rq.ReadWriteTimeout = timeoutMs;
            rq.UserAgent = "YAEC/" + MainForm.Versione.TrimStart('v') + " (EME calculator for radio amateurs)";
            rq.CachePolicy = new System.Net.Cache.RequestCachePolicy(System.Net.Cache.RequestCacheLevel.NoCacheNoStore);
            using (WebResponse rs = rq.GetResponse())
            using (Stream st = rs.GetResponseStream())
            using (MemoryStream ms = new MemoryStream())
            {
                st.CopyTo(ms);
                return ms.ToArray();
            }
        }

        internal static void ScriviAtomico(string p, byte[] dati)
        {
            string tmp = p + ".tmp";
            File.WriteAllBytes(tmp, dati);
            if (File.Exists(p)) File.Delete(p);
            File.Move(tmp, p);
        }

        // Controllo eseguito durante la barra verde dell'avvio: ogni file mancante o non valido
        // viene preso di nuovo dalla sua fonte. stato() riceve i messaggi da mostrare.
        public static void Controlla(Action<string> stato)
        {
            stato(Lang.T("Controllo dei file nella cartella data…"));
            try
            {
                Directory.CreateDirectory(Cartella);
                Directory.CreateDirectory(Percorso("tiles"));
                string prova = Percorso("scrittura.tmp");
                File.WriteAllText(prova, "ok");
                File.Delete(prova);
            }
            catch (Exception ex)
            {
                stato(Lang.T("Impossibile scrivere nella cartella data: ") + ex.Message);
                return;
            }

            // flussi solari: mancanti, non validi o più vecchi di 12 ore
            string sfu = Percorso("solar-radio-flux.json");
            bool valido = false;
            try
            {
                if (File.Exists(sfu) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(sfu)).TotalHours < 12)
                {
                    string t = File.ReadAllText(sfu, Encoding.UTF8).TrimStart();
                    valido = t.StartsWith("[") || t.StartsWith("{");
                }
            }
            catch { valido = false; }
            if (!valido)
            {
                string url = Impostazione("sfu_url");
                if (url.Length == 0) url = MainForm.SfuUrlDefault;
                stato(Lang.T("Flusso solare: scaricamento da NOAA…"));
                try
                {
                    byte[] b = Scarica(url, 15000);
                    string t = Encoding.UTF8.GetString(b).TrimStart();
                    if (!(t.StartsWith("[") || t.StartsWith("{"))) throw new Exception("?");
                    ScriviAtomico(sfu, b);
                    stato(Lang.T("Flusso solare scaricato di nuovo da NOAA"));
                }
                catch { stato(Lang.T("Flusso solare non raggiungibile: si usano i dati salvati")); }
            }

            // log LoTW: solo se mancante e con nome utente e password memorizzati
            string lotw = Percorso("lotw.adi");
            string u = Impostazione("lotw_utente"), pw = MainForm.DecifraPassword(Impostazione("lotw_password"));
            if (!File.Exists(lotw) && u.Length > 0 && pw.Length > 0)
            {
                stato(Lang.T("Registro LoTW mancante: scaricamento in corso…"));
                try
                {
                    string url = "https://lotw.arrl.org/lotwuser/lotwreport.adi?login=" + Uri.EscapeDataString(u)
                        + "&password=" + Uri.EscapeDataString(pw)
                        + "&qso_query=1&qso_qsl=no&qso_qsldetail=yes&qso_mydetail=yes&qso_withown=yes";
                    byte[] b = Scarica(url, 180000);
                    string t = Encoding.GetEncoding(28591).GetString(b);
                    if (t.IndexOf("<eoh>", StringComparison.OrdinalIgnoreCase) < 0) throw new Exception("login");
                    ScriviAtomico(lotw, b);
                    stato(Lang.T("Registro LoTW scaricato di nuovo"));
                }
                catch { stato(Lang.T("Registro LoTW non raggiungibile")); }
            }

            // CALL3.TXT (nominativi e locator delle stazioni EME): mancante o più vecchio di 7 giorni
            if (!File.Exists(Call3.Percorso)) stato(Lang.T("CALL3.TXT mancante: scaricamento da W7GJ e WSJT-X Improved…"));
            else if ((DateTime.UtcNow - File.GetLastWriteTimeUtc(Call3.Percorso)).TotalDays >= Call3.GiorniValidita)
                stato(Lang.T("CALL3.TXT più vecchio di 7 giorni: scaricamento da W7GJ e WSJT-X Improved…"));
            stato(Call3.Aggiorna(false));
            Attivi.Aggiorna();   // stazioni attive (chat N0UK): in silenzio
            Impianti.Aggiorna(); // impianti dichiarati nella chat (Stazioni da provare): in silenzio
            Cty.Aggiorna();      // paesi dei nominativi (cty.dat di AD1C) per escludere le stazioni del mio paese
            stato(Lang.T("Cartella data pronta"));
        }
    }

    // Stazioni EME attive: nominativi che hanno scritto (o sono stati decodificati) nella chat EME di N0UK
    // negli ultimi 90 giorni. L'elenco è preparato una volta al giorno su GitHub (tools/n0uk_attivi.py,
    // ramo "attivi") e contiene solo nominativo e data dell'ultimo messaggio; il programma lo scarica
    // in data/attivi.gz e lo usa solo per bordare in arancione la casella del nominativo del DX.
    static class Attivi
    {
        public const string Url = "https://raw.githubusercontent.com/ic8tem/YAEC/attivi/attivi.gz";
        public const int Giorni = 90;
        static readonly object blocco = new object();
        static Dictionary<string, DateTime> elenco;
        static DateTime letto = DateTime.MinValue;
        static volatile bool inCorso;

        public static string Percorso { get { return Dati.Percorso("attivi.gz"); } }

        static Dictionary<string, DateTime> Leggi(byte[] gz)
        {
            Dictionary<string, DateTime> d = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
            string t;
            using (MemoryStream ms = new MemoryStream(gz))
            using (System.IO.Compression.GZipStream z = new System.IO.Compression.GZipStream(ms, System.IO.Compression.CompressionMode.Decompress))
            using (StreamReader sr = new StreamReader(z, Encoding.ASCII))
                t = sr.ReadToEnd();
            DateTime limite = DateTime.UtcNow.Date.AddDays(-Giorni);
            foreach (string r0 in t.Split('\n'))
            {
                string[] p = r0.Trim().Split(' ');
                DateTime dt;
                if (p.Length != 2 || p[0].Length < 3 || p[0].Length > 13) continue;
                if (!DateTime.TryParseExact(p[1], "yyyy-MM-dd", CultureInfo.InvariantCulture, DateTimeStyles.None, out dt)) continue;
                if (dt < limite) continue;
                DateTime pr;
                if (!d.TryGetValue(p[0], out pr) || dt > pr) d[p[0]] = dt;
            }
            return d;
        }

        // Scarica l'elenco se manca o ha più di 20 ore (in silenzio: in caso di errore resta quello salvato)
        public static bool Aggiorna()
        {
            if (inCorso) return false;
            inCorso = true;
            try
            {
                string p = Percorso;
                if (File.Exists(p) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(p)).TotalHours < 20) return false;
                byte[] b = Dati.Scarica(Url, 20000);
                Leggi(b);   // controllo: deve essere un elenco leggibile
                Dati.ScriviAtomico(p, b);
                lock (blocco) letto = DateTime.MinValue;
                return true;
            }
            catch { return false; }
            finally { inCorso = false; }
        }

        public static bool DaAggiornare
        {
            get { try { return !File.Exists(Percorso) || (DateTime.UtcNow - File.GetLastWriteTimeUtc(Percorso)).TotalHours >= 20; } catch { return false; } }
        }

        public static string Firma { get { try { return File.Exists(Percorso) ? File.GetLastWriteTimeUtc(Percorso).Ticks.ToString(CultureInfo.InvariantCulture) : "0"; } catch { return "0"; } } }

        // tutte le stazioni attive negli ultimi 90 giorni, con la data dell'ultimo messaggio
        public static Dictionary<string, DateTime> Tutti()
        {
            Dictionary<string, DateTime> r = new Dictionary<string, DateTime>(StringComparer.OrdinalIgnoreCase);
            lock (blocco)
            {
                Carica();
                if (elenco == null) return r;
                DateTime limite = DateTime.UtcNow.Date.AddDays(-Giorni);
                foreach (KeyValuePair<string, DateTime> kv in elenco) if (kv.Value >= limite) r[kv.Key] = kv.Value;
            }
            return r;
        }

        static void Carica()
        {
            try
            {
                string p = Percorso;
                if (!File.Exists(p)) { elenco = null; return; }
                DateTime m = File.GetLastWriteTimeUtc(p);
                if (elenco != null && m == letto) return;
                elenco = Leggi(File.ReadAllBytes(p));
                letto = m;
            }
            catch { elenco = null; }
        }

        // Data dell'ultimo messaggio del nominativo (anche scritto con prefisso o suffisso: IS0/DL1ABC, DL1ABC/P)
        public static bool Cerca(string call, out DateTime ultimo)
        {
            ultimo = DateTime.MinValue;
            if (string.IsNullOrEmpty(call)) return false;
            call = call.Trim().ToUpperInvariant();
            if (call.Length < 3) return false;
            lock (blocco)
            {
                Carica();
                if (elenco == null) return false;
                DateTime limite = DateTime.UtcNow.Date.AddDays(-Giorni);
                List<string> prove = new List<string> { call };
                string lungo = "";
                foreach (string parte in call.Split('/')) if (parte.Length > lungo.Length) lungo = parte;
                if (lungo != call) prove.Add(lungo);
                foreach (string c in prove)
                {
                    DateTime d;
                    if (elenco.TryGetValue(c, out d) && d >= limite && d > ultimo) ultimo = d;
                }
                return ultimo != DateTime.MinValue;
            }
        }
    }

    // CALL3.TXT: elenco nominativo → locator delle stazioni EME (quello usato da WSJT-X).
    // Due fonti: la lista curata da W7GJ e quella distribuita con WSJT-X Improved (SourceForge).
    // Si scaricano entrambe; se una non risponde si usa l'altra; se rispondono tutte e due si fondono
    // per nominativo (in caso di locator diversi vale W7GJ). Il file finale sta in data/CALL3.TXT.
    static class Call3
    {
        public const string Nome = "CALL3.TXT";
        public static readonly string[][] Fonti = {
            new string[] { "W7GJ", "http://www.bigskyspaces.com/w7gj/CALL3.TXT", "https://www.bigskyspaces.com/w7gj/call3.txt", "http://www.bigskyspaces.com/w7gj/call3.txt" },
            new string[] { "WSJT-X Improved (SourceForge)", "https://downloads.sourceforge.net/project/wsjt-x-improved/Additional%20Files/CALL3.TXT",
                "https://sourceforge.net/projects/wsjt-x-improved/files/Additional%20Files/CALL3.TXT/download",
                // ultima possibilità senza HTTPS (alcune installazioni di Mono non accettano i certificati dei mirror):
                // il contenuto viene comunque controllato riga per riga prima di usarlo
                "http://downloads.sourceforge.net/project/wsjt-x-improved/Additional%20Files/CALL3.TXT" } };
        public const int GiorniValidita = 7;

        static readonly object blocco = new object();
        static Dictionary<string, string> griglie;      // nominativo → locator
        static DateTime caricato = DateTime.MinValue;  // data del file letto
        public static volatile bool InCorso;
        public static string[] Esito = { "", "" };      // esito dell'ultimo tentativo per ciascuna fonte

        public static string Percorso { get { return Dati.Percorso(Nome); } }

        // Righe valide: "NOMINATIVO,LOCATOR,..." (le righe che iniziano con // sono commenti)
        static bool RigaValida(string riga, out string call, out string grid)
        {
            call = grid = null;
            if (riga.Length < 6 || riga.StartsWith("//")) return false;
            string[] p = riga.Split(',');
            if (p.Length < 2) return false;
            call = p[0].Trim().ToUpperInvariant();
            grid = p[1].Trim().ToUpperInvariant();
            if (call.Length < 3 || call.Length > 13 || call.IndexOf(' ') >= 0) return false;
            double la, lo;
            if (grid.Length < 4 || !Locator.TryParse(grid, out la, out lo)) return false;
            return true;
        }

        // Testo scaricato → righe valide (null se non sembra un CALL3)
        static List<string> Analizza(byte[] b)
        {
            if (b == null || b.Length < 200) return null;
            string t = Encoding.GetEncoding(28591).GetString(b);
            if (t.IndexOf("<html", StringComparison.OrdinalIgnoreCase) >= 0) return null;
            List<string> ok = new List<string>();
            string c, g;
            foreach (string r0 in t.Split('\n'))
            {
                string r = r0.Trim('\r', ' ', '\t');
                if (RigaValida(r, out c, out g)) ok.Add(r);
            }
            return ok.Count >= 50 ? ok : null;
        }

        // Scaricamento che segue a mano i rinvii (SourceForge rimanda a un mirror, anche da https a http,
        // e Mono non segue da solo quel passaggio)
        static string ultimoUrl = "";
        static byte[] ScaricaConRinvii(string url, int timeoutMs)
        {
            Dati.PreparaVerificaCertificati();
            try { ServicePointManager.SecurityProtocol = (SecurityProtocolType)3072 | (SecurityProtocolType)768 | SecurityProtocolType.Tls; } catch { }
            for (int salto = 0; salto < 8; salto++)
            {
                ultimoUrl = url;
                HttpWebRequest rq = (HttpWebRequest)WebRequest.Create(url);
                rq.Timeout = timeoutMs;
                rq.ReadWriteTimeout = timeoutMs;
                rq.AllowAutoRedirect = false;
                rq.UserAgent = "YAEC/" + MainForm.Versione.TrimStart('v') + " (EME calculator for radio amateurs)";
                HttpWebResponse rs;
                try { rs = (HttpWebResponse)rq.GetResponse(); }
                catch (WebException wex)
                {
                    rs = wex.Response as HttpWebResponse;
                    if (rs == null) throw;
                }
                using (rs)
                {
                    int code = (int)rs.StatusCode;
                    if (code >= 300 && code < 400)
                    {
                        string dove = rs.Headers["Location"];
                        if (string.IsNullOrEmpty(dove)) throw new WebException("HTTP " + code);
                        url = new Uri(new Uri(url), dove).AbsoluteUri;
                        continue;
                    }
                    if (code != 200) throw new WebException("HTTP " + code);
                    using (Stream st = rs.GetResponseStream())
                    using (MemoryStream ms = new MemoryStream())
                    {
                        st.CopyTo(ms);
                        return ms.ToArray();
                    }
                }
            }
            throw new WebException("too many redirects");
        }

        static List<string> ScaricaFonte(int i)
        {
            string errore = "";
            for (int k = 1; k < Fonti[i].Length; k++)
            {
                try
                {
                    List<string> r = Analizza(ScaricaConRinvii(Fonti[i][k], i == 0 ? 30000 : 120000));   // SourceForge: 2 MB, a volte lento
                    if (r != null) { Esito[i] = string.Format(Lang.Cultura, Lang.T("{0:N0} nominativi"), r.Count); return r; }
                    errore = "?";
                }
                catch (Exception ex)
                {
                    errore = ex.Message;
                    for (Exception x = ex.InnerException; x != null; x = x.InnerException) errore += " / " + x.Message;
                    if (ultimoUrl.Length > 0) errore += " @ " + ultimoUrl;
                }
            }
            Esito[i] = Lang.T("non raggiungibile") + (errore.Length > 0 ? " (" + errore + ")" : "");
            return null;
        }

        // Scarica e fonde; forza = ignora l'età del file. Restituisce un messaggio per l'utente.
        public static string Aggiorna(bool forza)
        {
            string p = Percorso;
            try
            {
                if (!forza && File.Exists(p) && (DateTime.UtcNow - File.GetLastWriteTimeUtc(p)).TotalDays < GiorniValidita)
                    return Lang.T("CALL3.TXT aggiornato");
            }
            catch { }
            if (InCorso) return Lang.T("CALL3.TXT: aggiornamento già in corso…");
            InCorso = true;
            try
            {
                List<string> a = ScaricaFonte(0), b = ScaricaFonte(1);
                if (a == null && b == null) return Lang.T("CALL3.TXT non raggiungibile: si usa il file salvato");
                // fusione per nominativo: prima W7GJ, poi le stazioni che mancano prese dall'altra fonte
                List<string> righe = new List<string>();
                HashSet<string> visti = new HashSet<string>();
                int diversi = 0, aggiunti = 0;
                Dictionary<string, string> ga = new Dictionary<string, string>();
                string c, g;
                if (a != null)
                    foreach (string r in a)
                        if (RigaValida(r, out c, out g) && visti.Add(c)) { righe.Add(r); ga[c] = g; }
                if (b != null)
                    foreach (string r in b)
                    {
                        if (!RigaValida(r, out c, out g)) continue;
                        string g0;
                        if (ga.TryGetValue(c, out g0)) { if (!LocatorCompatibili(g0, g)) diversi++; continue; }
                        if (visti.Add(c)) { righe.Add(r); if (a != null) aggiunti++; }
                    }
                // le correzioni fatte dall'utente valgono anche sul file appena scaricato
                righe = ApplicaCorrezioni(righe);
                righe.Sort((x, y) => string.CompareOrdinal(x, y));
                StringBuilder sb = new StringBuilder();
                string fonti = a != null && b != null ? Fonti[0][0] + " + " + Fonti[1][0] : (a != null ? Fonti[0][0] : Fonti[1][0]);
                sb.Append("// CALL3.TXT - " + righe.Count.ToString(CultureInfo.InvariantCulture) + " stations - "
                    + DateTime.UtcNow.ToString("yyyy-MM-dd", CultureInfo.InvariantCulture) + " UTC\r\n");
                sb.Append("// Sources: " + fonti + (a != null && b != null ? " (merged by callsign, W7GJ preferred)" : "") + "\r\n");
                sb.Append("// Downloaded and merged by YAEC - Yet Another EME Calc\r\n");
                sb.Append("// " + Fonti[0][0] + ": " + Esito[0] + " - " + Fonti[1][0] + ": " + Esito[1] + "\r\n");
                foreach (string r in righe) sb.Append(r).Append("\r\n");
                Dati.ScriviAtomico(p, Encoding.GetEncoding(28591).GetBytes(sb.ToString()));
                lock (blocco) { griglie = null; }
                if (a != null && b != null)
                    return string.Format(Lang.Cultura, Lang.T("CALL3.TXT aggiornato: {0:N0} nominativi da W7GJ e WSJT-X Improved ({1:N0} solo nella seconda, {2:N0} con locator diverso: vale W7GJ)"),
                        righe.Count, aggiunti, diversi);
                return string.Format(Lang.Cultura, Lang.T("CALL3.TXT aggiornato: {0:N0} nominativi (solo {1}, l'altra fonte non risponde)"), righe.Count, fonti);
            }
            catch (Exception ex) { return Lang.T("CALL3.TXT non aggiornato: ") + ex.Message; }
            finally { InCorso = false; }
        }

        // Due locator della stessa stazione sono "uguali" se il più corto è l'inizio del più lungo
        static bool LocatorCompatibili(string x, string y)
        {
            return x.StartsWith(y, StringComparison.Ordinal) || y.StartsWith(x, StringComparison.Ordinal);
        }

        static Dictionary<string, string> Tabella()
        {
            lock (blocco)
            {
                string p = Percorso;
                DateTime d = DateTime.MinValue;
                try { if (File.Exists(p)) d = File.GetLastWriteTimeUtc(p); } catch { }
                if (griglie != null && d == caricato) return griglie;
                Dictionary<string, string> t = new Dictionary<string, string>();
                try
                {
                    if (d != DateTime.MinValue)
                    {
                        string c, g;
                        foreach (string r in File.ReadAllLines(p, Encoding.GetEncoding(28591)))
                            if (RigaValida(r.Trim(), out c, out g) && !t.ContainsKey(c)) t[c] = g;
                    }
                }
                catch { }
                foreach (KeyValuePair<string, string> kv in Correzioni()) t[kv.Key] = kv.Value;   // le correzioni dell'utente prevalgono
                griglie = t; caricato = d;
                return t;
            }
        }

        // Correzioni dei locator fatte dall'utente (pulsante CORREGGI nella scheda del DX): data\call3_correzioni.txt,
        // una riga "NOMINATIVO,LOCATOR"; valgono sopra il CALL3.TXT e vengono riapplicate a ogni aggiornamento del file
        public const string NomeCorrezioni = "call3_correzioni.txt";
        static Dictionary<string, string> Correzioni()
        {
            Dictionary<string, string> d = new Dictionary<string, string>();
            try
            {
                string pc = Dati.Percorso(NomeCorrezioni);
                if (!File.Exists(pc)) return d;
                string c, g;
                foreach (string r in File.ReadAllLines(pc, Encoding.UTF8))
                    if (RigaValida(r.Trim(), out c, out g)) d[c] = g;
            }
            catch { }
            return d;
        }
        static List<string> ApplicaCorrezioni(List<string> righe)
        {
            Dictionary<string, string> cor = Correzioni();
            if (cor.Count == 0) return righe;
            List<string> out1 = new List<string>();
            HashSet<string> fatti = new HashSet<string>();
            string c, g;
            foreach (string r in righe)
            {
                string g2;
                if (RigaValida(r, out c, out g) && cor.TryGetValue(c, out g2))
                {
                    string[] pz = r.Split(',');
                    pz[1] = g2;
                    out1.Add(string.Join(",", pz));
                    fatti.Add(c);
                }
                else out1.Add(r);
            }
            foreach (KeyValuePair<string, string> kv in cor)
                if (!fatti.Contains(kv.Key)) out1.Add(kv.Key + "," + kv.Value + ",");
            return out1;
        }
        // Salva la correzione e la applica subito al CALL3.TXT (così anche la copia per WSJT-X è giusta)
        public static bool Correggi(string call, string loc)
        {
            call = (call ?? "").Trim().ToUpperInvariant(); loc = (loc ?? "").Trim().ToUpperInvariant();
            string c, g;
            if (!RigaValida(call + "," + loc, out c, out g)) return false;
            lock (blocco)
            {
                try
                {
                    Dictionary<string, string> cor = Correzioni();
                    cor[c] = g;
                    StringBuilder sb = new StringBuilder();
                    sb.Append("// YAEC: locator corretti dall'utente, applicati sopra il CALL3.TXT / locators corrected by the user\r\n");
                    foreach (KeyValuePair<string, string> kv in cor) sb.Append(kv.Key).Append(',').Append(kv.Value).Append("\r\n");
                    Dati.ScriviAtomico(Dati.Percorso(NomeCorrezioni), Encoding.UTF8.GetBytes(sb.ToString()));
                    string p = Percorso;
                    if (File.Exists(p))
                    {
                        List<string> righe = new List<string>(File.ReadAllLines(p, Encoding.GetEncoding(28591)));
                        List<string> nuove = new List<string>(), dati = new List<string>();
                        foreach (string r in righe) { if (r.StartsWith("//")) nuove.Add(r); else if (r.Trim().Length > 0) dati.Add(r.Trim()); }
                        dati = ApplicaCorrezioni(dati);
                        dati.Sort((x, y) => string.CompareOrdinal(x, y));
                        nuove.AddRange(dati);
                        Dati.ScriviAtomico(p, Encoding.GetEncoding(28591).GetBytes(string.Join("\r\n", nuove.ToArray()) + "\r\n"));
                    }
                    griglie = null;
                    return true;
                }
                catch { return false; }
            }
        }

        public static int Conteggio { get { return Tabella().Count; } }
        public static DateTime DataFile
        {
            get { try { return File.Exists(Percorso) ? File.GetLastWriteTime(Percorso) : DateTime.MinValue; } catch { return DateTime.MinValue; } }
        }

        // Locator di un nominativo (anche con prefisso o suffisso: EA8/IK1ABC, IK1ABC/P); null se assente
        public static string Cerca(string testo, out string call)
        {
            call = null;
            if (string.IsNullOrEmpty(testo)) return null;
            string t = testo.Trim().ToUpperInvariant();
            if (t.Length < 3) return null;
            Dictionary<string, string> tab = Tabella();
            if (tab.Count == 0) return null;
            string g;
            if (tab.TryGetValue(t, out g)) { call = t; return g; }
            string piu = null;
            foreach (string pz in t.Split('/'))
                if (pz.Length >= 3 && (piu == null || pz.Length > piu.Length)) piu = pz;
            if (piu != null && piu != t && tab.TryGetValue(piu, out g)) { call = piu; return g; }
            return null;
        }

        // Cartella dei dati di WSJT-X sul sistema in uso
        public static string CartellaWsjtx()
        {
            if (Piattaforma.Windows)
                return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData), "WSJT-X");
            string home = Environment.GetEnvironmentVariable("HOME") ?? Environment.GetFolderPath(Environment.SpecialFolder.Personal);
            if (Piattaforma.Mac) return Path.Combine(home, "Library", "Application Support", "WSJT-X");
            string xdg = Environment.GetEnvironmentVariable("XDG_DATA_HOME");
            return Path.Combine(string.IsNullOrEmpty(xdg) ? Path.Combine(home, ".local", "share") : xdg, "WSJT-X");
        }
    }

