            int lo = idx[0], hi = idx[idx.Count - 1];
            for (int i = 0; i < Fb.Length; i++)
            {
                if (c.Segno[i] == 'm' && c.Db[i] > 0) continue;
                c.Db[i] = Math.Round(k1 * Math.Sqrt(Fb[i]) + k2 * Fb[i], 1);
                c.Segno[i] = i > lo && i < hi ? 'i' : 'e';
            }
        }

